package com.healthdecoder.app.ui

/**
 * Static, hand-maintained translations for UI chrome — button labels, titles, empty states.
 * One map per language, keyed by the English source string. A string missing from a
 * language's map just renders in English until someone adds it here — no build step, no
 * network call.
 *
 * CHROME ONLY. A string belongs here if it can only change in an app release. Anything that
 * can change without one has no stable key to add and must not be listed here:
 *   - AI-generated content (chat answers, report summaries) — translated live via
 *     LanguageUtil/Sarvam.
 *   - Health tips — the backend's health_tips table is the source, the bundled lists are an
 *     offline seed, so a tip added to the DB tomorrow would never have an entry here.
 *   - Anything read off a scanned report (test names, doctor/lab text).
 * Those go through trDynamic() instead (see Localization.kt / DynamicTranslations), which
 * translates once at runtime and caches on-device. Adding them here instead looks like it
 * works — until the first row that wasn't hand-copied silently renders in English.
 *
 * Strings with a runtime value in them are stored as positional format templates
 * ("Check Now (%1\$d)") and rendered with trFormat(); interpolating before the lookup builds a
 * different string every call, which can never match a key.
 *
 * This covers the highest-traffic strings across the app (navigation, common actions, the
 * Medications/Reminders screen, and the AI Assistant chat screen) — it is AI-generated and
 * has NOT been reviewed by a native speaker of each language. Treat it as a functional
 * starting point, not a final translation: have a native speaker review before shipping
 * widely, and extend this map as more strings need covering (see `tr()` in Localization.kt
 * for how a missing key just falls back to English, so adding entries here is always safe).
 */
