        "Tap Settings → allow exact alarms so reminders arrive at the precise time." to "रिमाइंडर सटीक समय पर आने के लिए सेटिंग्स → सटीक अलार्म की अनुमति दें पर टैप करें।",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ऊपर \"अपॉइंटमेंट जोड़ें\" पर टैप करके डॉक्टर विज़िट या चेक-अप शेड्यूल करें। इसकी देय तारीख से पहले आपको याद दिलाया जाएगा।",
