        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "अपने डिवाइस से इमेज, PDF या डॉक चुनने के लिए यहां टैप करें, या फोटो लेने के लिए नीचे कैमरा का उपयोग करें।",
        "Tap play to hear this summary" to "इस सारांश को सुनने के लिए प्ले टैप करें",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "दवा रिमाइंडर आपके फोन और जुड़ी हुई वॉच पर दिखाई देने के लिए अनुमति देने हेतु टैप करें।",
        "Tap to pick\nImage or PDF" to "चुनने के लिए टैप करें\nइमेज या PDF",
        "Tap to select" to "चुनने के लिए टैप करें",
        "Tap to view" to "देखने के लिए टैप करें",
        "Test Parameter Changes" to "जांच पैरामीटर परिवर्तन",
        "Test group" to "जांच समूह",
        "Tested Parameters" to "परीक्षण किए गए पैरामीटर",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "प्रिस्क्रिप्शन में अनुशंसित जांच स्वतः ट्रैक की जाती हैं। आप उन्हें मैन्युअल रूप से भी जोड़ सकते हैं।",
        "That QR code doesn't contain a report link." to "उस QR कोड में कोई रिपोर्ट लिंक नहीं है।",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "सुविधा 10 मिनट के भीतर SMS/WhatsApp के माध्यम से आपके स्लॉट की पुष्टि करेगी।",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "चयनित फाइलें बहुत बड़ी हैं (%.2f MB)। इन फाइलों को प्रोसेस करने में अधिक समय लगेगा और मेमोरी समस्याएं हो सकती हैं। हम फाइलों को 10 MB से कम रखने की सलाह देते हैं। क्या आप फिर भी आगे बढ़ना चाहते हैं?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "यह वास्तविक नहीं है। इसे हटाएं, या अपने स्वयं के रिकॉर्ड ट्रैक करना शुरू करने के लिए साइन इन करें।",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "यह सभी रिपोर्ट, दवाओं, लंबित जांच और इमेज को स्थायी रूप से हटा देता है। यह पूर्ववत नहीं किया जा सकता।",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "यह मूल रूप से स्कैन की गई इमेज पर AI विश्लेषण फिर से चलाता है और नीचे निकाले गए जांच मूल्यों, दवाओं और जानकारियों को रिफ्रेश करता है। यदि पहले का स्कैन अधूरा आया था (जैसे API थोड़ी देर के लिए अनुपलब्ध था) तो यह उपयोगी है। यह आपके कुछ API कोटा का उपयोग कर सकता है।",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "इस रिपोर्ट की फाइल सेव है लेकिन AI द्वारा विश्लेषण नहीं किया गया है, इसलिए इसमें अभी तक कोई जांच मूल्य, रुझान या जानकारी नहीं है। जब भी आप तैयार हों तब इसका विश्लेषण करें (कुछ API कोटा का उपयोग करता है)।",
        "Time (HH:MM)" to "समय (HH:MM)",
        "Tip: 1-0-1 = morning & night, 1-1-1 = three times a day." to "टिप: 1-0-1 = सुबह और रात, 1-1-1 = दिन में तीन बार।",
        "Tips" to "टिप्स",
        "To" to "को",
        "Today's free pool quota is used up. Add a personal API key below for unlimited scans, or wait until tomorrow." to "आज का मुफ्त पूल कोटा समाप्त हो गया है। असीमित स्कैन के लिए नीचे एक व्यक्तिगत API कुंजी जोड़ें, या कल तक प्रतीक्षा करें।",
        "Toggle" to "टॉगल करें",
        "Toggle text" to "टॉगल पाठ",
        "Transfer Records" to "रिकॉर्ड स्थानांतरित करें",
        "Translates this intent using AI to target specific lab emails." to "विशिष्ट लैब ईमेल को लक्षित करने के लिए AI का उपयोग करके इस इरादे का अनुवाद करता है।",
        "Trend" to "रुझान",
        "Trends Overview" to "रुझान अवलोकन",
        "Trends appear once you have reports with numeric test values like TSH, sugar, hemoglobin, cholesterol." to "जब आपके पास TSH, शुगर, हीमोग्लोबिन, कोलेस्ट्रॉल जैसे संख्यात्मक जांच मूल्यों वाली रिपोर्ट होती हैं, तो रुझान दिखाई देते हैं।",
        "Try Demo" to "डेमो आज़माएं",
        "Try searching a different name" to "किसी अन्य नाम की खोज करने का प्रयास करें",
        "UHI Registered" to "UHI पंजीकृत",
        "Upcoming Appointment" to "आगामी अपॉइंटमेंट",
        "Update Password" to "पासवर्ड अपडेट करें",
        "Upload Only (No Scan)" to "केवल अपलोड करें (कोई स्कैन नहीं)",
        "Upload only" to "केवल अपलोड करें",
        "Upload two reports, prescriptions, or scans to compare what changed between them." to "उनके बीच क्या बदला यह तुलना करने के लिए दो रिपोर्ट, प्रिस्क्रिप्शन या स्कैन अपलोड करें।",
        "Uploaded — not analyzed yet" to "अपलोड किया गया — अभी तक विश्लेषण नहीं हुआ",
        "Uploaded. Open it later to analyze when you're ready." to "अपलोड हो गया। जब आप तैयार हों तब विश्लेषण के लिए इसे बाद में खोलें।",
        "Use GPS" to "GPS का उपयोग करें",
        "Use your fingerprint to quickly sign in next time without waiting for an OTP or entering passwords." to "अगली बार OTP की प्रतीक्षा किए बिना या पासवर्ड दर्ज किए बिना जल्दी साइन इन करने के लिए अपने फिंगरप्रिंट का उपयोग करें।",
        "Using your individual Gemini API key — unlimited scans, bypassing the free tier limits." to "आपकी व्यक्तिगत Gemini API कुंजी का उपयोग करते हुए — असीमित स्कैन, मुफ़्त स्तर की सीमाओं को दरकिनार करते हुए।",
        "Value" to "मूल्य",
        "Verification timed out. Please try again." to "सत्यापन का समय समाप्त हो गया। कृपया फिर से प्रयास करें।",
        "Verify & Create Account" to "सत्यापित करें और खाता बनाएं",
        "Verify & Log In" to "सत्यापित करें और लॉग इन करें",
        "View Detailed Analysis" to "विस्तृत विश्लेषण देखें",
        "View Previous Report" to "पिछली रिपोर्ट देखें",
        "View Report" to "रिपोर्ट देखें",
        "View Scanned Report" to "स्कैन की गई रिपोर्ट देखें",
