        "View existing document" to "मौजूदा दस्तावेज़ देखें",
        "Voice (Read Aloud)" to "आवाज़ (ज़ोर से पढ़ें)",
        "Voice Search" to "आवाज़ खोज",
        "Voice engine" to "आवाज़ इंजन",
        "W" to "W",
        "Waiting for UHI webhook callbacks..." to "UHI वेबहुक कॉलबैक की प्रतीक्षा हो रही है...",
        "Watch Out For:" to "इनसे सावधान रहें:",
        "Weekly Schedule" to "साप्ताहिक अनुसूची",
        "What This Report Means" to "इस रिपोर्ट का क्या मतलब है",
        "What is this medicine for?" to "यह दवा किस लिए है?",
        "Which voice reads answers aloud. Sarvam & Gemini speak Indian languages well; Phone uses your device's built-in voices (may not have Marathi)." to "कौन सी आवाज़ जवाब ज़ोर से पढ़ती है। Sarvam और Gemini भारतीय भाषाएं अच्छी तरह बोलते हैं; फोन आपके डिवाइस की अंतर्निर्मित आवाज़ों का उपयोग करता है (मराठी नहीं हो सकती)।",
        "Who is this report for?" to "यह रिपोर्ट किसके लिए है?",
        "Why It's Prescribed" to "यह क्यों निर्धारित की गई है",
        "Why is this medicine used?" to "यह दवा क्यों उपयोग की जाती है?",
        "Why is this used?" to "यह क्यों उपयोग किया जाता है?",
        "Within:" to "इसके भीतर:",
        "Yes, Import" to "हां, आयात करें",
        "You can manually correct spelling mistakes in the Patient Name, Date, or Type below. Tapping the Save (Checkmark) icon in the top right will update the history database." to "आप नीचे मरीज़ का नाम, तारीख या प्रकार में वर्तनी की गलतियों को मैन्युअल रूप से ठीक कर सकते हैं। ऊपर दाईं ओर सेव (चेकमार्क) आइकन टैप करने से इतिहास डेटाबेस अपडेट हो जाएगा।",
        "You haven't linked an email account yet. Please go to Settings (Account tab) to link your Gmail account or IMAP details first." to "आपने अभी तक कोई ईमेल खाता लिंक नहीं किया है। कृपया अपने Gmail खाते या IMAP विवरण को पहले लिंक करने के लिए सेटिंग्स (खाता टैब) पर जाएं।",
        "You're using Health Decoder without an account" to "आप बिना खाते के Health Decoder का उपयोग कर रहे हैं",
        "and set your new password." to "और अपना नया पासवर्ड सेट करें।",
        "at" to "को",
        "chars). It will be analyzed with any images." to "अक्षर)। इसे किसी भी इमेज के साथ विश्लेषण किया जाएगा।",
