        "e.g. Apollo, Metropolis, Fortis" to "उदा. अपोलो, मेट्रोपोलिस, फोर्टिस",
        "e.g. Blood Sugar Fasting (BSF)" to "उदा. ब्लड शुगर फास्टिंग (BSF)",
        "e.g. CBC, Lipid, Thyroid..." to "उदा. CBC, लिपिड, थायरॉइड...",
