        "e.g. Take with warm water" to "उदा. गुनगुने पानी के साथ लें",
        "new report(s) — check your notifications." to "नई रिपोर्ट — अपनी सूचनाएं जांचें।",
        "on" to "पर",
        "online" to "ऑनलाइन",
        "page(s) selected. Add more pages of the SAME report, then analyze." to "पेज चयनित। उसी रिपोर्ट के और पेज जोड़ें, फिर विश्लेषण करें।",
        "per scan — extra pages were skipped. Analyze these first, then scan the rest." to "प्रति स्कैन — अतिरिक्त पेज छोड़ दिए गए। पहले इनका विश्लेषण करें, फिर बाकी स्कैन करें।",
        "report(s) on file" to "रिपोर्ट फ़ाइल में हैं",
        "selected" to "चयनित",
        "starting" to "से शुरू",
        "your account" to "आपका खाता",
        "ℹ️ AI-generated reference. Always consult your doctor for medical advice." to "ℹ️ एआई-जनित संदर्भ। चिकित्सा सलाह के लिए हमेशा अपने डॉक्टर से परामर्श करें।",
        "● LIVE" to "● लाइव",
