        "📸 Identify" to "📸 पहचानें",
        "🧪 You're viewing sample demo data" to "🧪 आप नमूना डेमो डेटा देख रहे हैं",
        "Medication Reminders" to "दवा रिमाइंडर",
        "Find Doctors" to "डॉक्टर खोजें",
        "Find Hospitals" to "अस्पताल खोजें",
        "Doctor Brief" to "डॉक्टर संक्षेप",
        "Scan any medical report" to "किसी भी मेडिकल रिपोर्ट को स्कैन करें",
        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "कागज़ की लैब रिपोर्ट, प्रिस्क्रिप्शन और डिस्चार्ज सारांश को व्यवस्थित, खोजने योग्य डिजिटल रिकॉर्ड में बदलें — सीधे अपने फोन के कैमरे से।",
        "Understand it instantly" to "इसे तुरंत समझें",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI पेज पर हर जांच मूल्य, दवा और तारीख पढ़ता है, ताकि आप बिना मेडिकल शब्दजाल में उलझे रिपोर्ट का वास्तविक अर्थ देख सकें।",
        "Never miss a dose or a follow-up" to "कभी भी खुराक या फॉलो-अप न चूकें",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "दवा रिमाइंडर हर दिन सही समय पर चलते हैं — यहां तक कि सप्ताह में दो बार लेने वाली दवा के लिए भी — और डॉक्टर अपॉइंटमेंट का भी अपना रिमाइंडर होता है।",
        "What do my latest test results mean?" to "मेरे नवीनतम जांच परिणामों का क्या मतलब है?",
        "Explain my current medicines in simple words" to "मेरी वर्तमान दवाओं को सरल शब्दों में समझाएं",
        "Are any of my values abnormal?" to "क्या मेरे कोई मूल्य असामान्य हैं?",
        "What should I ask my doctor next?" to "मुझे अपने डॉक्टर से आगे क्या पूछना चाहिए?",
        "Rx" to "Rx",
        "Hospitals" to "अस्पताल",
        "Lab Tests" to "लैब जांच",
        "Doctors" to "डॉक्टर",
        "Broadcasting search to UHI gateway..." to "UHI गेटवे को खोज प्रसारित की जा रही है...",
        "Gateway ACK received. Listening for provider webhook responses..." to "गेटवे ACK प्राप्त हुआ। प्रदाता वेबहुक प्रतिक्रियाओं को सुना जा रहा है...",
        "Listening for provider webhooks... (Incoming responses)" to "प्रदाता वेबहुक सुने जा रहे हैं... (आने वाली प्रतिक्रियाएं)",
        "3M" to "3 महीने",
        "6M" to "6 महीने",
        "1Y" to "1 वर्ष",
        "2Y" to "2 वर्ष",
