        "20 km" to "20 किमी",
        "50 km" to "50 किमी",
        "Any" to "कोई भी",
        "Couldn't load your account. Check your connection and try again." to "आपका खाता लोड नहीं हो सका। अपना कनेक्शन जांचें और फिर से प्रयास करें।",
        "Please enter a valid API key or tap 'Revert to Shared Pool'." to "कृपया एक वैध API कुंजी दर्ज करें या 'शेयर्ड पूल पर वापस जाएं' पर टैप करें।",
        "Personal API Key saved! Switched to Individual Key mode." to "व्यक्तिगत API कुंजी सेव हो गई! व्यक्तिगत कुंजी मोड में बदल गया।",
        "Reverted to Primary Shared Key Pool." to "प्राइमरी शेयर्ड की पूल पर वापस जाया गया।",
        "All fields are required." to "सभी फ़ील्ड आवश्यक हैं।",
        "New password must be at least 6 characters." to "नया पासवर्ड कम से कम 6 अक्षर का होना चाहिए।",
        "Password updated successfully." to "पासवर्ड सफलतापूर्वक अपडेट हो गया।",
        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "सहायक तक नहीं पहुंच सका। जांचें कि सर्वर चल रहा है और सेटिंग्स में कॉन्फ़िगर है।",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "इस डिवाइस पर वॉइस इनपुट उपलब्ध नहीं है। कृपया Google वॉइस टाइपिंग इंस्टॉल/सक्षम करें।",
        "Couldn't generate the detailed analysis. Please try again." to "विस्तृत विश्लेषण जनरेट नहीं हो सका। कृपया फिर से प्रयास करें।",
        "Search failed. Make sure the backend server is running and database is migrated." to "खोज विफल। सुनिश्चित करें कि बैकएंड सर्वर चल रहा है और डेटाबेस माइग्रेट हो चुका है।",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "दवाइयां प्राप्त करने में विफल। सुनिश्चित करें कि आपका स्थानीय सर्वर चल रहा है और सेटिंग्स में सही ढंग से कॉन्फ़िगर है।",
        "Failed to delete the selected medicines." to "चयनित दवाओं को हटाने में विफल।",
        "Failed to update the selected medicines." to "चयनित दवाओं को अपडेट करने में विफल।",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "लंबित जांच प्राप्त करने में विफल। सुनिश्चित करें कि आपका स्थानीय सर्वर चल रहा है और सेटिंग्स में सही ढंग से कॉन्फ़िगर है।",
        "Failed to delete test reminder." to "जांच रिमाइंडर हटाने में विफल।",
        "Patient and Test names are required." to "मरीज़ और जांच के नाम आवश्यक हैं।",
        "Failed to save test reminder." to "जांच रिमाइंडर सेव करने में विफल।",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "रिकॉर्ड प्राप्त करने में विफल। सुनिश्चित करें कि आपका स्थानीय सर्वर चल रहा है और सेटिंग्स में सही ढंग से कॉन्फ़िगर है।",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "रिमाइंडर प्राप्त करने में विफल। सुनिश्चित करें कि आपका स्थानीय सर्वर चल रहा है और सेटिंग्स में सही ढंग से कॉन्फ़िगर है।",
        "Couldn't save the file." to "फ़ाइल सेव नहीं हो सकी।",
        "No app available to open this file type." to "इस फ़ाइल प्रकार को खोलने के लिए कोई ऐप उपलब्ध नहीं है।",
        "Couldn't share this file." to "इस फ़ाइल को शेयर नहीं किया जा सका।",
        "Report not found." to "रिपोर्ट नहीं मिली।",
        "Failed to load report details." to "रिपोर्ट विवरण लोड करने में विफल।",
        "Failed to save edits. Check network settings." to "संपादन सेव करने में विफल। नेटवर्क सेटिंग्स जांचें।",
        "Failed to delete report." to "रिपोर्ट हटाने में विफल।",
        "Couldn't reprocess: report or its scanned image is missing." to "पुनः प्रोसेस नहीं हो सका: रिपोर्ट या इसकी स्कैन की गई इमेज गायब है।",
        "Failed to reprocess this report." to "इस रिपोर्ट को पुनः प्रोसेस करने में विफल।",
        "Medicine name is required." to "दवा का नाम आवश्यक है।",
        "Select at least one reminder slot." to "कम से कम एक रिमाइंडर स्लॉट चुनें।",
        "Doctor name is required." to "डॉक्टर का नाम आवश्यक है।",
        "Place is required." to "स्थान आवश्यक है।",
        "Date is required." to "तारीख आवश्यक है।",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "इस डिवाइस का सुरक्षित हार्डवेयर स्टोरेज उपलब्ध नहीं है, इसलिए आपकी लोकल रिकॉर्ड्स की और लिंक्ड-ईमेल क्रेडेंशियल हार्डवेयर-बैक्ड एन्क्रिप्शन के बिना संग्रहीत हैं। आपका डेटा फिर भी असुरक्षित रूप से कहीं नहीं भेजा जाता, लेकिन यह डिवाइस सामान्य से कमज़ोर सुरक्षा प्रदान करता है।",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "स्कैनिंग, रिमाइंडर और बाकी सब कुछ इस डिवाइस पर बिना साइन इन किए पूरी तरह से काम करता है। साइन इन वैकल्पिक है (यह SMS कोड भेजता है, इसलिए यह स्वचालित नहीं है) — इसका उपयोग करें यदि आप एक प्रोफ़ाइल या व्यक्तिगत API कुंजी चाहते हैं जो डिवाइसों में आपके साथ रहे।",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "वह इकाई जिसमें हर रुझान चार्ट रीडिंग को मानकीकृत करता है। अलग इकाई वाली रिपोर्ट स्वतः बदली जाती हैं; हर रिपोर्ट अभी भी अपना मूल मूल्य दिखाती है।",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "क्यों: Health Decoder लागत कम रखकर मुफ़्त रहता है, आपके रिकॉर्ड बेचकर नहीं। यदि आप यहां शामिल होते हैं, तो केवल आपकी उम्र और लिंग — कभी भी आपका नाम, रिपोर्ट या सटीक स्थान नहीं — मेडिकल रिसर्च संस्थानों के साथ समग्र रूप से साझा किया जाएगा, ताकि ऐप को विज्ञापन चलाने या सब्सक्रिप्शन लेने के बजाय हर परिवार के लिए मुफ़्त रखने में मदद मिल सके।",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "यह कार्यक्रम अभी लॉन्च नहीं हुआ है — आज इसे चालू करने से केवल आपकी प्राथमिकता सेव होती है। जब तक वास्तविक डेटा-शेयरिंग पाइपलाइन मौजूद न हो, कुछ भी कहीं नहीं भेजा जाता, और आप कभी भी अपना उत्तर यहां बदल सकते हैं।",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "यह आपके Health Decoder खाते और इस डिवाइस पर संग्रहीत सभी मेडिकल रिकॉर्ड — रिपोर्ट, रिमाइंडर, अपॉइंटमेंट और परिवार प्रोफ़ाइल — को स्थायी रूप से हटा देता है। यह पूर्ववत नहीं किया जा सकता।",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "निर्धारित की जाती है, साथ ही मुख्य सुझाव भी। पहली बार खोज इंटरनेट का उपयोग करती है, फिर इसे सेव कर लिया जाता है ताकि अगली बार यह तुरंत खुल जाए।",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "उदाहरण रिपोर्ट, रिमाइंडर और पहले से भरी हुई अपॉइंटमेंट के साथ, ताकि आप कुछ भी वास्तविक स्कैन करने से पहले हर स्क्रीन देख सकें। इसे कभी भी खाते से हटा दें।",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "उस QR ने एक वेब पेज खोला, प्रत्यक्ष फ़ाइल नहीं। इसे आपके ब्राउज़र में खोला जा रहा है — वहां रिपोर्ट डाउनलोड करें, फिर इसे इम्पोर्ट करने के लिए \"डिवाइस से\" का उपयोग करें।",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "%1\$d बहु-पृष्ठ स्कैन उस बदलाव से पहले प्रोसेस हुए थे जिसमें बड़े दस्तावेज़ों को विश्लेषण के लिए बाँटने का तरीका ठीक किया गया — उसी दस्तावेज़ का कोई पैनल (जैसे इलेक्ट्रोलाइट्स या PT/INR पृष्ठ) छूट सकता है। यह पहले से सहेजे गए पृष्ठों से उन्हें दोबारा जाँचता है और जो छूटा था उसे जोड़ता है; जो पहले से सहेजा है वह वैसा ही रहता है।",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "%1\$d रिपोर्ट उस समय सहेजी गई थीं जब AI विश्लेषण सर्वर उपलब्ध नहीं था (जैसे दैनिक कोटा पूरा हो गया), इसलिए उनकी तारीख और श्रेणी दस्तावेज़ से पढ़ी नहीं गईं, बल्कि अनुमान हैं। दोबारा विश्लेषण पहले से सहेजी गई छवियों का उपयोग करता है — आपको उन्हें फिर से स्कैन करने की ज़रूरत नहीं।",
        "Add, edit, or remove people this device tracks — including yourself" to "इस डिवाइस पर ट्रैक किए जाने वाले लोगों को जोड़ें, संपादित करें या हटाएं — स्वयं सहित",
        "Also protect automatic backups with a password" to "स्वचालित बैकअप को भी पासवर्ड से सुरक्षित करें",
