        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restoring REPLACES everything currently on this device." to "अपने सभी रिकॉर्ड (रिपोर्ट + छवियाँ) एक ही बैकअप फ़ाइल के रूप में निर्यात करें। क्लाउड कॉपी रखने के लिए पिकर में अपना Google Drive या OneDrive फ़ोल्डर चुनें। पुनर्स्थापित करने पर इस डिवाइस पर मौजूद सब कुछ बदल दिया जाता है।",
