        "General lifestyle suggestion, not medical advice — talk to your doctor before making changes based on a lab result." to "सामान्य जीवनशैली सुझाव, चिकित्सीय सलाह नहीं — किसी लैब परिणाम के आधार पर बदलाव करने से पहले अपने डॉक्टर से बात करें।",
