        "Live camera scan — point and get instant answers" to "लाइव कैमरा स्कैन — कैमरा दिखाएँ और तुरंत जवाब पाएँ",
        "Low" to "कम",
        "Medical Report" to "मेडिकल रिपोर्ट",
        "Not set" to "सेट नहीं",
