        "Off by default — these sync to your cloud folder above without a password unless you set one here" to "डिफ़ॉल्ट रूप से बंद — ये ऊपर दिए आपके क्लाउड फ़ोल्डर में बिना पासवर्ड के सिंक होते हैं, जब तक आप यहाँ एक सेट न करें",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "प्रिस्क्रिप्शन स्कैन हो जाने के बाद, आपकी रोज़ की दवाएं यहाँ रिमाइंडर के साथ दिखेंगी।\n\nहर दवा के लिए रिमाइंडर चालू करने के लिए नीचे टॉगल दबाएँ।",
        "Optional — keeps your data available across devices" to "वैकल्पिक — आपका डेटा सभी डिवाइस पर उपलब्ध रखता है",
        "Optional — leave blank to use the shared pool" to "वैकल्पिक — साझा पूल का उपयोग करने के लिए खाली छोड़ें",
        "PERSONALIZED FOR YOU" to "आपके लिए ख़ास",
        "Passwords don't match" to "पासवर्ड मेल नहीं खाते",
        "Profile" to "प्रोफ़ाइल",
        "Protect this backup with a password" to "इस बैकअप को पासवर्ड से सुरक्षित करें",
        "Re-analyze All (%1\$d)" to "सभी का दोबारा विश्लेषण करें (%1\$d)",
        "Re-analyzing %1\$d of %2\$d…" to "%2\$d में से %1\$d का दोबारा विश्लेषण हो रहा है…",
        "Reports Needing Re-check" to "दोबारा जाँच वाली रिपोर्ट",
        "Restoring…" to "पुनर्स्थापित हो रहा है…",
        "Select gender" to "लिंग चुनें",
        "Share / Merge Records" to "रिकॉर्ड साझा करें / मर्ज करें",
        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "साझा करें / मर्ज करें चुनी हुई जानकारी दूसरे फ़ोन या डॉक्टर को भेजता है और वहाँ मौजूद डेटा में जोड़ देता है। बैकअप और पुनर्स्थापना इस डिवाइस का पूरा स्नैपशॉट है जो पुनर्स्थापित करने पर सब कुछ बदल देता है — इसे साझा करने के लिए नहीं, आपदा रिकवरी के लिए उपयोग करें।",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "अपना नाम और विवरण संपादित करने, निजी API कुंजी उपयोग करने और फ़िंगरप्रिंट लॉगिन चालू करने के लिए साइन इन करें। ऐप इसके बिना भी पूरी तरह काम करता है — आपके परिवार के सदस्य और रिकॉर्ड पहले से इसी डिवाइस पर हैं।",
        "Sign in to sync your records" to "अपने रिकॉर्ड सिंक करने के लिए साइन इन करें",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "इसे छोड़ दें तो ऐप डिफ़ॉल्ट रूप से साझा मुफ़्त पूल का उपयोग करता है। अपनी कुंजी पहले से जोड़ने का मतलब है कि आप उस पूल की दैनिक सीमा से कभी बंधे नहीं रहेंगे।",
        "Sono" to "सोनो",
        "Starts" to "शुरू",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "डॉक्टर की मुलाक़ात या जाँच तय करने के लिए ऊपर \"अपॉइंटमेंट जोड़ें\" दबाएँ। समय से पहले आपको याद दिलाया जाएगा।",
        "Tap to pick\nImage or PDF" to "चुनने के लिए दबाएँ\nछवि या PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "उस QR ने एक वेब पेज खोला, सीधी फ़ाइल नहीं। इसे आपके ब्राउज़र में खोला जा रहा है — वहाँ रिपोर्ट डाउनलोड करें, फिर उसे इंपोर्ट करने के लिए \"डिवाइस से\" का उपयोग करें।",
        "There's no way to reset this if you forget it — write it down somewhere safe." to "अगर आप इसे भूल गए तो इसे रीसेट करने का कोई तरीका नहीं है — इसे कहीं सुरक्षित लिख लें।",
        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "अगर आप इसे भूल गए तो इसे रीसेट करने का कोई तरीका नहीं है — इसे कहीं सुरक्षित लिख लें। बैकअप पासवर्ड खो जाने का मतलब है कि वह बैकअप कभी पुनर्स्थापित नहीं हो पाएगा।",
        "This backup is password-protected. Enter the password it was created with." to "यह बैकअप पासवर्ड से सुरक्षित है। वही पासवर्ड दर्ज करें जिससे इसे बनाया गया था।",
        "Try Smart Health Lens" to "स्मार्ट हेल्थ लेंस आज़माएँ",
