        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "निवडलेल्या फाइल्स खूप मोठ्या आहेत (%.2f MB). या फाइल्स प्रोसेस करण्यास जास्त वेळ लागेल आणि मेमरी समस्या येऊ शकतात. आम्ही फाइल्स 10 MB पेक्षा कमी ठेवण्याची शिफारस करतो. तुम्हाला तरीही पुढे जायचे आहे का?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "हे खरे नाही. ते काढा, किंवा तुमचे स्वतःचे रेकॉर्ड ट्रॅक करणे सुरू करण्यासाठी साइन इन करा.",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "हे सर्व रिपोर्ट्स, औषधे, प्रलंबित चाचण्या आणि इमेज कायमचे हटवते. हे पूर्ववत करता येणार नाही.",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "हे मूळ स्कॅन केलेल्या इमेजवर AI विश्लेषण पुन्हा चालवते आणि खालील काढलेली चाचणी मूल्ये, औषधे आणि माहिती रिफ्रेश करते. आधीचा स्कॅन अपूर्ण आला असल्यास (उदा. API थोडा वेळ अनुपलब्ध होते) हे उपयुक्त आहे. हे तुमच्या काही API कोट्याचा वापर करू शकते.",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "या रिपोर्टची फाइल सेव्ह आहे पण AI द्वारे विश्लेषण झालेले नाही, त्यामुळे यात अजून कोणतीही चाचणी मूल्ये, ट्रेंड किंवा माहिती नाही. तुम्ही तयार असाल तेव्हा त्याचे विश्लेषण करा (काही API कोटा वापरतो).",
        "Time (HH:MM)" to "वेळ (HH:MM)",
