        "To" to "ला",
        "Today's free pool quota is used up. Add a personal API key below for unlimited scans, or wait until tomorrow." to "आजचा मोफत पूल कोटा संपला आहे. अमर्यादित स्कॅनसाठी खाली वैयक्तिक API की जोडा, किंवा उद्यापर्यंत थांबा.",
