        "Date is required." to "तारीख आवश्यक आहे.",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "या डिव्हाइसचा सुरक्षित हार्डवेअर स्टोरेज उपलब्ध नाही, त्यामुळे तुमची लोकल रेकॉर्ड्स की आणि लिंक्ड-ईमेल क्रेडेन्शियल्स हार्डवेअर-समर्थित एन्क्रिप्शनशिवाय साठवली जातात. तुमचा डेटा तरीही असुरक्षितपणे कुठेही पाठवला जात नाही, पण हे डिव्हाइस नेहमीपेक्षा कमकुवत संरक्षण देते.",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "स्कॅनिंग, रिमाइंडर आणि बाकी सर्व काही या डिव्हाइसवर साइन इन न करता पूर्णपणे कार्य करते. साइन इन पर्यायी आहे (यामध्ये SMS कोड पाठवला जातो, त्यामुळे तो स्वयंचलित नाही) — प्रोफाइल किंवा वैयक्तिक API की हवी असल्यास याचा वापर करा जी सर्व डिव्हाइसवर तुमच्यासोबत राहते.",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "प्रत्येक ट्रेंड चार्ट ज्या युनिटमध्ये रीडिंग्ज प्रमाणित करतो. वेगळ्या युनिटमधील रिपोर्ट्स आपोआप रूपांतरित होतात; प्रत्येक रिपोर्ट अजूनही त्याचे मूळ मूल्य दाखवतो.",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "का: Health Decoder खर्च कमी ठेवून मोफत राहतो, तुमचे रेकॉर्ड विकून नाही. जर तुम्ही येथे सहभागी झालात, तर फक्त तुमचे वय आणि लिंग — कधीही तुमचे नाव, रिपोर्ट किंवा नेमके स्थान नाही — वैद्यकीय संशोधन संस्थांसोबत एकत्रितपणे शेअर केले जाईल, जेणेकरून जाहिराती चालवण्याऐवजी किंवा सबस्क्रिप्शन आकारण्याऐवजी अ‍ॅप प्रत्येक कुटुंबासाठी मोफत ठेवण्यास मदत होईल.",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "हा कार्यक्रम अद्याप सुरू झालेला नाही — आज हे चालू केल्याने फक्त तुमची पसंती सेव्ह होते. खरी डेटा-शेअरिंग पाइपलाइन अस्तित्वात येईपर्यंत काहीही कुठेही पाठवले जात नाही, आणि तुम्ही कधीही येथे तुमचे उत्तर बदलू शकता.",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "हे तुमचे Health Decoder खाते आणि या डिव्हाइसवर साठवलेले सर्व वैद्यकीय रेकॉर्ड — रिपोर्ट्स, रिमाइंडर, भेटी आणि कुटुंब प्रोफाइल्स — कायमचे हटवते. हे पूर्ववत करता येणार नाही.",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "लिहून दिली जाते, तसेच मुख्य टिपा. पहिला शोध इंटरनेट वापरतो, नंतर तो सेव्ह केला जातो जेणेकरून पुढच्या वेळी तो त्वरित उघडेल.",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "उदाहरण रिपोर्ट्स, रिमाइंडर आणि आधीच भरलेली भेट यांसह, जेणेकरून तुम्ही खरे काहीही स्कॅन करण्यापूर्वी प्रत्येक स्क्रीन एक्सप्लोर करू शकाल. खात्यामधून ते केव्हाही काढा.",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "त्या QR ने वेब पेज उघडले, थेट फाइल नाही. ते तुमच्या ब्राउझरमध्ये उघडत आहे — तेथे रिपोर्ट डाउनलोड करा, नंतर तो इम्पोर्ट करण्यासाठी \"डिव्हाइसवरून\" वापरा.",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "%1\$d बहु-पृष्ठ स्कॅन मोठे दस्तऐवज विश्लेषणासाठी विभागण्याच्या पद्धतीत सुधारणा होण्यापूर्वी प्रक्रिया केले गेले होते — त्याच दस्तऐवजातील एखादा पॅनेल (उदा. इलेक्ट्रोलाइट्स किंवा PT/INR पृष्ठ) गहाळ असू शकतो. हे आधीच जतन केलेल्या पृष्ठांचा वापर करून त्यांची पुन्हा तपासणी करते आणि जे राहिले ते जोडते; आधीच जतन केलेले तसेच राहते.",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "%1\$d अहवाल AI विश्लेषण सर्व्हर उपलब्ध नसताना जतन झाले होते (उदा. दैनिक मर्यादा संपली), त्यामुळे त्यांची तारीख आणि श्रेणी दस्तऐवजातून वाचलेली नसून अंदाज आहेत. पुन्हा विश्लेषण आधीच जतन केलेल्या प्रतिमा वापरते — तुम्हाला त्या पुन्हा स्कॅन करण्याची गरज नाही.",
