        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "विसरल्यास हा रीसेट करण्याचा कोणताही मार्ग नाही — तो कुठेतरी सुरक्षित लिहून ठेवा. बॅकअप पासवर्ड हरवला म्हणजे तो बॅकअप कधीही पुनर्संचयित होऊ शकणार नाही.",
