        "All patients" to "બધા દર્દીઓ",
        "All search results, doctor availability, and diagnostic slots are purely informational. Sourced from the public UHI network, they are not clinical recommendations or confirmed appointments. Do not rely solely on this information. Always consult a qualified medical professional for health concerns." to "બધા શોધ પરિણામો, ડોક્ટરની ઉપલબ્ધતા અને ડાયગ્નોસ્ટિક સ્લોટ ફક્ત માહિતીલક્ષી છે. જાહેર UHI નેટવર્કમાંથી મેળવેલા, તે ક્લિનિકલ ભલામણો અથવા પુષ્ટિ થયેલ એપોઇન્ટમેન્ટ નથી. ફક્ત આ માહિતી પર આધાર રાખશો નહીં. સ્વાસ્થ્ય સંબંધિત ચિંતાઓ માટે હંમેશા લાયક તબીબી વ્યાવસાયિકની સલાહ લો.",
