        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restore re-imports a backup file." to "તમારા બધા રેકોર્ડ (રિપોર્ટ + ઇમેજ) એક જ બેકઅપ ફાઇલ તરીકે એક્સપોર્ટ કરો. ક્લાઉડ કૉપિ રાખવા માટે પિકરમાં તમારું Google Drive અથવા OneDrive ફોલ્ડર પસંદ કરો. રિસ્ટોર બેકઅપ ફાઇલ ફરીથી ઇમ્પોર્ટ કરે છે.",
