        "Health Decoder requires your permission to connect to your email inbox. We will only search for emails from the last 2 days containing potential medical report attachments (PDFs) and extract them locally on your phone. No email contents are sent to our servers. Do you consent to this?" to "Health Decoder ને તમારા ઈમેલ ઇનબોક્સ સાથે કનેક્ટ થવા માટે તમારી પરવાનગી જોઈએ છે. અમે ફક્ત છેલ્લા 2 દિવસના સંભવિત મેડિકલ રિપોર્ટ જોડાણો (PDF) ધરાવતા ઈમેલ શોધીશું અને તેમને તમારા ફોન પર સ્થાનિક રીતે કાઢીશું. કોઈ ઈમેલ સામગ્રી અમારા સર્વર પર મોકલવામાં આવતી નથી. શું તમે આ માટે સંમત છો?",
