        "Signing in gives you your own free daily AI usage allowance, separate from other users of this app." to "સાઇન ઇન કરવાથી તમને આ એપના અન્ય વપરાશકારોથી અલગ તમારો પોતાનો મફત દૈનિક AI ઉપયોગ ભથ્થું મળે છે.",
