        "Smart Health Lens" to "સ્માર્ટ હેલ્થ લેન્સ",
        "Something went wrong. Check your connection and try again." to "કંઈક ખોટું થયું. તમારું કનેક્શન તપાસો અને ફરી પ્રયાસ કરો.",
        "Speak" to "બોલો",
        "Special Patient Notes" to "વિશેષ દર્દી નોંધો",
        "Start Date (YYYY-MM-DD)" to "શરૂઆતની તારીખ (YYYY-MM-DD)",
        "Stores the file without using AI — no API calls. You can analyze it anytime from its details." to "AI નો ઉપયોગ કર્યા વિના ફાઇલ સ્ટોર કરે છે — કોઈ API કૉલ નથી. તમે તેને તેની વિગતોમાંથી ગમે ત્યારે વિશ્લેષણ કરી શકો છો.",
        "Successfully initiated booking request for:" to "આ માટે બુકિંગ વિનંતી સફળતાપૂર્વક શરૂ કરવામાં આવી:",
        "Switch Profile" to "પ્રોફાઇલ સ્વિચ કરો",
        "Sync Now" to "હવે સિંક કરો",
        "System" to "સિસ્ટમ",
        "T" to "T",
        "Tap Settings → allow exact alarms so reminders arrive at the precise time." to "રિમાઇન્ડર ચોક્કસ સમયે આવે તે માટે સેટિંગ્સ → ચોક્કસ એલાર્મને મંજૂરી આપો પર ટેપ કરો.",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ડોક્ટર મુલાકાત અથવા ચેક-અપ શેડ્યૂલ કરવા ઉપર \"એપોઇન્ટમેન્ટ ઉમેરો\" પર ટેપ કરો. તે નિયત થાય તે પહેલાં તમને યાદ અપાવવામાં આવશે.",
        "Tap a medicine to expand" to "વિસ્તૃત કરવા દવા પર ટેપ કરો",
        "Tap any point to open that report" to "તે રિપોર્ટ ખોલવા કોઈપણ બિંદુ પર ટેપ કરો",
        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "તમારા ડિવાઇસમાંથી ઇમેજ, PDF અથવા ડોક પસંદ કરવા અહીં ટેપ કરો, અથવા ફોટો લેવા નીચે કૅમેરાનો ઉપયોગ કરો.",
        "Tap play to hear this summary" to "આ સારાંશ સાંભળવા પ્લે ટેપ કરો",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "દવા રિમાઇન્ડર તમારા ફોન અને જોડાયેલ વોચ પર દેખાય તે માટે મંજૂરી આપવા ટેપ કરો.",
        "Tap to pick\nImage or PDF" to "પસંદ કરવા ટેપ કરો\nઇમેજ અથવા PDF",
        "Tap to select" to "પસંદ કરવા ટેપ કરો",
        "Tap to view" to "જોવા માટે ટેપ કરો",
        "Test Parameter Changes" to "ટેસ્ટ પેરામીટર ફેરફારો",
        "Test group" to "ટેસ્ટ ગ્રુપ",
        "Tested Parameters" to "ટેસ્ટ કરેલા પેરામીટર",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "પ્રિસ્ક્રિપ્શનમાં ભલામણ કરેલ ટેસ્ટ આપમેળે ટ્રેક થાય છે. તમે તેમને મેન્યુઅલી પણ ઉમેરી શકો છો.",
        "That QR code doesn't contain a report link." to "તે QR કોડમાં રિપોર્ટ લિંક નથી.",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "સુવિધા 10 મિનિટમાં SMS/WhatsApp દ્વારા તમારા સ્લોટની પુષ્ટિ કરશે.",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "પસંદ કરેલી ફાઇલો ખૂબ મોટી છે (%.2f MB). આ ફાઇલોને પ્રોસેસ કરવામાં વધુ સમય લાગશે અને મેમરી સમસ્યાઓ થઈ શકે છે. અમે ફાઇલોને 10 MB થી ઓછી રાખવાની ભલામણ કરીએ છીએ. શું તમે તેમ છતાં આગળ વધવા માંગો છો?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "આ સાચું નથી. તેને દૂર કરો, અથવા તમારા પોતાના રેકોર્ડ ટ્રેક કરવાનું શરૂ કરવા સાઇન ઇન કરો.",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "આ બધા રિપોર્ટ, દવાઓ, બાકી ટેસ્ટ અને ઇમેજને કાયમ માટે કાઢી નાખે છે. આ પૂર્વવત્ કરી શકાતું નથી.",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "આ મૂળ સ્કેન કરેલી ઇમેજ પર AI વિશ્લેષણ ફરીથી ચલાવે છે અને નીચે કાઢેલા ટેસ્ટ મૂલ્યો, દવાઓ અને માહિતીને રિફ્રેશ કરે છે. જો પહેલાનું સ્કેન અધૂરું આવ્યું હોય (દા.ત. API થોડા સમય માટે અનુપલબ્ધ હતું) તો આ ઉપયોગી છે. તે તમારા થોડા API ક્વોટાનો ઉપયોગ કરી શકે છે.",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "આ રિપોર્ટની ફાઇલ સેવ છે પણ AI દ્વારા વિશ્લેષણ કરવામાં આવ્યું નથી, તેથી તેમાં હજુ કોઈ ટેસ્ટ મૂલ્યો, ટ્રેન્ડ કે માહિતી નથી. તમે તૈયાર હો ત્યારે તેનું વિશ્લેષણ કરો (થોડો API ક્વોટા વાપરે છે).",
        "Time (HH:MM)" to "સમય (HH:MM)",
        "Tip: 1-0-1 = morning & night, 1-1-1 = three times a day." to "ટિપ: 1-0-1 = સવાર અને રાત, 1-1-1 = દિવસમાં ત્રણ વખત.",
        "Tips" to "ટિપ્સ",
        "To" to "ને",
        "Today's free pool quota is used up. Add a personal API key below for unlimited scans, or wait until tomorrow." to "આજનો મફત પૂલ ક્વોટા વપરાઈ ગયો છે. અમર્યાદિત સ્કેન માટે નીચે વ્યક્તિગત API કી ઉમેરો, અથવા આવતીકાલ સુધી રાહ જુઓ.",
        "Toggle" to "ટૉગલ કરો",
        "Toggle text" to "ટૉગલ ટેક્સ્ટ",
        "Transfer Records" to "રેકોર્ડ ટ્રાન્સફર કરો",
        "Translates this intent using AI to target specific lab emails." to "ચોક્કસ લેબ ઈમેલને લક્ષ્ય બનાવવા AI નો ઉપયોગ કરીને આ ઇરાદાનું ભાષાંતર કરે છે.",
        "Trend" to "ટ્રેન્ડ",
        "Trends Overview" to "ટ્રેન્ડ ઝાંખી",
        "Trends appear once you have reports with numeric test values like TSH, sugar, hemoglobin, cholesterol." to "જ્યારે તમારી પાસે TSH, સુગર, હિમોગ્લોબિન, કોલેસ્ટ્રોલ જેવા સંખ્યાત્મક ટેસ્ટ મૂલ્યો ધરાવતા રિપોર્ટ હોય ત્યારે ટ્રેન્ડ દેખાય છે.",
        "Try Demo" to "ડેમો અજમાવો",
        "Try searching a different name" to "બીજું નામ શોધવાનો પ્રયાસ કરો",
        "UHI Registered" to "UHI નોંધાયેલ",
        "Unknown" to "અજ્ઞાત",
        "Upcoming Appointment" to "આગામી એપોઇન્ટમેન્ટ",
        "Update Password" to "પાસવર્ડ અપડેટ કરો",
        "Upload Only (No Scan)" to "ફક્ત અપલોડ કરો (સ્કેન નહીં)",
        "Upload only" to "ફક્ત અપલોડ કરો",
        "Upload two reports, prescriptions, or scans to compare what changed between them." to "તેમની વચ્ચે શું બદલાયું તેની સરખામણી કરવા બે રિપોર્ટ, પ્રિસ્ક્રિપ્શન અથવા સ્કેન અપલોડ કરો.",
        "Uploaded — not analyzed yet" to "અપલોડ થયું — હજુ વિશ્લેષણ થયું નથી",
        "Uploaded. Open it later to analyze when you're ready." to "અપલોડ થયું. તમે તૈયાર હો ત્યારે વિશ્લેષણ માટે તેને પછી ખોલો.",
        "Use GPS" to "GPS વાપરો",
        "Use your fingerprint to quickly sign in next time without waiting for an OTP or entering passwords." to "આગલી વખતે OTP ની રાહ જોયા વગર અથવા પાસવર્ડ દાખલ કર્યા વગર ઝડપથી સાઇન ઇન કરવા તમારી ફિંગરપ્રિન્ટનો ઉપયોગ કરો.",
        "Using your individual Gemini API key — unlimited scans, bypassing the free tier limits." to "તમારી વ્યક્તિગત Gemini API કીનો ઉપયોગ કરીને — અમર્યાદિત સ્કેન, મફત સ્તરની મર્યાદાઓને બાયપાસ કરીને.",
        "Value" to "મૂલ્ય",
        "Verification timed out. Please try again." to "વેરિફિકેશન સમય સમાપ્ત થયો. કૃપા કરીને ફરી પ્રયાસ કરો.",
