        "Which voice reads answers aloud. Sarvam & Gemini speak Indian languages well; Phone uses your device's built-in voices (may not have Marathi)." to "કયો અવાજ જવાબો મોટેથી વાંચે છે. Sarvam અને Gemini ભારતીય ભાષાઓ સારી રીતે બોલે છે; ફોન તમારા ડિવાઇસના બિલ્ટ-ઇન અવાજોનો ઉપયોગ કરે છે (મરાઠી ન પણ હોય).",
        "Who is this report for?" to "આ રિપોર્ટ કોના માટે છે?",
