        "Yes, Import" to "હા, ઇમ્પોર્ટ કરો",
        "You can manually correct spelling mistakes in the Patient Name, Date, or Type below. Tapping the Save (Checkmark) icon in the top right will update the history database." to "તમે નીચે દર્દીનું નામ, તારીખ, અથવા પ્રકારમાં જોડણીની ભૂલો જાતે સુધારી શકો છો. ઉપર જમણી બાજુના સેવ (ચેકમાર્ક) આઇકોન પર ટેપ કરવાથી ઇતિહાસ ડેટાબેઝ અપડેટ થશે.",
        "You haven't linked an email account yet. Please go to Settings (Account tab) to link your Gmail account or IMAP details first." to "તમે હજુ સુધી ઈમેલ ખાતું લિંક કર્યું નથી. કૃપા કરીને તમારા Gmail ખાતા અથવા IMAP વિગતોને પહેલા લિંક કરવા સેટિંગ્સ (ખાતા ટેબ) પર જાઓ.",
        "You're using Health Decoder without an account" to "તમે ખાતા વગર Health Decoder નો ઉપયોગ કરી રહ્યાં છો",
