        "new report(s) — check your notifications." to "નવો રિપોર્ટ(ઓ) — તમારી સૂચનાઓ તપાસો.",
        "on" to "પર",
        "online" to "ઓનલાઇન",
        "page(s) selected. Add more pages of the SAME report, then analyze." to "પેજ(ો) પસંદ કરાયા. તે જ રિપોર્ટના વધુ પેજ ઉમેરો, પછી વિશ્લેષણ કરો.",
