        "Find Hospitals" to "હોસ્પિટલ શોધો",
        "Doctor Brief" to "ડોક્ટર સારાંશ",
        "Scan any medical report" to "કોઈપણ મેડિકલ રિપોર્ટ સ્કેન કરો",
        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "કાગળના લેબ રિપોર્ટ, પ્રિસ્ક્રિપ્શન અને ડિસ્ચાર્જ સારાંશને વ્યવસ્થિત, શોધી શકાય તેવા ડિજિટલ રેકોર્ડમાં ફેરવો — સીધા તમારા ફોનના કૅમેરાથી.",
        "Understand it instantly" to "તેને તાત્કાલિક સમજો",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI પેજ પરના દરેક ટેસ્ટ મૂલ્ય, દવા અને તારીખ વાંચે છે, જેથી તમે તબીબી શબ્દજાળમાં અટવાયા વગર રિપોર્ટનો સાચો અર્થ જોઈ શકો.",
        "Never miss a dose or a follow-up" to "ક્યારેય ડોઝ અથવા ફોલો-અપ ચૂકશો નહીં",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "દવા રિમાઇન્ડર દરરોજ યોગ્ય સમયે વાગે છે — અઠવાડિયામાં બે વાર લેવાની દવા માટે પણ — અને ડોક્ટર એપોઇન્ટમેન્ટને પણ પોતાનું રિમાઇન્ડર મળે છે.",
        "What do my latest test results mean?" to "મારા નવીનતમ ટેસ્ટ પરિણામોનો અર્થ શું છે?",
