        "Personal API Key saved! Switched to Individual Key mode." to "વ્યક્તિગત API કી સેવ થઈ! વ્યક્તિગત કી મોડમાં બદલાયું.",
        "Reverted to Primary Shared Key Pool." to "પ્રાયમરી શેર્ડ કી પૂલ પર પાછા જવાયું.",
        "All fields are required." to "બધા ફીલ્ડ જરૂરી છે.",
