        "Voice input isn't available on this device. Please install/enable Google voice typing." to "આ ડિવાઇસ પર વૉઇસ ઇનપુટ ઉપલબ્ધ નથી. કૃપા કરીને Google વૉઇસ ટાઇપિંગ ઇન્સ્ટોલ/સક્ષમ કરો.",
        "Couldn't generate the detailed analysis. Please try again." to "વિગતવાર વિશ્લેષણ જનરેટ કરી શકાયું નથી. કૃપા કરીને ફરી પ્રયાસ કરો.",
        "Search failed. Make sure the backend server is running and database is migrated." to "શોધ નિષ્ફળ. ખાતરી કરો કે બેકએન્ડ સર્વર ચાલી રહ્યું છે અને ડેટાબેઝ સ્થળાંતરિત છે.",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "દવાઓ મેળવવામાં નિષ્ફળ. ખાતરી કરો કે તમારું સ્થાનિક સર્વર ચાલી રહ્યું છે અને સેટિંગ્સમાં યોગ્ય રીતે ગોઠવેલ છે.",
        "Failed to delete the selected medicines." to "પસંદ કરેલી દવાઓ કાઢી નાખવામાં નિષ્ફળ.",
        "Failed to update the selected medicines." to "પસંદ કરેલી દવાઓ અપડેટ કરવામાં નિષ્ફળ.",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "બાકી ટેસ્ટ મેળવવામાં નિષ્ફળ. ખાતરી કરો કે તમારું સ્થાનિક સર્વર ચાલી રહ્યું છે અને સેટિંગ્સમાં યોગ્ય રીતે ગોઠવેલ છે.",
        "Failed to delete test reminder." to "ટેસ્ટ રિમાઇન્ડર કાઢી નાખવામાં નિષ્ફળ.",
        "Patient and Test names are required." to "દર્દી અને ટેસ્ટના નામ જરૂરી છે.",
        "Failed to save test reminder." to "ટેસ્ટ રિમાઇન્ડર સેવ કરવામાં નિષ્ફળ.",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "રેકોર્ડ મેળવવામાં નિષ્ફળ. ખાતરી કરો કે તમારું સ્થાનિક સર્વર ચાલી રહ્યું છે અને સેટિંગ્સમાં યોગ્ય રીતે ગોઠવેલ છે.",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "રિમાઇન્ડર મેળવવામાં નિષ્ફળ. ખાતરી કરો કે તમારું સ્થાનિક સર્વર ચાલી રહ્યું છે અને સેટિંગ્સમાં યોગ્ય રીતે ગોઠવેલ છે.",
        "Couldn't save the file." to "ફાઇલ સેવ કરી શકાઈ નથી.",
        "No app available to open this file type." to "આ ફાઇલ પ્રકાર ખોલવા માટે કોઈ એપ ઉપલબ્ધ નથી.",
        "Couldn't share this file." to "આ ફાઇલ શેર કરી શકાઈ નથી.",
        "Report not found." to "રિપોર્ટ મળ્યો નથી.",
        "Failed to load report details." to "રિપોર્ટ વિગતો લોડ કરવામાં નિષ્ફળ.",
        "Failed to save edits. Check network settings." to "સંપાદનો સેવ કરવામાં નિષ્ફળ. નેટવર્ક સેટિંગ્સ તપાસો.",
        "Failed to delete report." to "રિપોર્ટ કાઢી નાખવામાં નિષ્ફળ.",
        "Couldn't reprocess: report or its scanned image is missing." to "ફરીથી પ્રોસેસ કરી શકાયું નથી: રિપોર્ટ અથવા તેની સ્કેન કરેલી ઇમેજ ગુમ છે.",
        "Failed to reprocess this report." to "આ રિપોર્ટને ફરીથી પ્રોસેસ કરવામાં નિષ્ફળ.",
        "Medicine name is required." to "દવાનું નામ જરૂરી છે.",
        "Select at least one reminder slot." to "ઓછામાં ઓછો એક રિમાઇન્ડર સ્લોટ પસંદ કરો.",
        "Doctor name is required." to "ડોક્ટરનું નામ જરૂરી છે.",
        "Place is required." to "સ્થળ જરૂરી છે.",
        "Date is required." to "તારીખ જરૂરી છે.",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "આ ડિવાઇસનો સુરક્ષિત હાર્ડવેર સ્ટોરેજ ઉપલબ્ધ નથી, તેથી તમારી લોકલ રેકોર્ડ્સ કી અને લિંક્ડ-ઈમેલ ક્રેડેન્શિયલ્સ હાર્ડવેર-બેક્ડ એન્ક્રિપ્શન વગર સંગ્રહિત છે. તમારો ડેટા હજુ પણ અસુરક્ષિત રીતે ક્યાંય મોકલવામાં આવતો નથી, પણ આ ડિવાઇસ સામાન્ય કરતાં નબળું રક્ષણ આપે છે.",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "સ્કેનિંગ, રિમાઇન્ડર અને બાકીનું બધું આ ડિવાઇસ પર સાઇન ઇન કર્યા વગર સંપૂર્ણપણે કામ કરે છે. સાઇન ઇન વૈકલ્પિક છે (તે SMS કોડ મોકલે છે, તેથી તે સ્વયંસંચાલિત નથી) — જો તમને પ્રોફાઇલ અથવા વ્યક્તિગત API કી જોઈએ જે ડિવાઇસો પર તમારી સાથે રહે તો તેનો ઉપયોગ કરો.",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "દરેક ટ્રેન્ડ ચાર્ટ જે યુનિટમાં રીડિંગ્સ પ્રમાણિત કરે છે. અલગ યુનિટવાળા રિપોર્ટ આપમેળે રૂપાંતરિત થાય છે; દરેક રિપોર્ટ હજુ પણ તેનું મૂળ મૂલ્ય બતાવે છે.",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "શા માટે: Health Decoder ખર્ચ ઓછો રાખીને મફત રહે છે, તમારા રેકોર્ડ વેચીને નહીં. જો તમે અહીં ભાગ લો છો, તો ફક્ત તમારી ઉંમર અને લિંગ — ક્યારેય તમારું નામ, રિપોર્ટ કે ચોક્કસ સ્થાન નહીં — તબીબી સંશોધન સંસ્થાઓ સાથે એકંદરે શેર કરવામાં આવશે, જેથી જાહેરાતો ચલાવવા અથવા સબ્સ્ક્રિપ્શન લેવાને બદલે એપને દરેક પરિવાર માટે મફત રાખવામાં મદદ મળે.",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "આ પ્રોગ્રામ હજુ લોન્ચ થયો નથી — આજે આ ચાલુ કરવાથી ફક્ત તમારી પસંદગી સેવ થાય છે. વાસ્તવિક ડેટા-શેરિંગ પાઇપલાઇન અસ્તિત્વમાં ન આવે ત્યાં સુધી કંઈ પણ ક્યાંય મોકલવામાં આવતું નથી, અને તમે ગમે ત્યારે અહીં તમારો જવાબ બદલી શકો છો.",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "આ તમારું Health Decoder ખાતું અને આ ડિવાઇસ પર સંગ્રહિત તમામ મેડિકલ રેકોર્ડ — રિપોર્ટ, રિમાઇન્ડર, એપોઇન્ટમેન્ટ અને કુટુંબ પ્રોફાઇલ — કાયમ માટે કાઢી નાખે છે. આ પૂર્વવત્ કરી શકાતું નથી.",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "સૂચવવામાં આવે છે, સાથે મુખ્ય ટિપ્સ. પ્રથમ શોધ ઇન્ટરનેટનો ઉપયોગ કરે છે, પછી તે સેવ થાય છે જેથી આગલી વખતે તે તરત ખૂલે.",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "ઉદાહરણ રિપોર્ટ, રિમાઇન્ડર અને પહેલેથી ભરેલી એપોઇન્ટમેન્ટ સાથે, જેથી તમે કંઈપણ વાસ્તવિક સ્કેન કરતા પહેલા દરેક સ્ક્રીન અન્વેષણ કરી શકો. તેને ખાતામાંથી ગમે ત્યારે દૂર કરો.",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "તે QR એ વેબ પેજ ખોલ્યું, સીધી ફાઇલ નહીં. તેને તમારા બ્રાઉઝરમાં ખોલવામાં આવી રહ્યું છે — ત્યાં રિપોર્ટ ડાઉનલોડ કરો, પછી તેને ઇમ્પોર્ટ કરવા \"ડિવાઇસમાંથી\" વાપરો.",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "%1\$d બહુ-પૃષ્ઠ સ્કેન મોટા દસ્તાવેજોને વિશ્લેષણ માટે વિભાજિત કરવાની રીતમાં સુધારો થયો તે પહેલાં પ્રોસેસ થયા હતા — એ જ દસ્તાવેજની કોઈ પેનલ (દા.ત. ઇલેક્ટ્રોલાઇટ્સ કે PT/INR પૃષ્ઠ) ખૂટતી હોઈ શકે. આ પહેલેથી સાચવેલા પૃષ્ઠોનો ઉપયોગ કરીને તેમને ફરી તપાસે છે અને જે ચૂકી ગયું હતું તે ઉમેરે છે; પહેલેથી સાચવેલું એમનું એમ રહે છે.",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "%1\$d રિપોર્ટ ત્યારે સાચવાયા હતા જ્યારે AI વિશ્લેષણ સર્વર ઉપલબ્ધ ન હતું (દા.ત. દૈનિક ક્વોટા પૂરો થયો), તેથી તેમની તારીખ અને શ્રેણી દસ્તાવેજમાંથી વાંચેલી નહીં પણ અનુમાન છે. ફરી વિશ્લેષણ પહેલેથી સાચવેલી છબીઓ વાપરે છે — તમારે તે ફરી સ્કેન કરવાની જરૂર નથી.",
        "Add, edit, or remove people this device tracks — including yourself" to "આ ડિવાઇસ જે લોકોને ટ્રૅક કરે છે તેમને ઉમેરો, સંપાદિત કરો કે દૂર કરો — તમારી જાત સહિત",
        "Also protect automatic backups with a password" to "સ્વચાલિત બૅકઅપને પણ પાસવર્ડથી સુરક્ષિત કરો",
        "Auto-backup password" to "સ્વતઃ-બૅકઅપ પાસવર્ડ",
        "Backup password" to "બૅકઅપ પાસવર્ડ",
        "Based on your %1\$s result (%2\$s) from your report dated %3\$s." to "%3\$s ના તમારા રિપોર્ટમાંના %1\$s પરિણામ (%2\$s) પર આધારિત.",
        "Blood" to "રક્ત",
        "Brief" to "સારાંશ",
        "Chat" to "ચેટ",
        "Check Now (%1\$d)" to "હમણાં તપાસો (%1\$d)",
        "Check for Missing Report Data" to "ખૂટતા રિપોર્ટ ડેટા માટે તપાસો",
        "Checking %1\$d of %2\$d…" to "%2\$d માંથી %1\$d તપાસાઈ રહ્યું છે…",
        "Compare" to "સરખામણી",
        "Confirm password" to "પાસવર્ડની પુષ્ટિ કરો",
        "Data Management" to "ડેટા વ્યવસ્થાપન",
        "Date of Birth (YYYY-MM-DD)" to "જન્મ તારીખ (YYYY-MM-DD)",
        "Discharge Summary" to "ડિસ્ચાર્જ સારાંશ",
        "Discharge Summary + Prescription" to "ડિસ્ચાર્જ સારાંશ + પ્રિસ્ક્રિપ્શન",
        "Echo" to "ઇકો",
        "Edit Profile" to "પ્રોફાઇલ સંપાદિત કરો",
        "Edit profile" to "પ્રોફાઇલ સંપાદિત કરો",
        "Ends" to "સમાપ્ત",
        "Enter Backup Password" to "બૅકઅપ પાસવર્ડ દાખલ કરો",
        "Every" to "દર",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restoring REPLACES everything currently on this device." to "તમારા બધા રેકોર્ડ (રિપોર્ટ + છબીઓ) એક જ બૅકઅપ ફાઇલ તરીકે નિકાસ કરો. ક્લાઉડ નકલ રાખવા માટે પિકરમાં તમારું Google Drive કે OneDrive ફોલ્ડર પસંદ કરો. પુનઃસ્થાપિત કરવાથી આ ડિવાઇસ પરનું બધું બદલાઈ જાય છે.",
        "Family Members" to "કુટુંબના સભ્યો",
        "First Name" to "પ્રથમ નામ",
        "Free Gemini API Key (Optional)" to "મફત Gemini API કી (વૈકલ્પિક)",
        "Full Backup & Restore" to "સંપૂર્ણ બૅકઅપ અને પુનઃસ્થાપન",
        "General lifestyle suggestion, not medical advice — talk to your doctor before making changes based on a lab result." to "સામાન્ય જીવનશૈલી સૂચન, તબીબી સલાહ નહીં — લેબ પરિણામના આધારે ફેરફાર કરતા પહેલાં તમારા ડૉક્ટર સાથે વાત કરો.",
        "Get Free API Key" to "મફત API કી મેળવો",
        "Got it" to "સમજાયું",
        "HEALTH TIP" to "આરોગ્ય ટિપ",
        "Health Decoder" to "હેલ્થ ડિકોડર",
        "Hello," to "નમસ્તે,",
        "High" to "ઊંચું",
        "Home" to "હોમ",
        "Last Name" to "અટક",
        "Learn More" to "વધુ જાણો",
        "Leave blank to keep the current one" to "હાલનો એ જ રાખવા માટે ખાલી છોડો",
        "Live camera scan — point and get instant answers" to "લાઇવ કૅમેરા સ્કૅન — કૅમેરા તાકો અને તરત જવાબ મેળવો",
        "Low" to "ઓછું",
        "Medical Report" to "મેડિકલ રિપોર્ટ",
        "Not set" to "સેટ નથી",
        "Not signed in" to "સાઇન ઇન નથી",
        "Off by default — these sync to your cloud folder above without a password unless you set one here" to "ડિફૉલ્ટ રૂપે બંધ — તમે અહીં પાસવર્ડ સેટ ન કરો ત્યાં સુધી આ ઉપરના તમારા ક્લાઉડ ફોલ્ડરમાં પાસવર્ડ વગર સિંક થાય છે",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "પ્રિસ્ક્રિપ્શન સ્કૅન થયા પછી, તમારી રોજિંદી દવાઓ રિમાઇન્ડર સાથે અહીં દેખાશે.\n\nદરેક દવા માટે રિમાઇન્ડર ચાલુ કરવા નીચેનું ટૉગલ દબાવો.",
        "Optional — keeps your data available across devices" to "વૈકલ્પિક — તમારો ડેટા બધા ડિવાઇસ પર ઉપલબ્ધ રાખે છે",
        "Optional — leave blank to use the shared pool" to "વૈકલ્પિક — સહિયારા પૂલનો ઉપયોગ કરવા ખાલી છોડો",
        "PERSONALIZED FOR YOU" to "તમારા માટે ખાસ",
        "Passwords don't match" to "પાસવર્ડ મેળ ખાતા નથી",
        "Profile" to "પ્રોફાઇલ",
        "Protect this backup with a password" to "આ બૅકઅપને પાસવર્ડથી સુરક્ષિત કરો",
        "Re-analyze All (%1\$d)" to "બધાનું ફરી વિશ્લેષણ કરો (%1\$d)",
        "Re-analyzing %1\$d of %2\$d…" to "%2\$d માંથી %1\$d નું ફરી વિશ્લેષણ થઈ રહ્યું છે…",
        "Reports Needing Re-check" to "ફરી તપાસ જરૂરી હોય તેવા રિપોર્ટ",
        "Restoring…" to "પુનઃસ્થાપિત થઈ રહ્યું છે…",
        "Select gender" to "લિંગ પસંદ કરો",
        "Share / Merge Records" to "રેકોર્ડ શેર કરો / મર્જ કરો",
        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "શેર / મર્જ પસંદ કરેલી માહિતી બીજા ફોન કે ડૉક્ટરને મોકલે છે અને ત્યાં જે છે તેમાં ઉમેરે છે. બૅકઅપ અને પુનઃસ્થાપન એ આ ડિવાઇસનો સંપૂર્ણ સ્નૅપશૉટ છે જે પુનઃસ્થાપિત કરતાં બધું બદલી નાખે છે — તેને શેર કરવા માટે નહીં, આપત્તિ પુનઃપ્રાપ્તિ માટે વાપરો.",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "તમારું નામ અને વિગતો સંપાદિત કરવા, વ્યક્તિગત API કી વાપરવા અને ફિંગરપ્રિન્ટ લૉગિન ચાલુ કરવા સાઇન ઇન કરો. તેના વગર પણ ઍપ સંપૂર્ણ કામ કરે છે — તમારા કુટુંબના સભ્યો અને રેકોર્ડ પહેલેથી આ જ ડિવાઇસ પર છે.",
        "Sign in to sync your records" to "તમારા રેકોર્ડ સિંક કરવા સાઇન ઇન કરો",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "આ છોડી દો તો ઍપ ડિફૉલ્ટ રૂપે સહિયારા મફત પૂલનો ઉપયોગ કરે છે. પોતાની કી પહેલેથી ઉમેરવાનો અર્થ છે કે તમે એ પૂલની દૈનિક મર્યાદાથી ક્યારેય બંધાયેલા નહીં રહો.",
        "Sono" to "સોનો",
        "Starts" to "શરૂ",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ડૉક્ટરની મુલાકાત કે ચેક-અપ ગોઠવવા ઉપર \"અપોઇન્ટમેન્ટ ઉમેરો\" દબાવો. સમય પહેલાં તમને યાદ કરાવવામાં આવશે.",
        "Tap to pick\nImage or PDF" to "પસંદ કરવા દબાવો\nછબી કે PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "એ QR એ વેબ પેજ ખોલ્યું, સીધી ફાઇલ નહીં. તેને તમારા બ્રાઉઝરમાં ખોલવામાં આવે છે — ત્યાં રિપોર્ટ ડાઉનલોડ કરો, પછી તેને આયાત કરવા \"ડિવાઇસમાંથી\" વાપરો.",
        "There's no way to reset this if you forget it — write it down somewhere safe." to "ભૂલી જાઓ તો આને રીસેટ કરવાનો કોઈ રસ્તો નથી — તેને ક્યાંક સુરક્ષિત લખી રાખો.",
        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "ભૂલી જાઓ તો આને રીસેટ કરવાનો કોઈ રસ્તો નથી — તેને ક્યાંક સુરક્ષિત લખી રાખો. બૅકઅપ પાસવર્ડ ખોવાય તો એ બૅકઅપ ક્યારેય પુનઃસ્થાપિત થઈ શકશે નહીં.",
        "This backup is password-protected. Enter the password it was created with." to "આ બૅકઅપ પાસવર્ડથી સુરક્ષિત છે. જે પાસવર્ડથી તે બનાવાયો હતો તે જ દાખલ કરો.",
        "Try Smart Health Lens" to "સ્માર્ટ હેલ્થ લેન્સ અજમાવો",
        "Welcome" to "સ્વાગત છે",
        "Without one, anyone who gets the backup file can open it" to "તેના વગર, જેને પણ બૅકઅપ ફાઇલ મળે તે તેને ખોલી શકે છે",
        "Your Profile" to "તમારી પ્રોફાઇલ",
        "➕ Add family member" to "➕ કુટુંબનો સભ્ય ઉમેરો"
    )

