        "All medications extracted from prescriptions will show up here along with their dosage history." to "மருந்துச் சீட்டுகளிலிருந்து பிரித்தெடுக்கப்பட்ட அனைத்து மருந்துகளும் அவற்றின் அளவு வரலாற்றுடன் இங்கு காட்டப்படும்.",
        "All patients" to "அனைத்து நோயாளிகளும்",
        "All search results, doctor availability, and diagnostic slots are purely informational. Sourced from the public UHI network, they are not clinical recommendations or confirmed appointments. Do not rely solely on this information. Always consult a qualified medical professional for health concerns." to "அனைத்து தேடல் முடிவுகள், மருத்துவர் கிடைக்கும் தன்மை மற்றும் நோயறிதல் இடங்கள் தகவலுக்காக மட்டுமே. பொது UHI நெட்வொர்க்கிலிருந்து பெறப்பட்டவை, இவை மருத்துவ பரிந்துரைகள் அல்லது உறுதிசெய்யப்பட்ட நியமனங்கள் அல்ல. இந்தத் தகவலை மட்டுமே நம்பாதீர்கள். உடல்நல கவலைகளுக்கு எப்போதும் தகுதிவாய்ந்த மருத்துவரை அணுகவும்.",
        "Analysing your report…" to "உங்கள் அறிக்கை பகுப்பாய்வு செய்யப்படுகிறது…",
        "Analyze & Scan Document" to "ஆவணத்தை பகுப்பாய்வு செய்து ஸ்கேன் செய்யவும்",
        "Analyze Now" to "இப்போது பகுப்பாய்வு செய்யவும்",
        "Analyzing & Comparing..." to "பகுப்பாய்வு & ஒப்பீடு நடைபெறுகிறது...",
        "Analyzing image text..." to "படத்தின் உரையை பகுப்பாய்வு செய்கிறது...",
        "App Password / Password" to "ஆப் கடவுச்சொல் / கடவுச்சொல்",
