        "Are you sure you want to delete this medical report? This will permanently remove the record from your database and delete the uploaded image file." to "இந்த மருத்துவ அறிக்கையை நீக்க வேண்டுமா? இது உங்கள் தரவுத்தளத்திலிருந்து பதிவை நிரந்தரமாக அகற்றி, பதிவேற்றப்பட்ட படக்கோப்பையும் நீக்கும்.",
        "Ask by typing or tap the mic to speak" to "தட்டச்சு செய்து கேளுங்கள் அல்லது பேச மைக்கை தட்டவும்",
        "Asking about: " to "இதைப் பற்றி கேட்கிறது: ",
