        "Based on your latest uploaded reports, here is what has changed and the differences:" to "உங்கள் சமீபத்திய பதிவேற்றப்பட்ட அறிக்கைகளின் அடிப்படையில், என்ன மாறியது மற்றும் வேறுபாடுகள் இங்கே:",
