        "Export a shareable file of your records (with analysis included) to send to another phone or a doctor. Importing merges it into this phone and never re-runs the AI, so it's free." to "மற்றொரு தொலைபேசிக்கு அல்லது மருத்துவருக்கு அனுப்ப உங்கள் பதிவுகளின் பகிரக்கூடிய கோப்பை (பகுப்பாய்வுடன்) ஏற்றுமதி செய்யவும். இறக்குமதி செய்வது இதை இந்த தொலைபேசியில் இணைக்கிறது, AI-ஐ மீண்டும் இயக்காது, எனவே இது இலவசம்.",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restore re-imports a backup file." to "உங்கள் அனைத்து பதிவுகளையும் (அறிக்கைகள் + படங்கள்) ஒரே காப்புப்பிரதி கோப்பாக ஏற்றுமதி செய்யவும். கிளவுட் நகலை வைத்திருக்க பிக்கரில் உங்கள் Google Drive அல்லது OneDrive கோப்புறையைத் தேர்ந்தெடுக்கவும். மீட்டமைப்பது காப்புப்பிரதி கோப்பை மீண்டும் இறக்குமதி செய்யும்.",
