        "Finds reports that were saved more than once (same patient, date, and content) and removes the extra copies. The original of each report is always kept. New scans are checked automatically; this cleans up older duplicates." to "ஒன்றுக்கு மேற்பட்ட முறை சேமிக்கப்பட்ட அறிக்கைகளை (அதே நோயாளி, தேதி, உள்ளடக்கம்) கண்டறிந்து கூடுதல் நகல்களை அகற்றுகிறது. ஒவ்வொரு அறிக்கையின் மூலப்பிரதியும் எப்போதும் வைக்கப்படும். புதிய ஸ்கேன்கள் தானாக சரிபார்க்கப்படும்; இது பழைய நகல்களை சுத்தம் செய்யும்.",
