        "No medication history" to "மருந்து வரலாறு இல்லை",
        "No medications extracted." to "மருந்துகள் எதுவும் பிரித்தெடுக்கப்படவில்லை.",
        "No new reports found (already scanned or none available)." to "புதிய அறிக்கைகள் எதுவும் கிடைக்கவில்லை (ஏற்கனவே ஸ்கேன் செய்யப்பட்டது அல்லது கிடைக்கவில்லை).",
        "No new reports found in the last 2 days." to "கடந்த 2 நாட்களில் புதிய அறிக்கைகள் எதுவும் கிடைக்கவில்லை.",
        "No numeric values to chart." to "விரைபடத்திற்கு எண் மதிப்புகள் இல்லை.",
        "No patients yet" to "இதுவரை நோயாளிகள் இல்லை",
        "No previous export yet — this sends everything" to "முந்தைய ஏற்றுமதி இல்லை — இது அனைத்தையும் அனுப்பும்",
        "No recorded logs for this medicine yet." to "இந்த மருந்திற்கு இதுவரை பதிவுகள் இல்லை.",
        "No saved fingerprint credentials found." to "சேமிக்கப்பட்ட கைரேகை நற்சான்றிதழ்கள் இல்லை.",
        "No test values to chart" to "விரைபடத்திற்கு பரிசோதனை மதிப்புகள் இல்லை",
        "No timeline specified" to "காலவரிசை குறிப்பிடப்படவில்லை",
