        "Normal" to "இயல்பான",
        "Not Now" to "இப்போது வேண்டாம்",
        "Not enough comparable data found between the two reports." to "இரண்டு அறிக்கைகளுக்கும் இடையே போதுமான ஒப்பிடக்கூடிய தரவு இல்லை.",
        "Not now" to "இப்போது வேண்டாம்",
        "Not selected" to "தேர்ந்தெடுக்கப்படவில்லை",
        "Note: Gmail, Yahoo, and Outlook require you to generate an 'App Password' from your account security settings to log in via IMAP." to "குறிப்பு: Gmail, Yahoo, Outlook ஆகியவை IMAP வழியாக உள்நுழைய உங்கள் கணக்கு பாதுகாப்பு அமைப்புகளிலிருந்து 'ஆப் கடவுச்சொல்' உருவாக்க வேண்டும்.",
        "Observations / Impressions:" to "அவதானிப்புகள் / எண்ணங்கள்:",
        "Offline summary (set GEMINI_API_KEY for full AI analysis)" to "ஆஃப்லைன் சுருக்கம் (முழு AI பகுப்பாய்விற்கு GEMINI_API_KEY அமைக்கவும்)",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "மருந்துச்சீட்டுகள் ஸ்கேன் செய்யப்பட்டவுடன், உங்கள் தினசரி மருந்துகள் நினைவூட்டல்களுடன் இங்கே தோன்றும்.\n\nஒவ்வொரு மருந்திற்கும் நினைவூட்டல்களை இயக்க கீழே உள்ள மாற்றியை தட்டவும்.",
        "One-off" to "ஒரு முறை",
