        "Only" to "மட்டும்",
        "Only new since last export" to "கடைசி ஏற்றுமதிக்குப் பிறகு புதியவை மட்டும்",
        "Open" to "திற",
        "Optional / As Needed" to "விருப்பம் / தேவைக்கேற்ப",
        "Or sign in with another method" to "அல்லது வேறு முறையில் உள்நுழையவும்",
        "Original file(s)" to "மூலக் கோப்பு(கள்)",
        "Other (IMAP)" to "மற்றவை (IMAP)",
        "Overall:" to "மொத்தமாக:",
        "Overview" to "கண்ணோட்டம்",
        "Page" to "பக்கம்",
        "Page limit is" to "பக்க வரம்பு",
        "Parameter" to "அளவுரு",
        "Parameter Changes:" to "அளவுரு மாற்றங்கள்:",
        "Password must be at least 6 characters." to "கடவுச்சொல் குறைந்தது 6 எழுத்துகள் இருக்க வேண்டும்.",
        "Password reset successfully. Log in with your new password." to "கடவுச்சொல் வெற்றிகரமாக மீட்டமைக்கப்பட்டது. உங்கள் புதிய கடவுச்சொல்லுடன் உள்நுழையவும்.",
        "Passwords do not match." to "கடவுச்சொற்கள் பொருந்தவில்லை.",
        "Permanently removes every report, medicine, pending test and image. This cannot be undone." to "ஒவ்வொரு அறிக்கை, மருந்து, நிலுவை பரிசோதனை மற்றும் படத்தையும் நிரந்தரமாக அகற்றுகிறது. இதை மீட்டெடுக்க முடியாது.",
        "Phone OTP" to "தொலைபேசி OTP",
        "Pick a folder in Google Drive, OneDrive, or Dropbox. New backups are automatically synced there by the cloud app." to "Google Drive, OneDrive அல்லது Dropbox இல் ஒரு கோப்புறையைத் தேர்ந்தெடுக்கவும். புதிய காப்புப்பிரதிகள் அங்கு கிளவுட் ஆப் மூலம் தானாக ஒத்திசைக்கப்படும்.",
        "Place / Clinic Name" to "இடம் / மருத்துவமனை பெயர்",
        "Plan:" to "திட்டம்:",
