        "Please link your Google Account first." to "முதலில் உங்கள் Google கணக்கை இணைக்கவும்.",
        "Point camera at a medicine strip to instantly identify it, see usage instructions, and check for interactions." to "மருந்து ஸ்ட்ரிப் மீது கேமராவை காட்டவும், உடனடியாக அடையாளம் காண, பயன்பாட்டு வழிமுறைகளைப் பார்க்க, மற்றும் இடையீடுகளைச் சரிபார்க்க.",
        "Point the camera at the QR code printed on the report" to "அறிக்கையில் அச்சிடப்பட்ட QR குறியீட்டில் கேமராவைக் காட்டவும்",
        "Preferred Language" to "விருப்பமான மொழி",
