        "Scan Mode: English (Google Scan + Gemini)" to "ஸ்கேன் பயன்முறை: ஆங்கிலம் (Google ஸ்கேன் + Gemini)",
        "Scan Mode: Regional / Indic Script (Sarvam AI)" to "ஸ்கேன் பயன்முறை: பிராந்திய / இந்திய எழுத்து (Sarvam AI)",
