        "Scan started — watch the progress above." to "ஸ்கேன் தொடங்கியது — மேலே முன்னேற்றத்தைப் பார்க்கவும்.",
        "Scan time" to "ஸ்கேன் நேரம்",
        "Scanning inbox for new reports…" to "புதிய அறிக்கைகளுக்காக இன்பாக்ஸ் ஸ்கேன் செய்யப்படுகிறது…",
        "Scheduled Slot:" to "திட்டமிடப்பட்ட நேரம்:",
        "Search doctor or specialty..." to "மருத்துவர் அல்லது சிறப்புத்துறையைத் தேடு...",
        "Search hospital name..." to "மருத்துவமனை பெயரைத் தேடு...",
