        "See it in action" to "இதை செயலில் காண்க",
        "Select a Slot first" to "முதலில் ஒரு நேரத்தைத் தேர்ந்தெடு",
        "Select reminder slots" to "நினைவூட்டல் நேரங்களைத் தேர்ந்தெடு",
        "Select which days the patient should take this medicine:" to "நோயாளி இந்த மருந்தை எந்த நாட்களில் எடுக்க வேண்டும் என்பதைத் தேர்ந்தெடுக்கவும்:",
        "Sends just what changed since last time" to "கடைசி முறையிலிருந்து மாறியதை மட்டும் அனுப்புகிறது",
        "Server Settings" to "சேவையக அமைப்புகள்",
        "Server address, language, voice, backups" to "சேவையக முகவரி, மொழி, குரல், காப்புப்பிரதிகள்",
        "Set" to "அமை",
        "Settings" to "அமைப்புகள்",
        "Sex" to "பாலினம்",
        "Share" to "பகிர்",
        "Share brief" to "சுருக்கத்தைப் பகிர்",
        "Share on WhatsApp" to "WhatsApp-இல் பகிர்",
        "Share with Doctor" to "மருத்துவருடன் பகிர்",
        "Side Effects" to "பக்க விளைவுகள்",
        "Sign In" to "உள்நுழை",
        "Sign In with Google" to "Google மூலம் உள்நுழை",
        "Sign in quickly using fingerprint" to "கைரேகையைப் பயன்படுத்தி விரைவாக உள்நுழை",
        "Signing in gives you your own free daily AI usage allowance, separate from other users of this app." to "உள்நுழைவது இந்த ஆப்பின் மற்ற பயனர்களிடமிருந்து தனியாக உங்கள் சொந்த இலவச தினசரி AI பயன்பாட்டு அனுமதியை வழங்குகிறது.",
        "Skip & Mark Read" to "தவிர்த்து படித்ததாகக் குறி",
        "Smart Health Lens" to "ஸ்மார்ட் ஹெல்த் லென்ஸ்",
        "Something went wrong. Check your connection and try again." to "ஏதோ தவறு ஏற்பட்டது. உங்கள் இணைப்பைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும்.",
        "Speak" to "பேசு",
        "Special Patient Notes" to "சிறப்பு நோயாளி குறிப்புகள்",
        "Start Date (YYYY-MM-DD)" to "தொடக்க தேதி (YYYY-MM-DD)",
        "Stores the file without using AI — no API calls. You can analyze it anytime from its details." to "AI-ஐப் பயன்படுத்தாமல் கோப்பைச் சேமிக்கிறது — API அழைப்புகள் இல்லை. அதன் விவரங்களிலிருந்து எப்போது வேண்டுமானாலும் பகுப்பாய்வு செய்யலாம்.",
        "Successfully initiated booking request for:" to "இதற்கான முன்பதிவு கோரிக்கை வெற்றிகரமாகத் தொடங்கப்பட்டது:",
        "Switch Profile" to "சுயவிவரத்தை மாற்று",
        "Sync Now" to "இப்போது ஒத்திசை",
        "System" to "கணினி",
        "T" to "T",
        "Tap Settings → allow exact alarms so reminders arrive at the precise time." to "நினைவூட்டல்கள் சரியான நேரத்தில் வர அமைப்புகள் → துல்லியமான அலாரங்களை அனுமதிக்கவும் என்பதைத் தட்டவும்.",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "மருத்துவர் வருகை அல்லது பரிசோதனையை திட்டமிட மேலே \"நியமனத்தைச் சேர்\" என்பதைத் தட்டவும். அது நிலுவைக்கு முன் உங்களுக்கு நினைவூட்டப்படும்.",
        "Tap a medicine to expand" to "விரிவாக்க மருந்தைத் தட்டவும்",
        "Tap any point to open that report" to "அந்த அறிக்கையைத் திறக்க எந்தப் புள்ளியையும் தட்டவும்",
        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "உங்கள் சாதனத்திலிருந்து படம், PDF அல்லது டாக்கைத் தேர்ந்தெடுக்க இங்கே தட்டவும், அல்லது புகைப்படம் எடுக்க கீழே உள்ள கேமராவைப் பயன்படுத்தவும்.",
        "Tap play to hear this summary" to "இந்த சுருக்கத்தைக் கேட்க பிளேயைத் தட்டவும்",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "மருந்து நினைவூட்டல்கள் உங்கள் தொலைபேசி மற்றும் இணைக்கப்பட்ட வாட்சில் காட்ட அனுமதிக்க தட்டவும்.",
        "Tap to pick\nImage or PDF" to "தேர்ந்தெடுக்க தட்டவும்\nபடம் அல்லது PDF",
        "Tap to select" to "தேர்ந்தெடுக்க தட்டவும்",
        "Tap to view" to "பார்க்க தட்டவும்",
        "Test Parameter Changes" to "பரிசோதனை அளவுரு மாற்றங்கள்",
        "Test group" to "பரிசோதனை குழு",
        "Tested Parameters" to "சோதிக்கப்பட்ட அளவுருக்கள்",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "மருந்துச்சீட்டுகளில் பரிந்துரைக்கப்பட்ட பரிசோதனைகள் தானாக கண்காணிக்கப்படும். நீங்கள் அவற்றை கைமுறையாகவும் சேர்க்கலாம்.",
        "That QR code doesn't contain a report link." to "அந்த QR குறியீட்டில் அறிக்கை இணைப்பு இல்லை.",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "வசதி 10 நிமிடங்களுக்குள் SMS/WhatsApp மூலம் உங்கள் நேரத்தை உறுதிப்படுத்தும்.",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "தேர்ந்தெடுக்கப்பட்ட கோப்புகள் மிகப் பெரியவை (%.2f MB). இந்தக் கோப்புகளை செயலாக்குவது அதிக நேரம் எடுக்கும் மற்றும் நினைவக சிக்கல்களை ஏற்படுத்தலாம். கோப்புகளை 10 MB க்குள் வைத்திருக்க பரிந்துரைக்கிறோம். எப்படியும் தொடர விரும்புகிறீர்களா?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "இது உண்மையானது அல்ல. இதை நீக்கவும், அல்லது உங்கள் சொந்த பதிவுகளைக் கண்காணிக்கத் தொடங்க உள்நுழையவும்.",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "இது அனைத்து அறிக்கைகள், மருந்துகள், நிலுவை பரிசோதனைகள் மற்றும் படங்களை நிரந்தரமாக நீக்குகிறது. இதை மீட்டெடுக்க முடியாது.",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "இது அசல் ஸ்கேன் செய்யப்பட்ட படத்தில் AI பகுப்பாய்வை மீண்டும் இயக்கி கீழே உள்ள பிரித்தெடுக்கப்பட்ட பரிசோதனை மதிப்புகள், மருந்துகள் மற்றும் நுண்ணறிவுகளை புதுப்பிக்கிறது. முந்தைய ஸ்கேன் முழுமையடையாமல் வந்திருந்தால் (எ.கா. API சிறிது நேரம் கிடைக்கவில்லை) இது பயனுள்ளது. இது உங்கள் சில API ஒதுக்கீட்டைப் பயன்படுத்தலாம்.",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "இந்த அறிக்கையின் கோப்பு சேமிக்கப்பட்டுள்ளது ஆனால் AI ஆல் பகுப்பாய்வு செய்யப்படவில்லை, எனவே இதற்கு இன்னும் பரிசோதனை மதிப்புகள், போக்குகள் அல்லது நுண்ணறிவுகள் இல்லை. நீங்கள் தயாராக இருக்கும்போது பகுப்பாய்வு செய்யுங்கள் (சில API ஒதுக்கீட்டைப் பயன்படுத்தும்).",
        "Time (HH:MM)" to "நேரம் (HH:MM)",
        "Tip: 1-0-1 = morning & night, 1-1-1 = three times a day." to "குறிப்பு: 1-0-1 = காலை & இரவு, 1-1-1 = நாளொன்றுக்கு மூன்று முறை.",
        "Tips" to "குறிப்புகள்",
        "To" to "க்கு",
        "Today's free pool quota is used up. Add a personal API key below for unlimited scans, or wait until tomorrow." to "இன்றைய இலவச பூல் ஒதுக்கீடு தீர்ந்துவிட்டது. வரம்பற்ற ஸ்கேன்களுக்கு கீழே தனிப்பட்ட API கீயைச் சேர்க்கவும், அல்லது நாளை வரை காத்திருக்கவும்.",
        "Toggle" to "மாற்று",
        "Toggle text" to "மாற்று உரை",
        "Transfer Records" to "பதிவுகளை மாற்று",
        "Translates this intent using AI to target specific lab emails." to "குறிப்பிட்ட ஆய்வக மின்னஞ்சல்களை இலக்காகக் கொள்ள AI ஐப் பயன்படுத்தி இந்த நோக்கத்தை மொழிபெயர்க்கிறது.",
        "Trend" to "போக்கு",
        "Trends Overview" to "போக்குகள் கண்ணோட்டம்",
        "Trends appear once you have reports with numeric test values like TSH, sugar, hemoglobin, cholesterol." to "TSH, சர்க்கரை, ஹீமோகுளோபின், கொலஸ்ட்ரால் போன்ற எண் பரிசோதனை மதிப்புகளுடன் அறிக்கைகள் இருந்தால் போக்குகள் தோன்றும்.",
        "Try Demo" to "டெமோவை முயற்சிக்கவும்",
        "Try searching a different name" to "வேறு பெயரைத் தேட முயற்சிக்கவும்",
        "UHI Registered" to "UHI பதிவு செய்யப்பட்டது",
        "Unknown" to "அறியப்படாதது",
        "Upcoming Appointment" to "வரவிருக்கும் நியமனம்",
        "Update Password" to "கடவுச்சொல்லைப் புதுப்பி",
        "Upload Only (No Scan)" to "பதிவேற்றம் மட்டும் (ஸ்கேன் இல்லை)",
        "Upload only" to "பதிவேற்றம் மட்டும்",
        "Upload two reports, prescriptions, or scans to compare what changed between them." to "அவற்றுக்கிடையே என்ன மாறியது என்பதை ஒப்பிட இரண்டு அறிக்கைகள், மருந்துச்சீட்டுகள் அல்லது ஸ்கேன்களை பதிவேற்றவும்.",
        "Uploaded — not analyzed yet" to "பதிவேற்றப்பட்டது — இன்னும் பகுப்பாய்வு செய்யப்படவில்லை",
        "Uploaded. Open it later to analyze when you're ready." to "பதிவேற்றப்பட்டது. நீங்கள் தயாராகும்போது பகுப்பாய்வு செய்ய பின்னர் திறக்கவும்.",
        "Use GPS" to "GPS-ஐப் பயன்படுத்து",
        "Use your fingerprint to quickly sign in next time without waiting for an OTP or entering passwords." to "அடுத்த முறை OTP-க்காக காத்திருக்காமல் அல்லது கடவுச்சொல் உள்ளிடாமல் விரைவாக உள்நுழைய உங்கள் கைரேகையைப் பயன்படுத்தவும்.",
        "Using your individual Gemini API key — unlimited scans, bypassing the free tier limits." to "உங்கள் தனிப்பட்ட Gemini API கீயைப் பயன்படுத்துகிறது — வரம்பற்ற ஸ்கேன்கள், இலவச நிலை வரம்புகளைத் தவிர்த்து.",
        "Value" to "மதிப்பு",
        "Verification timed out. Please try again." to "சரிபார்ப்பு நேரம் முடிந்தது. மீண்டும் முயற்சிக்கவும்.",
        "Verify & Create Account" to "சரிபார்த்து கணக்கை உருவாக்கு",
        "Verify & Log In" to "சரிபார்த்து உள்நுழை",
        "View Detailed Analysis" to "விரிவான பகுப்பாய்வைப் பார்",
        "View Previous Report" to "முந்தைய அறிக்கையைப் பார்",
        "View Report" to "அறிக்கையைப் பார்",
        "View Scanned Report" to "ஸ்கேன் செய்யப்பட்ட அறிக்கையைப் பார்",
        "View details" to "விவரங்களைப் பார்",
        "View existing document" to "இருக்கும் ஆவணத்தைப் பார்",
        "Voice (Read Aloud)" to "குரல் (சத்தமாக படி)",
        "Voice Search" to "குரல் தேடல்",
        "Voice engine" to "குரல் இன்ஜின்",
        "W" to "W",
        "Waiting for UHI webhook callbacks..." to "UHI வெப்ஹுக் அழைப்புகளுக்காக காத்திருக்கிறது...",
        "Watch Out For:" to "கவனிக்க வேண்டியவை:",
        "Weekly Schedule" to "வாராந்திர அட்டவணை",
        "What This Report Means" to "இந்த அறிக்கை என்ன அர்த்தம்",
        "What is this medicine for?" to "இந்த மருந்து எதற்காக?",
        "Which voice reads answers aloud. Sarvam & Gemini speak Indian languages well; Phone uses your device's built-in voices (may not have Marathi)." to "எந்த குரல் பதில்களை சத்தமாக படிக்கிறது. Sarvam & Gemini இந்திய மொழிகளை நன்றாக பேசுகின்றன; தொலைபேசி உங்கள் சாதனத்தின் உள்ளமைந்த குரல்களைப் பயன்படுத்துகிறது (மராத்தி இல்லாமல் இருக்கலாம்).",
        "Who is this report for?" to "இந்த அறிக்கை யாருக்கானது?",
        "Why It's Prescribed" to "ஏன் பரிந்துரைக்கப்பட்டது",
        "Why is this medicine used?" to "இந்த மருந்து ஏன் பயன்படுத்தப்படுகிறது?",
        "Why is this used?" to "இது ஏன் பயன்படுத்தப்படுகிறது?",
        "Within:" to "இதற்குள்:",
        "Yes, Import" to "ஆம், இறக்குமதி செய்",
        "You can manually correct spelling mistakes in the Patient Name, Date, or Type below. Tapping the Save (Checkmark) icon in the top right will update the history database." to "கீழே நோயாளியின் பெயர், தேதி, அல்லது வகையில் உள்ள எழுத்துப் பிழைகளை நீங்கள் கைமுறையாக சரிசெய்யலாம். மேலே வலதுபுறத்தில் உள்ள சேமி (செக்மார்க்) ஐகானைத் தட்டுவது வரலாற்று தரவுத்தளத்தைப் புதுப்பிக்கும்.",
        "You haven't linked an email account yet. Please go to Settings (Account tab) to link your Gmail account or IMAP details first." to "நீங்கள் இன்னும் மின்னஞ்சல் கணக்கை இணைக்கவில்லை. உங்கள் Gmail கணக்கு அல்லது IMAP விவரங்களை முதலில் இணைக்க அமைப்புகள் (கணக்கு தாவல்) க்குச் செல்லவும்.",
        "You're using Health Decoder without an account" to "நீங்கள் கணக்கு இல்லாமல் Health Decoder ஐப் பயன்படுத்துகிறீர்கள்",
        "and set your new password." to "மேலும் உங்கள் புதிய கடவுச்சொல்லை அமைக்கவும்.",
        "at" to "இல்",
        "chars). It will be analyzed with any images." to "எழுத்துகள்). இது எந்த படங்களுடனும் பகுப்பாய்வு செய்யப்படும்.",
        "e.g. 1 tablet" to "எ.கா. 1 மாத்திரை",
        "e.g. 1-0-1" to "எ.கா. 1-0-1",
        "e.g. 1-0-1, twice daily, as needed" to "எ.கா. 1-0-1, நாளொன்றுக்கு இருமுறை, தேவைக்கேற்ப",
        "e.g. 2026-09-22" to "எ.கா. 2026-09-22",
        "e.g. 5 days" to "எ.கா. 5 நாட்கள்",
        "e.g. Apollo, Metropolis, Fortis" to "எ.கா. அப்பல்லோ, மெட்ரோபோலிஸ், ஃபோர்டிஸ்",
        "e.g. Blood Sugar Fasting (BSF)" to "எ.கா. இரத்த சர்க்கரை நோன்பு (BSF)",
        "e.g. CBC, Lipid, Thyroid..." to "எ.கா. CBC, லிபிட், தைராய்டு...",
        "e.g. John Doe" to "எ.கா. ஜான் டோ",
        "e.g. Metformin 500mg" to "எ.கா. மெட்ஃபார்மின் 500mg",
        "e.g. Rajesh Kumar" to "எ.கா. ராஜேஷ் குமார்",
        "e.g. Take with warm water" to "எ.கா. வெதுவெதுப்பான தண்ணீருடன் எடுத்துக் கொள்ளவும்",
        "new report(s) — check your notifications." to "புதிய அறிக்கை(கள்) — உங்கள் அறிவிப்புகளைச் சரிபார்க்கவும்.",
        "on" to "அன்று",
        "online" to "ஆன்லைன்",
        "page(s) selected. Add more pages of the SAME report, then analyze." to "பக்கங்கள் தேர்ந்தெடுக்கப்பட்டன. அதே அறிக்கையின் மேலும் பக்கங்களைச் சேர்த்து, பின் பகுப்பாய்வு செய்யவும்.",
        "per scan — extra pages were skipped. Analyze these first, then scan the rest." to "ஸ்கேனுக்கு — கூடுதல் பக்கங்கள் தவிர்க்கப்பட்டன. இவற்றை முதலில் பகுப்பாய்வு செய்து, பின் மீதமுள்ளவற்றை ஸ்கேன் செய்யவும்.",
        "report(s) on file" to "அறிக்கை(கள்) கோப்பில் உள்ளன",
        "selected" to "தேர்ந்தெடுக்கப்பட்டது",
        "starting" to "தொடங்கி",
        "your account" to "உங்கள் கணக்கு",
        "ℹ️ AI-generated reference. Always consult your doctor for medical advice." to "ℹ️ AI-உருவாக்கிய குறிப்பு. மருத்துவ ஆலோசனைக்கு எப்போதும் உங்கள் மருத்துவரை அணுகவும்.",
        "● LIVE" to "● நேரலை",
        "⚙️  Manage / edit family" to "⚙️  குடும்பத்தை நிர்வகி / திருத்து",
        "➕  New person…" to "➕  புதிய நபர்…",
        "🎙️ Ask AI" to "🎙️ AI-யிடம் கேளுங்கள்",
        "👨‍👩‍👧 Everyone" to "👨‍👩‍👧 அனைவரும்",
        "📸 Identify" to "📸 அடையாளம் காண்",
        "🧪 You're viewing sample demo data" to "🧪 நீங்கள் மாதிரி டெமோ தரவைப் பார்க்கிறீர்கள்",
        "Medication Reminders" to "மருந்து நினைவூட்டல்கள்",
        "Find Doctors" to "மருத்துவர்களைக் கண்டறி",
        "Find Hospitals" to "மருத்துவமனைகளைக் கண்டறி",
        "Doctor Brief" to "மருத்துவர் சுருக்கம்",
        "Scan any medical report" to "எந்த மருத்துவ அறிக்கையையும் ஸ்கேன் செய்யவும்",
        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "காகித ஆய்வக அறிக்கைகள், மருந்துச்சீட்டுகள் மற்றும் டிஸ்சார்ஜ் சுருக்கங்களை ஒழுங்கமைக்கப்பட்ட, தேடக்கூடிய டிஜிட்டல் பதிவுகளாக மாற்றவும் — உங்கள் தொலைபேசியின் கேமராவிலிருந்தே.",
        "Understand it instantly" to "அதை உடனடியாக புரிந்துகொள்ளுங்கள்",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI பக்கத்தில் உள்ள ஒவ்வொரு பரிசோதனை மதிப்பு, மருந்து மற்றும் தேதியையும் படிக்கிறது, இதனால் மருத்துவ சொற்களஞ்சியத்தில் சிக்காமல் அறிக்கை உண்மையில் என்ன அர்த்தம் என்பதை நீங்கள் காணலாம்.",
        "Never miss a dose or a follow-up" to "ஒருபோதும் ஒரு மருந்தளவையோ பின்தொடர்தலையோ தவறவிடாதீர்கள்",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "மருந்து நினைவூட்டல்கள் ஒவ்வொரு நாளும் சரியான நேரத்தில் ஒலிக்கும் — வாரத்திற்கு இருமுறை மருந்துக்கும் கூட — மேலும் மருத்துவர் நியமனங்களுக்கும் தனி நினைவூட்டல் உண்டு.",
        "What do my latest test results mean?" to "எனது சமீபத்திய பரிசோதனை முடிவுகள் என்ன அர்த்தம்?",
        "Explain my current medicines in simple words" to "எனது தற்போதைய மருந்துகளை எளிய வார்த்தைகளில் விளக்குங்கள்",
        "Are any of my values abnormal?" to "எனது மதிப்புகளில் ஏதேனும் அசாதாரணமா?",
        "What should I ask my doctor next?" to "அடுத்து நான் என் மருத்துவரிடம் என்ன கேட்க வேண்டும்?",
        "Rx" to "Rx",
        "Hospitals" to "மருத்துவமனைகள்",
        "Lab Tests" to "ஆய்வக பரிசோதனைகள்",
        "Doctors" to "மருத்துவர்கள்",
        "Broadcasting search to UHI gateway..." to "UHI நுழைவாயிலுக்கு தேடல் ஒளிபரப்பப்படுகிறது...",
        "Gateway ACK received. Listening for provider webhook responses..." to "நுழைவாயில் ACK பெறப்பட்டது. வழங்குநர் வெப்ஹுக் பதில்களுக்காக கேட்கிறது...",
        "Listening for provider webhooks... (Incoming responses)" to "வழங்குநர் வெப்ஹுக்குகளுக்காக கேட்கிறது... (வரும் பதில்கள்)",
        "3M" to "3 மாதங்கள்",
        "6M" to "6 மாதங்கள்",
        "1Y" to "1 ஆண்டு",
        "2Y" to "2 ஆண்டுகள்",
        "10 km" to "10 கிமீ",
        "20 km" to "20 கிமீ",
        "50 km" to "50 கிமீ",
        "Any" to "எதுவும்",
        "Couldn't load your account. Check your connection and try again." to "உங்கள் கணக்கை ஏற்ற முடியவில்லை. உங்கள் இணைப்பைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும்.",
        "Please enter a valid API key or tap 'Revert to Shared Pool'." to "சரியான API கீயை உள்ளிடவும் அல்லது 'பகிரப்பட்ட பூலுக்குத் திரும்பு' என்பதைத் தட்டவும்.",
        "Personal API Key saved! Switched to Individual Key mode." to "தனிப்பட்ட API கீ சேமிக்கப்பட்டது! தனிநபர் கீ முறைக்கு மாற்றப்பட்டது.",
        "Reverted to Primary Shared Key Pool." to "முதன்மை பகிரப்பட்ட கீ பூலுக்குத் திரும்பப்பட்டது.",
        "All fields are required." to "அனைத்து புலங்களும் தேவை.",
        "New password must be at least 6 characters." to "புதிய கடவுச்சொல் குறைந்தது 6 எழுத்துகள் இருக்க வேண்டும்.",
        "Password updated successfully." to "கடவுச்சொல் வெற்றிகரமாக புதுப்பிக்கப்பட்டது.",
        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "உதவியாளரை அடைய முடியவில்லை. சேவையகம் இயங்குகிறதா, அமைப்புகளில் கட்டமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "இந்த சாதனத்தில் குரல் உள்ளீடு கிடைக்கவில்லை. Google குரல் தட்டச்சை நிறுவவும்/இயக்கவும்.",
        "Couldn't generate the detailed analysis. Please try again." to "விரிவான பகுப்பாய்வை உருவாக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
        "Search failed. Make sure the backend server is running and database is migrated." to "தேடல் தோல்வியடைந்தது. பேக்எண்ட் சேவையகம் இயங்குகிறதா, தரவுத்தளம் இடம்பெயர்ந்துள்ளதா என உறுதிசெய்யவும்.",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "மருந்துகளைப் பெறுவதில் தோல்வி. உங்கள் உள்ளூர் சேவையகம் இயங்குகிறதா, அமைப்புகளில் சரியாக கட்டமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.",
        "Failed to delete the selected medicines." to "தேர்ந்தெடுக்கப்பட்ட மருந்துகளை நீக்குவதில் தோல்வி.",
        "Failed to update the selected medicines." to "தேர்ந்தெடுக்கப்பட்ட மருந்துகளைப் புதுப்பிப்பதில் தோல்வி.",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "நிலுவை பரிசோதனைகளைப் பெறுவதில் தோல்வி. உங்கள் உள்ளூர் சேவையகம் இயங்குகிறதா, அமைப்புகளில் சரியாக கட்டமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.",
        "Failed to delete test reminder." to "பரிசோதனை நினைவூட்டலை நீக்குவதில் தோல்வி.",
        "Patient and Test names are required." to "நோயாளி மற்றும் பரிசோதனை பெயர்கள் தேவை.",
        "Failed to save test reminder." to "பரிசோதனை நினைவூட்டலைச் சேமிப்பதில் தோல்வி.",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "பதிவுகளைப் பெறுவதில் தோல்வி. உங்கள் உள்ளூர் சேவையகம் இயங்குகிறதா, அமைப்புகளில் சரியாக கட்டமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "நினைவூட்டல்களைப் பெறுவதில் தோல்வி. உங்கள் உள்ளூர் சேவையகம் இயங்குகிறதா, அமைப்புகளில் சரியாக கட்டமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.",
        "Couldn't save the file." to "கோப்பைச் சேமிக்க முடியவில்லை.",
        "No app available to open this file type." to "இந்த கோப்பு வகையைத் திறக்க எந்த ஆப்பும் இல்லை.",
        "Couldn't share this file." to "இந்த கோப்பைப் பகிர முடியவில்லை.",
        "Report not found." to "அறிக்கை காணப்படவில்லை.",
        "Failed to load report details." to "அறிக்கை விவரங்களை ஏற்றுவதில் தோல்வி.",
        "Failed to save edits. Check network settings." to "திருத்தங்களைச் சேமிப்பதில் தோல்வி. நெட்வொர்க் அமைப்புகளைச் சரிபார்க்கவும்.",
        "Failed to delete report." to "அறிக்கையை நீக்குவதில் தோல்வி.",
        "Couldn't reprocess: report or its scanned image is missing." to "மீண்டும் செயலாக்க முடியவில்லை: அறிக்கை அல்லது அதன் ஸ்கேன் செய்யப்பட்ட படம் இல்லை.",
        "Failed to reprocess this report." to "இந்த அறிக்கையை மீண்டும் செயலாக்குவதில் தோல்வி.",
        "Medicine name is required." to "மருந்தின் பெயர் தேவை.",
        "Select at least one reminder slot." to "குறைந்தபட்சம் ஒரு நினைவூட்டல் நேரத்தைத் தேர்ந்தெடுக்கவும்.",
        "Doctor name is required." to "மருத்துவரின் பெயர் தேவை.",
        "Place is required." to "இடம் தேவை.",
        "Date is required." to "தேதி தேவை.",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "இந்த சாதனத்தின் பாதுகாப்பான ஹார்ட்வேர் சேமிப்பகம் கிடைக்கவில்லை, எனவே உங்கள் லோக்கல் ரெக்கார்ட்ஸ் கீ மற்றும் இணைக்கப்பட்ட-மின்னஞ்சல் நற்சான்றிதழ்கள் ஹார்ட்வேர்-ஆதரவு குறியாக்கம் இல்லாமல் சேமிக்கப்படுகின்றன. உங்கள் தரவு இன்னும் பாதுகாப்பின்றி எங்கும் அனுப்பப்படவில்லை, ஆனால் இந்த சாதனம் வழக்கத்தை விட பலவீனமான பாதுகாப்பை வழங்குகிறது.",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "ஸ்கேனிங், நினைவூட்டல்கள் மற்றும் மற்ற அனைத்தும் இந்த சாதனத்தில் உள்நுழையாமல் முழுமையாக செயல்படும். உள்நுழைவு விருப்பமானது (இது SMS குறியீட்டை அனுப்புகிறது, எனவே தானாக நடக்காது) — சாதனங்களில் உங்களுடன் தொடரும் சுயவிவரம் அல்லது தனிப்பட்ட API கீ வேண்டுமெனில் இதைப் பயன்படுத்தவும்.",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "ஒவ்வொரு போக்கு விரைபடமும் அளவீடுகளை தரப்படுத்தும் அலகு. வேறு அலகில் உள்ள அறிக்கைகள் தானாக மாற்றப்படும்; ஒவ்வொரு அறிக்கையும் அதன் அசல் மதிப்பைக் காட்டும்.",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "ஏன்: Health Decoder செலவுகளை குறைவாக வைத்திருப்பதன் மூலம் இலவசமாக இருக்கிறது, உங்கள் பதிவுகளை விற்பதன் மூலம் அல்ல. நீங்கள் இங்கு இணைந்தால், உங்கள் வயது மற்றும் பாலினம் மட்டும் — உங்கள் பெயர், அறிக்கைகள் அல்லது துல்லியமான இருப்பிடம் ஒருபோதும் இல்லை — மருத்துவ ஆராய்ச்சி நிறுவனங்களுடன் மொத்தமாக பகிரப்படும், விளம்பரங்களை இயக்குவதற்கு அல்லது சந்தா வசூலிப்பதற்குப் பதிலாக ஒவ்வொரு குடும்பத்திற்கும் ஆப்பை இலவசமாக வைத்திருக்க உதவும் வகையில்.",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "இந்த திட்டம் இன்னும் தொடங்கவில்லை — இன்று இதை இயக்குவது உங்கள் விருப்பத்தை மட்டும் சேமிக்கும். உண்மையான தரவு-பகிர்வு பைப்லைன் இருக்கும் வரை எதுவும் எங்கும் அனுப்பப்படாது, மேலும் நீங்கள் எப்போது வேண்டுமானாலும் இங்கு உங்கள் பதிலை மாற்றலாம்.",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "இது உங்கள் Health Decoder கணக்கையும் இந்த சாதனத்தில் சேமிக்கப்பட்ட அனைத்து மருத்துவ பதிவுகளையும் — அறிக்கைகள், நினைவூட்டல்கள், நியமனங்கள் மற்றும் குடும்ப சுயவிவரங்கள் — நிரந்தரமாக நீக்கும். இதை மீட்டெடுக்க முடியாது.",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "பரிந்துரைக்கப்படுகிறது, மேலும் முக்கிய குறிப்புகளும். முதல் தேடல் இணையத்தைப் பயன்படுத்துகிறது, பின்னர் அது சேமிக்கப்படுகிறது அதனால் அடுத்த முறை உடனடியாக திறக்கும்.",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "மாதிரி அறிக்கைகள், நினைவூட்டல்கள் மற்றும் ஏற்கனவே நிரப்பப்பட்ட நியமனத்துடன், நீங்கள் உண்மையானதை ஸ்கேன் செய்வதற்கு முன் ஒவ்வொரு திரையையும் ஆராயலாம். கணக்கிலிருந்து அதை எப்போது வேண்டுமானாலும் அகற்றவும்.",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "அந்த QR ஒரு வலைப்பக்கத்தைத் திறந்தது, நேரடி கோப்பு அல்ல. அதை உங்கள் உலாவியில் திறக்கிறது — அங்கு அறிக்கையைப் பதிவிறக்கவும், பின்னர் அதை இறக்குமதி செய்ய \"சாதனத்திலிருந்து\" பயன்படுத்தவும்.",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "பெரிய ஆவணங்களை பகுப்பாய்வுக்காகப் பிரிக்கும் முறையில் திருத்தம் செய்யப்படுவதற்கு முன்பு %1\$d பல-பக்க ஸ்கேன்கள் செயலாக்கப்பட்டன — அதே ஆவணத்தின் ஒரு பேனல் (எ.கா. எலக்ட்ரோலைட்டுகள் அல்லது PT/INR பக்கம்) விடுபட்டிருக்கலாம். இது ஏற்கனவே சேமிக்கப்பட்ட பக்கங்களைப் பயன்படுத்தி மீண்டும் சரிபார்த்து, விடுபட்டதைச் சேர்க்கிறது; ஏற்கனவே சேமித்தவை அப்படியே இருக்கும்.",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "AI பகுப்பாய்வு சேவையகம் கிடைக்காத நேரத்தில் %1\$d அறிக்கை(கள்) சேமிக்கப்பட்டன (எ.கா. தினசரி ஒதுக்கீடு முடிந்தது), எனவே அவற்றின் தேதியும் வகையும் ஆவணத்திலிருந்து படிக்கப்படாமல் ஊகிக்கப்பட்டவை. மீள்பகுப்பாய்வு ஏற்கனவே சேமித்த படங்களைப் பயன்படுத்துகிறது — நீங்கள் மீண்டும் ஸ்கேன் செய்ய வேண்டியதில்லை.",
        "Add, edit, or remove people this device tracks — including yourself" to "இந்தச் சாதனம் கண்காணிக்கும் நபர்களைச் சேர்க்கவும், திருத்தவும் அல்லது நீக்கவும் — நீங்கள் உட்பட",
        "Also protect automatic backups with a password" to "தானியங்கி காப்புப்பிரதிகளையும் கடவுச்சொல்லால் பாதுகாக்கவும்",
        "Auto-backup password" to "தானியங்கி காப்புப்பிரதி கடவுச்சொல்",
        "Backup password" to "காப்புப்பிரதி கடவுச்சொல்",
        "Based on your %1\$s result (%2\$s) from your report dated %3\$s." to "%3\$s தேதியிட்ட உங்கள் அறிக்கையின் %1\$s முடிவை (%2\$s) அடிப்படையாகக் கொண்டது.",
        "Blood" to "இரத்தம்",
        "Brief" to "சுருக்கம்",
        "Chat" to "அரட்டை",
        "Check Now (%1\$d)" to "இப்போது சரிபார் (%1\$d)",
        "Check for Missing Report Data" to "விடுபட்ட அறிக்கைத் தரவைச் சரிபார்க்கவும்",
        "Checking %1\$d of %2\$d…" to "%2\$d இல் %1\$d சரிபார்க்கப்படுகிறது…",
        "Compare" to "ஒப்பீடு",
        "Confirm password" to "கடவுச்சொல்லை உறுதிப்படுத்தவும்",
        "Data Management" to "தரவு மேலாண்மை",
        "Date of Birth (YYYY-MM-DD)" to "பிறந்த தேதி (YYYY-MM-DD)",
        "Discharge Summary" to "வெளியேற்ற சுருக்கம்",
        "Discharge Summary + Prescription" to "வெளியேற்ற சுருக்கம் + மருந்துச்சீட்டு",
        "Echo" to "எக்கோ",
        "Edit Profile" to "சுயவிவரத்தைத் திருத்து",
        "Edit profile" to "சுயவிவரத்தைத் திருத்து",
        "Ends" to "முடிவு",
        "Enter Backup Password" to "காப்புப்பிரதி கடவுச்சொல்லை உள்ளிடவும்",
        "Every" to "ஒவ்வொரு",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restoring REPLACES everything currently on this device." to "உங்கள் அனைத்துப் பதிவுகளையும் (அறிக்கைகள் + படங்கள்) ஒரே காப்புப்பிரதிக் கோப்பாக ஏற்றுமதி செய்யவும். கிளவுட் நகல் வைத்திருக்க பிக்கரில் உங்கள் Google Drive அல்லது OneDrive கோப்புறையைத் தேர்வு செய்யவும். மீட்டமைத்தால் இந்தச் சாதனத்தில் உள்ள அனைத்தும் மாற்றப்படும்.",
        "Family Members" to "குடும்ப உறுப்பினர்கள்",
        "First Name" to "முதல் பெயர்",
        "Free Gemini API Key (Optional)" to "இலவச Gemini API விசை (விருப்பத்தேர்வு)",
        "Full Backup & Restore" to "முழு காப்புப்பிரதி & மீட்டமைப்பு",
        "General lifestyle suggestion, not medical advice — talk to your doctor before making changes based on a lab result." to "பொதுவான வாழ்க்கைமுறை பரிந்துரை, மருத்துவ ஆலோசனை அல்ல — ஆய்வக முடிவின் அடிப்படையில் மாற்றங்கள் செய்வதற்கு முன் உங்கள் மருத்துவரிடம் பேசுங்கள்.",
        "Get Free API Key" to "இலவச API விசையைப் பெறுங்கள்",
        "Got it" to "புரிந்தது",
        "HEALTH TIP" to "உடல்நல குறிப்பு",
        "Health Decoder" to "ஹெல்த் டிகோடர்",
        "Hello," to "வணக்கம்,",
        "High" to "அதிகம்",
        "Home" to "முகப்பு",
        "Last Name" to "கடைசி பெயர்",
        "Learn More" to "மேலும் அறிக",
        "Leave blank to keep the current one" to "தற்போதையதை அப்படியே வைக்க காலியாக விடவும்",
        "Live camera scan — point and get instant answers" to "நேரடி கேமரா ஸ்கேன் — கேமராவைக் காட்டி உடனடி பதில்களைப் பெறுங்கள்",
        "Low" to "குறைவு",
        "Medical Report" to "மருத்துவ அறிக்கை",
        "Not set" to "அமைக்கப்படவில்லை",
        "Not signed in" to "உள்நுழையவில்லை",
        "Off by default — these sync to your cloud folder above without a password unless you set one here" to "இயல்பாக அணைக்கப்பட்டுள்ளது — நீங்கள் இங்கே ஒன்றை அமைக்கும் வரை இவை மேலே உள்ள உங்கள் கிளவுட் கோப்புறைக்கு கடவுச்சொல் இன்றி ஒத்திசைக்கப்படும்",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "மருந்துச்சீட்டுகள் ஸ்கேன் செய்யப்பட்டதும், உங்கள் தினசரி மருந்துகள் நினைவூட்டல்களுடன் இங்கே தோன்றும்.\n\nஒவ்வொரு மருந்துக்கும் நினைவூட்டல்களை இயக்க கீழே உள்ள மாற்றியை அழுத்தவும்.",
        "Optional — keeps your data available across devices" to "விருப்பத்தேர்வு — உங்கள் தரவை எல்லாச் சாதனங்களிலும் கிடைக்கச் செய்கிறது",
        "Optional — leave blank to use the shared pool" to "விருப்பத்தேர்வு — பகிர்ந்த தொகுப்பைப் பயன்படுத்த காலியாக விடவும்",
        "PERSONALIZED FOR YOU" to "உங்களுக்காகப் பிரத்யேகம்",
        "Passwords don't match" to "கடவுச்சொற்கள் பொருந்தவில்லை",
        "Profile" to "சுயவிவரம்",
        "Protect this backup with a password" to "இந்தக் காப்புப்பிரதியை கடவுச்சொல்லால் பாதுகாக்கவும்",
        "Re-analyze All (%1\$d)" to "அனைத்தையும் மீள்பகுப்பாய்வு செய் (%1\$d)",
        "Re-analyzing %1\$d of %2\$d…" to "%2\$d இல் %1\$d மீள்பகுப்பாய்வு செய்யப்படுகிறது…",
        "Reports Needing Re-check" to "மீண்டும் சரிபார்க்க வேண்டிய அறிக்கைகள்",
        "Restoring…" to "மீட்டமைக்கப்படுகிறது…",
        "Select gender" to "பாலினத்தைத் தேர்வு செய்யவும்",
        "Share / Merge Records" to "பதிவுகளைப் பகிர் / இணை",
        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "பகிர் / இணை என்பது தேர்ந்தெடுத்தவற்றை மற்றொரு தொலைபேசிக்கோ மருத்துவருக்கோ அனுப்பி, அங்கு உள்ளவற்றுடன் சேர்க்கிறது. காப்புப்பிரதி & மீட்டமைப்பு என்பது இந்தச் சாதனத்தின் முழு ஸ்னாப்ஷாட் — மீட்டமைக்கும்போது அனைத்தையும் மாற்றிவிடும், எனவே அதைப் பகிர்வதற்கு அல்ல, பேரிடர் மீட்புக்குப் பயன்படுத்துங்கள்.",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "உங்கள் பெயரையும் விவரங்களையும் திருத்த, தனிப்பட்ட API விசையைப் பயன்படுத்த, கைரேகை உள்நுழைவை இயக்க உள்நுழையவும். அது இல்லாமலும் ஆப் முழுமையாக வேலை செய்கிறது — உங்கள் குடும்ப உறுப்பினர்களும் பதிவுகளும் ஏற்கனவே இந்தச் சாதனத்தில் உள்ளன.",
        "Sign in to sync your records" to "உங்கள் பதிவுகளை ஒத்திசைக்க உள்நுழையவும்",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "இதைத் தவிர்த்தால் ஆப் இயல்பாக பகிர்ந்த இலவச தொகுப்பைப் பயன்படுத்தும். உங்கள் சொந்த விசையை முன்கூட்டியே சேர்த்தால் அந்தத் தொகுப்பின் தினசரி வரம்பு உங்களைத் தடுக்காது.",
        "Sono" to "சோனோ",
        "Starts" to "தொடக்கம்",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "மருத்துவர் சந்திப்பு அல்லது பரிசோதனையைத் திட்டமிட மேலே உள்ள \"சந்திப்பைச் சேர்\" ஐ அழுத்தவும். நேரத்திற்கு முன்பே உங்களுக்கு நினைவூட்டப்படும்.",
        "Tap to pick\nImage or PDF" to "தேர்வு செய்ய அழுத்தவும்\nபடம் அல்லது PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "அந்த QR ஒரு வலைப்பக்கத்தைத் திறந்தது, நேரடிக் கோப்பை அல்ல. அது உங்கள் உலாவியில் திறக்கப்படுகிறது — அங்கே அறிக்கையைப் பதிவிறக்கி, பிறகு அதை இறக்குமதி செய்ய \"சாதனத்திலிருந்து\" ஐப் பயன்படுத்தவும்.",
        "There's no way to reset this if you forget it — write it down somewhere safe." to "இதை மறந்தால் மீட்டமைக்க வழி இல்லை — எங்காவது பாதுகாப்பாக எழுதி வைத்துக்கொள்ளுங்கள்.",
        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "இதை மறந்தால் மீட்டமைக்க வழி இல்லை — எங்காவது பாதுகாப்பாக எழுதி வைத்துக்கொள்ளுங்கள். காப்புப்பிரதி கடவுச்சொல் தொலைந்தால் அந்தக் காப்புப்பிரதியை ஒருபோதும் மீட்டமைக்க முடியாது.",
        "This backup is password-protected. Enter the password it was created with." to "இந்தக் காப்புப்பிரதி கடவுச்சொல்லால் பாதுகாக்கப்பட்டுள்ளது. அது உருவாக்கப்பட்ட கடவுச்சொல்லையே உள்ளிடவும்.",
        "Try Smart Health Lens" to "ஸ்மார்ட் ஹெல்த் லென்ஸை முயற்சிக்கவும்",
        "Welcome" to "வரவேற்கிறோம்",
        "Without one, anyone who gets the backup file can open it" to "அது இல்லாவிட்டால், காப்புப்பிரதிக் கோப்பைப் பெறும் யாரும் அதைத் திறக்க முடியும்",
        "Your Profile" to "உங்கள் சுயவிவரம்",
        "➕ Add family member" to "➕ குடும்ப உறுப்பினரைச் சேர்"
