        "All patients" to "అందరు రోగులు",
        "All search results, doctor availability, and diagnostic slots are purely informational. Sourced from the public UHI network, they are not clinical recommendations or confirmed appointments. Do not rely solely on this information. Always consult a qualified medical professional for health concerns." to "అన్ని శోధన ఫలితాలు, డాక్టర్ లభ్యత మరియు నిర్ధారణ స్లాట్‌లు కేవలం సమాచార ప్రయోజనాల కోసమే. పబ్లిక్ UHI నెట్‌వర్క్ నుండి పొందినవి, ఇవి క్లినికల్ సిఫార్సులు లేదా ధృవీకరించబడిన అపాయింట్‌మెంట్‌లు కావు. కేవలం ఈ సమాచారంపై ఆధారపడవద్దు. ఆరోగ్య సమస్యల కోసం ఎల్లప్పుడూ అర్హత కలిగిన వైద్య నిపుణుడిని సంప్రదించండి.",
