        "Enter doctor's comments or notes here..." to "డాక్టర్ వ్యాఖ్యలు లేదా గమనికలను ఇక్కడ నమోదు చేయండి...",
        "Enter the 10-digit mobile number linked to your account to verify your identity via OTP." to "OTP ద్వారా మీ గుర్తింపును ధృవీకరించడానికి మీ ఖాతాకు లింక్ చేయబడిన 10-అంకెల మొబైల్ నంబర్‌ను నమోదు చేయండి.",
        "Enter the 6-digit OTP code sent to" to "దీనికి పంపిన 6-అంకెల OTP కోడ్‌ను నమోదు చేయండి",
        "Enter the 6-digit OTP code." to "6-అంకెల OTP కోడ్‌ను నమోదు చేయండి.",
        "Enter the 6-digit code sent to your phone." to "మీ ఫోన్‌కు పంపిన 6-అంకెల కోడ్‌ను నమోదు చేయండి.",
        "Error: Please log in again to configure fingerprint." to "లోపం: వేలిముద్రను కాన్ఫిగర్ చేయడానికి దయచేసి మళ్లీ లాగిన్ చేయండి.",
