        "Expand" to "విస్తరించండి",
        "Explains your records in simple terms. Not a doctor — always confirm with your physician." to "మీ రికార్డులను సాధారణ భాషలో వివరిస్తుంది. ఇది డాక్టర్ కాదు — ఎల్లప్పుడూ మీ వైద్యుడితో నిర్ధారించుకోండి.",
        "Export" to "ఎగుమతి చేయండి",
        "Export Backup" to "బ్యాకప్‌ను ఎగుమతి చేయండి",
        "Export a shareable file of your records (with analysis included) to send to another phone or a doctor. Importing merges it into this phone and never re-runs the AI, so it's free." to "మరొక ఫోన్‌కు లేదా డాక్టర్‌కు పంపడానికి మీ రికార్డుల యొక్క షేర్ చేయదగిన ఫైల్‌ను (విశ్లేషణతో సహా) ఎగుమతి చేయండి. దిగుమతి చేయడం దీన్ని ఈ ఫోన్‌లో విలీనం చేస్తుంది మరియు AIని మళ్లీ నడపదు, కాబట్టి ఇది ఉచితం.",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restore re-imports a backup file." to "మీ అన్ని రికార్డులను (నివేదికలు + చిత్రాలు) ఒకే బ్యాకప్ ఫైల్‌గా ఎగుమతి చేయండి. క్లౌడ్ కాపీని ఉంచడానికి పికర్‌లో మీ Google Drive లేదా OneDrive ఫోల్డర్‌ను ఎంచుకోండి. పునరుద్ధరణ బ్యాకప్ ఫైల్‌ను మళ్లీ దిగుమతి చేస్తుంది.",
        "F" to "F",
        "Facility:" to "సదుపాయం:",
