        "Finds reports that were saved more than once (same patient, date, and content) and removes the extra copies. The original of each report is always kept. New scans are checked automatically; this cleans up older duplicates." to "ఒకటి కంటే ఎక్కువ సార్లు సేవ్ చేయబడిన నివేదికలను (అదే రోగి, తేదీ, కంటెంట్) కనుగొని అదనపు కాపీలను తొలగిస్తుంది. ప్రతి నివేదిక యొక్క అసలు కాపీ ఎల్లప్పుడూ ఉంచబడుతుంది. కొత్త స్కాన్‌లు స్వయంచాలకంగా తనిఖీ చేయబడతాయి; ఇది పాత నకిలీలను శుభ్రం చేస్తుంది.",
