        "Full Screen shows a large-text alarm page (even on the lock screen) so medicine names are easy to read. Medicines due at the same time always appear together in one reminder." to "పూర్తి స్క్రీన్ పెద్ద-టెక్స్ట్ అలారం పేజీని చూపిస్తుంది (లాక్ స్క్రీన్‌పై కూడా) తద్వారా మందుల పేర్లు సులభంగా చదవగలరు. ఒకే సమయంలో తీసుకోవాల్సిన మందులు ఎల్లప్పుడూ ఒకే రిమైండర్‌లో కలిసి కనిపిస్తాయి.",
