        "Grant permission" to "అనుమతి ఇవ్వండి",
        "Health Decoder Logo" to "హెల్త్ డికోడర్ లోగో",
        "Health Decoder requires your permission to connect to your email inbox. We will only search for emails from the last 2 days containing potential medical report attachments (PDFs) and extract them locally on your phone. No email contents are sent to our servers. Do you consent to this?" to "మీ ఇమెయిల్ ఇన్‌బాక్స్‌కు కనెక్ట్ కావడానికి Health Decoder‌కు మీ అనుమతి అవసరం. మేము గత 2 రోజుల్లోని సంభావ్య వైద్య నివేదిక జోడింపులు (PDFలు) ఉన్న ఇమెయిల్‌లను మాత్రమే శోధించి, వాటిని మీ ఫోన్‌లో స్థానికంగా సేకరిస్తాము. ఏ ఇమెయిల్ కంటెంట్ కూడా మా సర్వర్‌లకు పంపబడదు. దీనికి మీరు అంగీకరిస్తారా?",
        "Help Fund This App" to "ఈ యాప్‌కు నిధులు సమకూర్చడంలో సహాయపడండి",
