        "Searching Unified Health Interface (UHI) registry for real-time open network listings." to "రియల్-టైమ్ ఓపెన్ నెట్‌వర్క్ లిస్టింగ్‌ల కోసం యూనిఫైడ్ హెల్త్ ఇంటర్‌ఫేస్ (UHI) రిజిస్ట్రీని శోధిస్తోంది.",
        "Searching nearby centers..." to "సమీప కేంద్రాలు శోధించబడుతున్నాయి...",
        "Secondary: Custom Key" to "సెకండరీ: అనుకూల కీ",
        "Secure App Password" to "సురక్షిత యాప్ పాస్‌వర్డ్",
        "Secure Medical Report Analyzer" to "సురక్షిత వైద్య నివేదిక విశ్లేషకుడు",
        "See it in action" to "దీన్ని చర్యలో చూడండి",
        "Select a Slot first" to "మొదట స్లాట్‌ను ఎంచుకోండి",
        "Select reminder slots" to "రిమైండర్ స్లాట్‌లను ఎంచుకోండి",
        "Select which days the patient should take this medicine:" to "రోగి ఈ మందును ఏ రోజుల్లో తీసుకోవాలో ఎంచుకోండి:",
        "Sends just what changed since last time" to "చివరిసారి నుండి మారినది మాత్రమే పంపుతుంది",
        "Server Settings" to "సర్వర్ సెట్టింగ్‌లు",
        "Server address, language, voice, backups" to "సర్వర్ చిరునామా, భాష, స్వరం, బ్యాకప్‌లు",
        "Set" to "సెట్ చేయండి",
        "Settings" to "సెట్టింగ్‌లు",
        "Sex" to "లింగం",
        "Share" to "షేర్ చేయండి",
        "Share brief" to "సారాంశాన్ని షేర్ చేయండి",
        "Share on WhatsApp" to "WhatsAppలో షేర్ చేయండి",
        "Share with Doctor" to "డాక్టర్‌తో షేర్ చేయండి",
        "Side Effects" to "దుష్ప్రభావాలు",
        "Sign In" to "సైన్ ఇన్ చేయండి",
        "Sign In with Google" to "Googleతో సైన్ ఇన్ చేయండి",
        "Sign in quickly using fingerprint" to "వేలిముద్రను ఉపయోగించి త్వరగా సైన్ ఇన్ చేయండి",
        "Signing in gives you your own free daily AI usage allowance, separate from other users of this app." to "సైన్ ఇన్ చేయడం వల్ల ఈ యాప్‌లోని ఇతర వినియోగదారుల నుండి వేరుగా మీ స్వంత ఉచిత రోజువారీ AI వినియోగ భత్యం లభిస్తుంది.",
        "Skip & Mark Read" to "దాటవేసి చదివినట్లు గుర్తించండి",
        "Smart Health Lens" to "స్మార్ట్ హెల్త్ లెన్స్",
        "Something went wrong. Check your connection and try again." to "ఏదో తప్పు జరిగింది. మీ కనెక్షన్‌ను తనిఖీ చేసి మళ్లీ ప్రయత్నించండి.",
        "Speak" to "మాట్లాడండి",
        "Special Patient Notes" to "ప్రత్యేక రోగి గమనికలు",
        "Start Date (YYYY-MM-DD)" to "ప్రారంభ తేదీ (YYYY-MM-DD)",
        "Stores the file without using AI — no API calls. You can analyze it anytime from its details." to "AI ఉపయోగించకుండా ఫైల్‌ను నిల్వ చేస్తుంది — API కాల్స్ లేవు. దాని వివరాల నుండి మీరు ఎప్పుడైనా విశ్లేషించవచ్చు.",
        "Successfully initiated booking request for:" to "దీని కోసం బుకింగ్ అభ్యర్థన విజయవంతంగా ప్రారంభించబడింది:",
        "Switch Profile" to "ప్రొఫైల్‌ను మార్చండి",
        "Sync Now" to "ఇప్పుడు సింక్ చేయండి",
        "System" to "సిస్టమ్",
        "T" to "T",
        "Tap Settings → allow exact alarms so reminders arrive at the precise time." to "రిమైండర్‌లు సరైన సమయానికి రావడానికి సెట్టింగ్‌లు → ఖచ్చితమైన అలారాలను అనుమతించండి నొక్కండి.",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "డాక్టర్ సందర్శన లేదా చెక్-అప్‌ను షెడ్యూల్ చేయడానికి పైన \"అపాయింట్‌మెంట్ జోడించు\" నొక్కండి. అది గడువు కావడానికి ముందు మీకు గుర్తు చేయబడుతుంది.",
        "Tap a medicine to expand" to "విస్తరించడానికి మందుపై నొక్కండి",
        "Tap any point to open that report" to "ఆ నివేదికను తెరవడానికి ఏదైనా పాయింట్‌ను నొక్కండి",
        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "మీ పరికరం నుండి చిత్రం, PDF లేదా డాక్‌ను ఎంచుకోవడానికి ఇక్కడ నొక్కండి, లేదా ఫోటో తీయడానికి క్రింద కెమెరాను ఉపయోగించండి.",
        "Tap play to hear this summary" to "ఈ సారాంశాన్ని వినడానికి ప్లే నొక్కండి",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "మీ ఫోన్ మరియు జత చేసిన వాచ్‌లో మందుల రిమైండర్‌లు కనిపించడానికి అనుమతించడానికి నొక్కండి.",
        "Tap to pick\nImage or PDF" to "ఎంచుకోవడానికి నొక్కండి\nచిత్రం లేదా PDF",
        "Tap to select" to "ఎంచుకోవడానికి నొక్కండి",
        "Tap to view" to "చూడటానికి నొక్కండి",
        "Test Parameter Changes" to "పరీక్ష పరామితి మార్పులు",
        "Test group" to "పరీక్ష సమూహం",
        "Tested Parameters" to "పరీక్షించిన పారామితులు",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "ప్రిస్క్రిప్షన్‌లలో సిఫార్సు చేసిన పరీక్షలు స్వయంచాలకంగా ట్రాక్ చేయబడతాయి. మీరు వాటిని మాన్యువల్‌గా కూడా జోడించవచ్చు.",
        "That QR code doesn't contain a report link." to "ఆ QR కోడ్‌లో నివేదిక లింక్ లేదు.",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "సదుపాయం 10 నిమిషాల్లో SMS/WhatsApp ద్వారా మీ స్లాట్‌ను నిర్ధారిస్తుంది.",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "ఎంచుకున్న ఫైల్‌లు చాలా పెద్దవి (%.2f MB). ఈ ఫైల్‌లను ప్రాసెస్ చేయడానికి ఎక్కువ సమయం పడుతుంది మరియు మెమరీ సమస్యలు రావచ్చు. ఫైల్‌లను 10 MB కంటే తక్కువగా ఉంచాలని మేము సిఫార్సు చేస్తున్నాము. మీరు అయినా కొనసాగించాలనుకుంటున్నారా?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "ఇది నిజం కాదు. దీన్ని తీసివేయండి, లేదా మీ స్వంత రికార్డులను ట్రాక్ చేయడం ప్రారంభించడానికి సైన్ ఇన్ చేయండి.",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "ఇది అన్ని నివేదికలు, మందులు, పెండింగ్ పరీక్షలు మరియు చిత్రాలను శాశ్వతంగా తొలగిస్తుంది. దీన్ని రద్దు చేయలేరు.",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "ఇది అసలు స్కాన్ చేసిన చిత్రంపై AI విశ్లేషణను మళ్లీ నడిపి క్రింద ఉన్న సేకరించిన పరీక్ష విలువలు, మందులు మరియు అంతర్దృష్టులను రిఫ్రెష్ చేస్తుంది. మునుపటి స్కాన్ అసంపూర్తిగా వచ్చినట్లయితే (ఉదా. API కొద్దిసేపు అందుబాటులో లేకపోతే) ఇది ఉపయోగకరం. ఇది మీ కొన్ని API కోటాను ఉపయోగించవచ్చు.",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "ఈ నివేదిక యొక్క ఫైల్ సేవ్ చేయబడింది కానీ AI ద్వారా విశ్లేషించబడలేదు, కాబట్టి దీనికి ఇంకా పరీక్ష విలువలు, ధోరణులు లేదా అంతర్దృష్టులు లేవు. మీరు సిద్ధంగా ఉన్నప్పుడు దీన్ని విశ్లేషించండి (కొంత API కోటాను ఉపయోగిస్తుంది).",
        "Time (HH:MM)" to "సమయం (HH:MM)",
        "Tip: 1-0-1 = morning & night, 1-1-1 = three times a day." to "చిట్కా: 1-0-1 = ఉదయం & రాత్రి, 1-1-1 = రోజుకు మూడుసార్లు.",
        "Tips" to "చిట్కాలు",
        "To" to "కి",
        "Today's free pool quota is used up. Add a personal API key below for unlimited scans, or wait until tomorrow." to "నేటి ఉచిత పూల్ కోటా ఖర్చయిపోయింది. అపరిమిత స్కాన్‌ల కోసం క్రింద వ్యక్తిగత API కీని జోడించండి, లేదా రేపటి వరకు వేచి ఉండండి.",
        "Toggle" to "టోగుల్ చేయండి",
        "Toggle text" to "టోగుల్ టెక్స్ట్",
        "Transfer Records" to "రికార్డులను బదిలీ చేయండి",
        "Translates this intent using AI to target specific lab emails." to "నిర్దిష్ట ల్యాబ్ ఇమెయిల్‌లను లక్ష్యంగా చేసుకోవడానికి AIని ఉపయోగించి ఈ ఉద్దేశాన్ని అనువదిస్తుంది.",
        "Trend" to "ధోరణి",
        "Trends Overview" to "ధోరణుల అవలోకనం",
        "Trends appear once you have reports with numeric test values like TSH, sugar, hemoglobin, cholesterol." to "మీ వద్ద TSH, చక్కెర, హీమోగ్లోబిన్, కొలెస్ట్రాల్ వంటి సంఖ్యా పరీక్ష విలువలు కలిగిన నివేదికలు ఉన్నప్పుడు ధోరణులు కనిపిస్తాయి.",
        "Try Demo" to "డెమోను ప్రయత్నించండి",
        "Try searching a different name" to "వేరే పేరును శోధించడానికి ప్రయత్నించండి",
        "UHI Registered" to "UHI నమోదు చేయబడింది",
        "Unknown" to "తెలియదు",
        "Upcoming Appointment" to "రాబోయే అపాయింట్‌మెంట్",
        "Update Password" to "పాస్‌వర్డ్‌ను నవీకరించండి",
        "Upload Only (No Scan)" to "అప్‌లోడ్ మాత్రమే (స్కాన్ లేదు)",
        "Upload only" to "అప్‌లోడ్ మాత్రమే",
        "Upload two reports, prescriptions, or scans to compare what changed between them." to "వాటి మధ్య ఏమి మారిందో పోల్చడానికి రెండు నివేదికలు, ప్రిస్క్రిప్షన్‌లు లేదా స్కాన్‌లను అప్‌లోడ్ చేయండి.",
        "Uploaded — not analyzed yet" to "అప్‌లోడ్ చేయబడింది — ఇంకా విశ్లేషించబడలేదు",
        "Uploaded. Open it later to analyze when you're ready." to "అప్‌లోడ్ చేయబడింది. మీరు సిద్ధంగా ఉన్నప్పుడు విశ్లేషించడానికి తర్వాత తెరవండి.",
        "Use GPS" to "GPS ఉపయోగించండి",
        "Use your fingerprint to quickly sign in next time without waiting for an OTP or entering passwords." to "తదుపరిసారి OTP కోసం వేచి ఉండకుండా లేదా పాస్‌వర్డ్‌లు నమోదు చేయకుండా త్వరగా సైన్ ఇన్ చేయడానికి మీ వేలిముద్రను ఉపయోగించండి.",
        "Using your individual Gemini API key — unlimited scans, bypassing the free tier limits." to "మీ వ్యక్తిగత Gemini API కీని ఉపయోగిస్తోంది — అపరిమిత స్కాన్‌లు, ఉచిత టైర్ పరిమితులను దాటవేసి.",
        "Value" to "విలువ",
        "Verification timed out. Please try again." to "ధృవీకరణ సమయం ముగిసింది. దయచేసి మళ్లీ ప్రయత్నించండి.",
        "Verify & Create Account" to "ధృవీకరించి ఖాతా సృష్టించండి",
        "Verify & Log In" to "ధృవీకరించి లాగిన్ చేయండి",
        "View Detailed Analysis" to "వివరణాత్మక విశ్లేషణను చూడండి",
        "View Previous Report" to "మునుపటి నివేదికను చూడండి",
        "View Report" to "నివేదికను చూడండి",
        "View Scanned Report" to "స్కాన్ చేసిన నివేదికను చూడండి",
        "View details" to "వివరాలను చూడండి",
        "View existing document" to "ఇప్పటికే ఉన్న పత్రాన్ని చూడండి",
        "Voice (Read Aloud)" to "వాయిస్ (గట్టిగా చదవండి)",
