        "W" to "W",
        "Waiting for UHI webhook callbacks..." to "UHI వెబ్‌హుక్ కాల్‌బ్యాక్‌ల కోసం వేచి ఉంది...",
        "Watch Out For:" to "వీటిపై జాగ్రత్త వహించండి:",
