        "What This Report Means" to "ఈ నివేదిక అర్థం ఏమిటి",
        "What is this medicine for?" to "ఈ మందు దేనికి?",
        "Which voice reads answers aloud. Sarvam & Gemini speak Indian languages well; Phone uses your device's built-in voices (may not have Marathi)." to "ఏ వాయిస్ సమాధానాలను గట్టిగా చదువుతుంది. Sarvam & Gemini భారతీయ భాషలను బాగా మాట్లాడతాయి; ఫోన్ మీ పరికరం యొక్క అంతర్నిర్మిత వాయిస్‌లను ఉపయోగిస్తుంది (మరాఠీ ఉండకపోవచ్చు).",
        "Who is this report for?" to "ఈ నివేదిక ఎవరి కోసం?",
