        "Within:" to "దీనిలో:",
        "Yes, Import" to "అవును, దిగుమతి చేయండి",
        "You can manually correct spelling mistakes in the Patient Name, Date, or Type below. Tapping the Save (Checkmark) icon in the top right will update the history database." to "మీరు క్రింద రోగి పేరు, తేదీ, లేదా రకంలో స్పెల్లింగ్ తప్పులను మాన్యువల్‌గా సరిచేయవచ్చు. పైన కుడివైపు సేవ్ (చెక్‌మార్క్) ఐకాన్‌ను నొక్కడం చరిత్ర డేటాబేస్‌ను నవీకరిస్తుంది.",
        "You haven't linked an email account yet. Please go to Settings (Account tab) to link your Gmail account or IMAP details first." to "మీరు ఇంకా ఇమెయిల్ ఖాతాను లింక్ చేయలేదు. మీ Gmail ఖాతా లేదా IMAP వివరాలను ముందుగా లింక్ చేయడానికి సెట్టింగ్‌లు (ఖాతా ట్యాబ్)‌కు వెళ్లండి.",
        "You're using Health Decoder without an account" to "మీరు ఖాతా లేకుండా Health Decoderను ఉపయోగిస్తున్నారు",
        "and set your new password." to "మరియు మీ కొత్త పాస్‌వర్డ్‌ను సెట్ చేయండి.",
        "at" to "వద్ద",
        "chars). It will be analyzed with any images." to "అక్షరాలు). ఇది ఏవైనా చిత్రాలతో విశ్లేషించబడుతుంది.",
        "e.g. 1 tablet" to "ఉదా. 1 టాబ్లెట్",
        "e.g. 1-0-1" to "ఉదా. 1-0-1",
        "e.g. 1-0-1, twice daily, as needed" to "ఉదా. 1-0-1, రోజుకు రెండుసార్లు, అవసరమైనప్పుడు",
        "e.g. 2026-09-22" to "ఉదా. 2026-09-22",
        "e.g. 5 days" to "ఉదా. 5 రోజులు",
        "e.g. Apollo, Metropolis, Fortis" to "ఉదా. అపోలో, మెట్రోపోలిస్, ఫోర్టిస్",
        "e.g. Blood Sugar Fasting (BSF)" to "ఉదా. బ్లడ్ షుగర్ ఫాస్టింగ్ (BSF)",
        "e.g. CBC, Lipid, Thyroid..." to "ఉదా. CBC, లిపిడ్, థైరాయిడ్...",
        "e.g. John Doe" to "ఉదా. జాన్ డో",
        "e.g. Metformin 500mg" to "ఉదా. మెట్‌ఫార్మిన్ 500mg",
        "e.g. Rajesh Kumar" to "ఉదా. రాజేష్ కుమార్",
        "e.g. Take with warm water" to "ఉదా. గోరువెచ్చని నీటితో తీసుకోండి",
        "new report(s) — check your notifications." to "కొత్త నివేదిక(లు) — మీ నోటిఫికేషన్‌లను తనిఖీ చేయండి.",
        "on" to "న",
        "online" to "ఆన్‌లైన్",
        "page(s) selected. Add more pages of the SAME report, then analyze." to "పేజీ(లు) ఎంపిక చేయబడ్డాయి. అదే నివేదిక యొక్క మరిన్ని పేజీలను జోడించి, తర్వాత విశ్లేషించండి.",
        "per scan — extra pages were skipped. Analyze these first, then scan the rest." to "స్కాన్‌కు — అదనపు పేజీలు దాటవేయబడ్డాయి. వీటిని ముందుగా విశ్లేషించి, తర్వాత మిగిలినవి స్కాన్ చేయండి.",
        "report(s) on file" to "నివేదిక(లు) ఫైల్‌లో ఉన్నాయి",
        "selected" to "ఎంపిక చేయబడింది",
        "starting" to "ప్రారంభమై",
        "your account" to "మీ ఖాతా",
        "ℹ️ AI-generated reference. Always consult your doctor for medical advice." to "ℹ️ AI-రూపొందించిన సూచన. వైద్య సలహా కోసం ఎల్లప్పుడూ మీ డాక్టర్‌ను సంప్రదించండి.",
        "● LIVE" to "● లైవ్",
        "⚙️  Manage / edit family" to "⚙️  కుటుంబాన్ని నిర్వహించండి / సవరించండి",
        "➕  New person…" to "➕  కొత్త వ్యక్తి…",
        "🎙️ Ask AI" to "🎙️ AIని అడగండి",
        "👨‍👩‍👧 Everyone" to "👨‍👩‍👧 అందరూ",
        "📸 Identify" to "📸 గుర్తించండి",
        "🧪 You're viewing sample demo data" to "🧪 మీరు నమూనా డెమో డేటాను చూస్తున్నారు",
        "Medication Reminders" to "మందుల రిమైండర్‌లు",
        "Find Doctors" to "డాక్టర్లను కనుగొనండి",
        "Find Hospitals" to "ఆసుపత్రులను కనుగొనండి",
        "Doctor Brief" to "డాక్టర్ సారాంశం",
        "Scan any medical report" to "ఏదైనా వైద్య నివేదికను స్కాన్ చేయండి",
        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "కాగితం ల్యాబ్ నివేదికలు, ప్రిస్క్రిప్షన్‌లు మరియు డిశ్చార్జ్ సారాంశాలను వ్యవస్థీకృత, శోధించదగిన డిజిటల్ రికార్డులుగా మార్చండి — నేరుగా మీ ఫోన్ కెమెరా నుండి.",
        "Understand it instantly" to "దీన్ని తక్షణమే అర్థం చేసుకోండి",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI పేజీలోని ప్రతి పరీక్ష విలువ, మందు మరియు తేదీని చదువుతుంది, తద్వారా వైద్య పరిభాషలో చిక్కుకోకుండా నివేదిక నిజంగా అర్థం ఏమిటో మీరు చూడగలరు.",
        "Never miss a dose or a follow-up" to "ఎప్పుడూ మోతాదు లేదా ఫాలో-అప్‌ను మిస్ చేయకండి",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "మందుల రిమైండర్‌లు ప్రతిరోజూ సరైన సమయంలో మోగుతాయి — వారానికి రెండుసార్లు తీసుకునే మందుకు కూడా — మరియు డాక్టర్ అపాయింట్‌మెంట్‌లకు కూడా వాటి స్వంత రిమైండర్ ఉంటుంది.",
        "What do my latest test results mean?" to "నా తాజా పరీక్ష ఫలితాల అర్థం ఏమిటి?",
        "Explain my current medicines in simple words" to "నా ప్రస్తుత మందులను సాధారణ మాటల్లో వివరించండి",
        "Are any of my values abnormal?" to "నా విలువలలో ఏవైనా అసాధారణంగా ఉన్నాయా?",
        "What should I ask my doctor next?" to "నేను తర్వాత నా డాక్టర్‌ను ఏమి అడగాలి?",
        "Rx" to "Rx",
        "Hospitals" to "ఆసుపత్రులు",
        "Lab Tests" to "ల్యాబ్ పరీక్షలు",
        "Doctors" to "డాక్టర్లు",
        "Broadcasting search to UHI gateway..." to "UHI గేట్‌వేకు శోధన ప్రసారం చేయబడుతోంది...",
        "Gateway ACK received. Listening for provider webhook responses..." to "గేట్‌వే ACK స్వీకరించబడింది. ప్రొవైడర్ వెబ్‌హుక్ ప్రతిస్పందనల కోసం వింటోంది...",
        "Listening for provider webhooks... (Incoming responses)" to "ప్రొవైడర్ వెబ్‌హుక్‌ల కోసం వింటోంది... (వస్తున్న ప్రతిస్పందనలు)",
        "3M" to "3 నెలలు",
        "6M" to "6 నెలలు",
        "1Y" to "1 సంవత్సరం",
        "2Y" to "2 సంవత్సరాలు",
        "10 km" to "10 కి.మీ",
        "20 km" to "20 కి.మీ",
        "50 km" to "50 కి.మీ",
        "Any" to "ఏదైనా",
        "Couldn't load your account. Check your connection and try again." to "మీ ఖాతాను లోడ్ చేయలేకపోయాము. మీ కనెక్షన్‌ను తనిఖీ చేసి మళ్లీ ప్రయత్నించండి.",
        "Please enter a valid API key or tap 'Revert to Shared Pool'." to "దయచేసి చెల్లుబాటు అయ్యే API కీని నమోదు చేయండి లేదా 'షేర్డ్ పూల్‌కు తిరిగి వెళ్ళండి' నొక్కండి.",
        "Personal API Key saved! Switched to Individual Key mode." to "వ్యక్తిగత API కీ సేవ్ చేయబడింది! వ్యక్తిగత కీ మోడ్‌కు మార్చబడింది.",
        "Reverted to Primary Shared Key Pool." to "ప్రైమరీ షేర్డ్ కీ పూల్‌కు తిరిగి వెళ్లబడింది.",
        "All fields are required." to "అన్ని ఫీల్డ్‌లు అవసరం.",
        "New password must be at least 6 characters." to "కొత్త పాస్‌వర్డ్ కనీసం 6 అక్షరాలు ఉండాలి.",
        "Password updated successfully." to "పాస్‌వర్డ్ విజయవంతంగా నవీకరించబడింది.",
        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "సహాయకుడిని చేరుకోలేకపోయాము. సర్వర్ నడుస్తుందని మరియు సెట్టింగ్‌లలో కాన్ఫిగర్ చేయబడిందని తనిఖీ చేయండి.",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "ఈ పరికరంలో వాయిస్ ఇన్‌పుట్ అందుబాటులో లేదు. దయచేసి Google వాయిస్ టైపింగ్‌ను ఇన్‌స్టాల్/ప్రారంభించండి.",
        "Couldn't generate the detailed analysis. Please try again." to "వివరణాత్మక విశ్లేషణను రూపొందించలేకపోయాము. దయచేసి మళ్లీ ప్రయత్నించండి.",
        "Search failed. Make sure the backend server is running and database is migrated." to "శోధన విఫలమైంది. బ్యాకెండ్ సర్వర్ నడుస్తోందని మరియు డేటాబేస్ మైగ్రేట్ చేయబడిందని నిర్ధారించుకోండి.",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "మందులను పొందడంలో విఫలమైంది. మీ స్థానిక సర్వర్ నడుస్తోందని మరియు సెట్టింగ్‌లలో సరిగ్గా కాన్ఫిగర్ చేయబడిందని నిర్ధారించుకోండి.",
        "Failed to delete the selected medicines." to "ఎంచుకున్న మందులను తొలగించడంలో విఫలమైంది.",
        "Failed to update the selected medicines." to "ఎంచుకున్న మందులను నవీకరించడంలో విఫలమైంది.",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "పెండింగ్ పరీక్షలను పొందడంలో విఫలమైంది. మీ స్థానిక సర్వర్ నడుస్తోందని మరియు సెట్టింగ్‌లలో సరిగ్గా కాన్ఫిగర్ చేయబడిందని నిర్ధారించుకోండి.",
        "Failed to delete test reminder." to "పరీక్ష రిమైండర్‌ను తొలగించడంలో విఫలమైంది.",
        "Patient and Test names are required." to "రోగి మరియు పరీక్ష పేర్లు అవసరం.",
        "Failed to save test reminder." to "పరీక్ష రిమైండర్‌ను సేవ్ చేయడంలో విఫలమైంది.",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "రికార్డులను పొందడంలో విఫలమైంది. మీ స్థానిక సర్వర్ నడుస్తోందని మరియు సెట్టింగ్‌లలో సరిగ్గా కాన్ఫిగర్ చేయబడిందని నిర్ధారించుకోండి.",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "రిమైండర్‌లను పొందడంలో విఫలమైంది. మీ స్థానిక సర్వర్ నడుస్తోందని మరియు సెట్టింగ్‌లలో సరిగ్గా కాన్ఫిగర్ చేయబడిందని నిర్ధారించుకోండి.",
        "Couldn't save the file." to "ఫైల్‌ను సేవ్ చేయలేకపోయాము.",
        "No app available to open this file type." to "ఈ ఫైల్ రకాన్ని తెరవడానికి యాప్ అందుబాటులో లేదు.",
        "Couldn't share this file." to "ఈ ఫైల్‌ను షేర్ చేయలేకపోయాము.",
        "Report not found." to "నివేదిక కనుగొనబడలేదు.",
        "Failed to load report details." to "నివేదిక వివరాలను లోడ్ చేయడంలో విఫలమైంది.",
        "Failed to save edits. Check network settings." to "సవరణలను సేవ్ చేయడంలో విఫలమైంది. నెట్‌వర్క్ సెట్టింగ్‌లను తనిఖీ చేయండి.",
        "Failed to delete report." to "నివేదికను తొలగించడంలో విఫలమైంది.",
        "Couldn't reprocess: report or its scanned image is missing." to "మళ్లీ ప్రాసెస్ చేయలేకపోయాము: నివేదిక లేదా దాని స్కాన్ చేసిన చిత్రం లేదు.",
        "Failed to reprocess this report." to "ఈ నివేదికను మళ్లీ ప్రాసెస్ చేయడంలో విఫలమైంది.",
        "Medicine name is required." to "మందు పేరు అవసరం.",
        "Select at least one reminder slot." to "కనీసం ఒక రిమైండర్ స్లాట్‌ను ఎంచుకోండి.",
        "Doctor name is required." to "డాక్టర్ పేరు అవసరం.",
        "Place is required." to "ప్రదేశం అవసరం.",
        "Date is required." to "తేదీ అవసరం.",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "ఈ పరికరం యొక్క సురక్షిత హార్డ్‌వేర్ నిల్వ అందుబాటులో లేదు, కాబట్టి మీ లోకల్ రికార్డ్స్ కీ మరియు లింక్ చేయబడిన-ఇమెయిల్ ఆధారాలు హార్డ్‌వేర్-ఆధారిత ఎన్‌క్రిప్షన్ లేకుండా నిల్వ చేయబడతాయి. మీ డేటా ఇప్పటికీ అసురక్షితంగా ఎక్కడికీ పంపబడదు, కానీ ఈ పరికరం సాధారణం కంటే బలహీనమైన రక్షణను అందిస్తుంది.",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "స్కానింగ్, రిమైండర్‌లు మరియు మిగతావన్నీ ఈ పరికరంలో సైన్ ఇన్ చేయకుండా పూర్తిగా పనిచేస్తాయి. సైన్ ఇన్ ఐచ్ఛికం (ఇది SMS కోడ్‌ను పంపుతుంది, కాబట్టి ఇది స్వయంచాలకం కాదు) — పరికరాలలో మీతో పాటు వచ్చే ప్రొఫైల్ లేదా వ్యక్తిగత API కీ కావాలంటే దీన్ని ఉపయోగించండి.",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "ప్రతి ధోరణి చార్ట్ రీడింగ్‌లను ప్రామాణీకరించే యూనిట్. వేరే యూనిట్‌లోని నివేదికలు స్వయంచాలకంగా మార్చబడతాయి; ప్రతి నివేదిక ఇప్పటికీ దాని అసలు విలువను చూపిస్తుంది.",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "ఎందుకు: Health Decoder ఖర్చులను తక్కువగా ఉంచడం ద్వారా ఉచితంగా ఉంటుంది, మీ రికార్డులను అమ్మడం ద్వారా కాదు. మీరు ఇక్కడ చేరితే, మీ వయస్సు మరియు లింగం మాత్రమే — మీ పేరు, నివేదికలు లేదా ఖచ్చితమైన స్థానం ఎప్పుడూ కాదు — వైద్య పరిశోధన సంస్థలతో సమిష్టిగా పంచుకోబడుతుంది, ప్రకటనలు నడపడం లేదా చందా వసూలు చేయడం కంటే ప్రతి కుటుంబానికి యాప్‌ను ఉచితంగా ఉంచడంలో సహాయపడటానికి.",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "ఈ ప్రోగ్రామ్ ఇంకా ప్రారంభించలేదు — ఈరోజు దీన్ని ఆన్ చేయడం మీ ప్రాధాన్యతను మాత్రమే సేవ్ చేస్తుంది. నిజమైన డేటా-షేరింగ్ పైప్‌లైన్ ఉనికిలో ఉండే వరకు ఏదీ ఎక్కడికీ పంపబడదు, మరియు మీరు ఎప్పుడైనా ఇక్కడ మీ సమాధానాన్ని మార్చుకోవచ్చు.",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "ఇది మీ Health Decoder ఖాతా మరియు ఈ పరికరంలో నిల్వ చేయబడిన అన్ని వైద్య రికార్డులను — నివేదికలు, రిమైండర్‌లు, అపాయింట్‌మెంట్‌లు మరియు కుటుంబ ప్రొఫైల్‌లు — శాశ్వతంగా తొలగిస్తుంది. దీన్ని రద్దు చేయలేరు.",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "సూచించబడుతుంది, అలాగే ముఖ్య చిట్కాలు కూడా. మొదటి శోధన ఇంటర్నెట్‌ను ఉపయోగిస్తుంది, తర్వాత అది సేవ్ చేయబడుతుంది తద్వారా తదుపరిసారి తక్షణమే తెరుచుకుంటుంది.",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "ఉదాహరణ నివేదికలు, రిమైండర్‌లు మరియు ఇప్పటికే నింపిన అపాయింట్‌మెంట్‌తో, తద్వారా మీరు నిజమైనదాన్ని స్కాన్ చేయడానికి ముందు ప్రతి స్క్రీన్‌ను అన్వేషించవచ్చు. ఖాతా నుండి దీన్ని ఎప్పుడైనా తీసివేయండి.",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ఆ QR ఒక వెబ్ పేజీని తెరిచింది, నేరుగా ఫైల్ కాదు. దీన్ని మీ బ్రౌజర్‌లో తెరుస్తోంది — అక్కడ నివేదికను డౌన్‌లోడ్ చేయండి, తర్వాత దాన్ని దిగుమతి చేయడానికి \"పరికరం నుండి\" ఉపయోగించండి.",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "పెద్ద పత్రాలను విశ్లేషణ కోసం విభజించే విధానంలో సవరణ జరగడానికి ముందు %1\$d బహు-పేజీ స్కాన్‌లు ప్రాసెస్ అయ్యాయి — అదే పత్రంలోని ఒక ప్యానెల్ (ఉదా. ఎలక్ట్రోలైట్స్ లేదా PT/INR పేజీ) మిస్ అయి ఉండవచ్చు. ఇది ఇప్పటికే సేవ్ చేసిన పేజీలను ఉపయోగించి వాటిని మళ్లీ తనిఖీ చేసి, మిస్ అయినదాన్ని జోడిస్తుంది; ఇప్పటికే సేవ్ అయినది అలాగే ఉంటుంది.",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "AI విశ్లేషణ సర్వర్ అందుబాటులో లేని సమయంలో %1\$d నివేదిక(లు) సేవ్ అయ్యాయి (ఉదా. రోజువారీ కోటా పూర్తయింది), కాబట్టి వాటి తేదీ మరియు వర్గం పత్రం నుండి చదివినవి కాక ఊహించినవి. మళ్లీ విశ్లేషణ ఇప్పటికే నిల్వ చేసిన చిత్రాలను ఉపయోగిస్తుంది — మీరు వాటిని మళ్లీ స్కాన్ చేయనవసరం లేదు.",
        "Add, edit, or remove people this device tracks — including yourself" to "ఈ పరికరం ట్రాక్ చేసే వ్యక్తులను జోడించండి, సవరించండి లేదా తీసివేయండి — మిమ్మల్ని కలుపుకుని",
        "Also protect automatic backups with a password" to "స్వయంచాలక బ్యాకప్‌లను కూడా పాస్‌వర్డ్‌తో రక్షించండి",
        "Auto-backup password" to "స్వయం-బ్యాకప్ పాస్‌వర్డ్",
        "Backup password" to "బ్యాకప్ పాస్‌వర్డ్",
        "Based on your %1\$s result (%2\$s) from your report dated %3\$s." to "%3\$s నాటి మీ నివేదికలోని %1\$s ఫలితం (%2\$s) ఆధారంగా.",
        "Blood" to "రక్తం",
        "Brief" to "సారాంశం",
        "Chat" to "చాట్",
        "Check Now (%1\$d)" to "ఇప్పుడే తనిఖీ చేయండి (%1\$d)",
        "Check for Missing Report Data" to "తప్పిపోయిన నివేదిక డేటా కోసం తనిఖీ చేయండి",
        "Checking %1\$d of %2\$d…" to "%2\$d లో %1\$d తనిఖీ అవుతోంది…",
        "Compare" to "పోలిక",
        "Confirm password" to "పాస్‌వర్డ్‌ను నిర్ధారించండి",
        "Data Management" to "డేటా నిర్వహణ",
        "Date of Birth (YYYY-MM-DD)" to "పుట్టిన తేదీ (YYYY-MM-DD)",
        "Discharge Summary" to "డిశ్చార్జ్ సారాంశం",
        "Discharge Summary + Prescription" to "డిశ్చార్జ్ సారాంశం + ప్రిస్క్రిప్షన్",
        "Echo" to "ఎకో",
        "Edit Profile" to "ప్రొఫైల్‌ను సవరించండి",
        "Edit profile" to "ప్రొఫైల్‌ను సవరించండి",
        "Ends" to "ముగింపు",
        "Enter Backup Password" to "బ్యాకప్ పాస్‌వర్డ్ నమోదు చేయండి",
        "Every" to "ప్రతి",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restoring REPLACES everything currently on this device." to "మీ అన్ని రికార్డులను (నివేదికలు + చిత్రాలు) ఒకే బ్యాకప్ ఫైల్‌గా ఎగుమతి చేయండి. క్లౌడ్ కాపీ ఉంచుకోవడానికి పికర్‌లో మీ Google Drive లేదా OneDrive ఫోల్డర్‌ను ఎంచుకోండి. పునరుద్ధరిస్తే ఈ పరికరంలో ప్రస్తుతం ఉన్నదంతా మారిపోతుంది.",
        "Family Members" to "కుటుంబ సభ్యులు",
        "First Name" to "మొదటి పేరు",
        "Free Gemini API Key (Optional)" to "ఉచిత Gemini API కీ (ఐచ్ఛికం)",
        "Full Backup & Restore" to "పూర్తి బ్యాకప్ & పునరుద్ధరణ",
        "General lifestyle suggestion, not medical advice — talk to your doctor before making changes based on a lab result." to "సాధారణ జీవనశైలి సూచన, వైద్య సలహా కాదు — ల్యాబ్ ఫలితం ఆధారంగా మార్పులు చేసే ముందు మీ వైద్యుడితో మాట్లాడండి.",
        "Get Free API Key" to "ఉచిత API కీ పొందండి",
        "Got it" to "అర్థమైంది",
        "HEALTH TIP" to "ఆరోగ్య చిట్కా",
        "Health Decoder" to "హెల్త్ డీకోడర్",
        "Hello," to "నమస్కారం,",
        "High" to "ఎక్కువ",
        "Home" to "హోమ్",
        "Last Name" to "ఇంటి పేరు",
        "Learn More" to "మరింత తెలుసుకోండి",
        "Leave blank to keep the current one" to "ప్రస్తుతం ఉన్నదే ఉంచడానికి ఖాళీగా వదిలేయండి",
        "Live camera scan — point and get instant answers" to "లైవ్ కెమెరా స్కాన్ — కెమెరా చూపించి వెంటనే సమాధానాలు పొందండి",
        "Low" to "తక్కువ",
        "Medical Report" to "వైద్య నివేదిక",
        "Not set" to "సెట్ చేయలేదు",
        "Not signed in" to "సైన్ ఇన్ కాలేదు",
