        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "షేర్ / విలీనం ఎంచుకున్నదాన్ని మరో ఫోన్‌కు లేదా వైద్యుడికి పంపి అక్కడ ఉన్నదానికి జోడిస్తుంది. బ్యాకప్ & పునరుద్ధరణ అనేది ఈ పరికరం యొక్క పూర్తి స్నాప్‌షాట్ — పునరుద్ధరించినప్పుడు అంతా మారిపోతుంది, కాబట్టి దాన్ని షేరింగ్ కోసం కాక విపత్తు రికవరీ కోసం వాడండి.",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "మీ పేరు, వివరాలు సవరించడానికి, వ్యక్తిగత API కీ ఉపయోగించడానికి, వేలిముద్ర లాగిన్ ప్రారంభించడానికి సైన్ ఇన్ చేయండి. అది లేకుండా కూడా యాప్ పూర్తిగా పనిచేస్తుంది — మీ కుటుంబ సభ్యులు, రికార్డులు ఇప్పటికే ఈ పరికరంలోనే ఉన్నాయి.",
        "Sign in to sync your records" to "మీ రికార్డులను సింక్ చేయడానికి సైన్ ఇన్ చేయండి",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "దీన్ని దాటవేస్తే యాప్ డిఫాల్ట్‌గా భాగస్వామ్య ఉచిత పూల్‌ను ఉపయోగిస్తుంది. మీ సొంత కీని ముందుగానే జోడిస్తే ఆ పూల్ రోజువారీ పరిమితి మిమ్మల్ని ఎప్పుడూ ఆపదు.",
