        "Tap to pick\nImage or PDF" to "ఎంచుకోవడానికి నొక్కండి\nచిత్రం లేదా PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ఆ QR ఒక వెబ్ పేజీని తెరిచింది, నేరుగా ఫైల్‌ను కాదు. దాన్ని మీ బ్రౌజర్‌లో తెరుస్తున్నాం — అక్కడ నివేదికను డౌన్‌లోడ్ చేసి, ఆపై దాన్ని దిగుమతి చేయడానికి \"పరికరం నుండి\" ఉపయోగించండి.",
