        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "మర్చిపోతే దీన్ని రీసెట్ చేసే మార్గం లేదు — దీన్ని ఎక్కడైనా సురక్షితంగా రాసి ఉంచుకోండి. బ్యాకప్ పాస్‌వర్డ్ పోతే ఆ బ్యాకప్‌ను ఎప్పటికీ పునరుద్ధరించలేరు.",
