        "All patients" to "ಎಲ್ಲಾ ರೋಗಿಗಳು",
        "All search results, doctor availability, and diagnostic slots are purely informational. Sourced from the public UHI network, they are not clinical recommendations or confirmed appointments. Do not rely solely on this information. Always consult a qualified medical professional for health concerns." to "ಎಲ್ಲಾ ಹುಡುಕಾಟ ಫಲಿತಾಂಶಗಳು, ವೈದ್ಯರ ಲಭ್ಯತೆ ಮತ್ತು ರೋಗನಿರ್ಣಯ ಸ್ಲಾಟ್‌ಗಳು ಕೇವಲ ಮಾಹಿತಿಗಾಗಿ ಮಾತ್ರ. ಸಾರ್ವಜನಿಕ UHI ನೆಟ್‌ವರ್ಕ್‌ನಿಂದ ಪಡೆದಿದ್ದು, ಇವು ವೈದ್ಯಕೀಯ ಶಿಫಾರಸುಗಳು ಅಥವಾ ದೃಢಪಡಿಸಿದ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್‌ಗಳಲ್ಲ. ಕೇವಲ ಈ ಮಾಹಿತಿಯ ಮೇಲೆ ಅವಲಂಬಿತರಾಗಬೇಡಿ. ಆರೋಗ್ಯ ಸಮಸ್ಯೆಗಳಿಗೆ ಯಾವಾಗಲೂ ಅರ್ಹ ವೈದ್ಯಕೀಯ ವೃತ್ತಿಪರರನ್ನು ಸಂಪರ್ಕಿಸಿ.",
        "Analysing your report…" to "ನಿಮ್ಮ ವರದಿಯನ್ನು ವಿಶ್ಲೇಷಿಸಲಾಗುತ್ತಿದೆ…",
        "Analyze & Scan Document" to "ದಾಖಲೆಯನ್ನು ವಿಶ್ಲೇಷಿಸಿ ಮತ್ತು ಸ್ಕ್ಯಾನ್ ಮಾಡಿ",
        "Analyze Now" to "ಈಗಲೇ ವಿಶ್ಲೇಷಿಸಿ",
