        "Are you sure you want to delete this medical report? This will permanently remove the record from your database and delete the uploaded image file." to "ಈ ವೈದ್ಯಕೀಯ ವರದಿಯನ್ನು ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ಇದು ನಿಮ್ಮ ಡೇಟಾಬೇಸ್‌ನಿಂದ ದಾಖಲೆಯನ್ನು ಶಾಶ್ವತವಾಗಿ ತೆಗೆದುಹಾಕುತ್ತದೆ ಮತ್ತು ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಇಮೇಜ್ ಫೈಲ್ ಅನ್ನು ಅಳಿಸುತ್ತದೆ.",
