        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restore re-imports a backup file." to "ನಿಮ್ಮ ಎಲ್ಲಾ ದಾಖಲೆಗಳನ್ನು (ವರದಿಗಳು + ಚಿತ್ರಗಳು) ಒಂದೇ ಬ್ಯಾಕಪ್ ಫೈಲ್ ಆಗಿ ರಫ್ತು ಮಾಡಿ. ಕ್ಲೌಡ್ ಪ್ರತಿ ಇಡಲು ಪಿಕರ್‌ನಲ್ಲಿ ನಿಮ್ಮ Google Drive ಅಥವಾ OneDrive ಫೋಲ್ಡರ್ ಆಯ್ಕೆಮಾಡಿ. ಮರುಸ್ಥಾಪನೆ ಬ್ಯಾಕಪ್ ಫೈಲ್ ಅನ್ನು ಮತ್ತೆ ಆಮದು ಮಾಡುತ್ತದೆ.",
