        "Health Decoder Logo" to "ಹೆಲ್ತ್ ಡಿಕೋಡರ್ ಲೋಗೋ",
        "Health Decoder requires your permission to connect to your email inbox. We will only search for emails from the last 2 days containing potential medical report attachments (PDFs) and extract them locally on your phone. No email contents are sent to our servers. Do you consent to this?" to "ನಿಮ್ಮ ಇಮೇಲ್ ಇನ್‌ಬಾಕ್ಸ್‌ಗೆ ಸಂಪರ್ಕಿಸಲು Health Decoder ಗೆ ನಿಮ್ಮ ಅನುಮತಿ ಅಗತ್ಯವಿದೆ. ಕಳೆದ 2 ದಿನಗಳ ಸಂಭಾವ್ಯ ವೈದ್ಯಕೀಯ ವರದಿ ಲಗತ್ತುಗಳನ್ನು (PDF) ಹೊಂದಿರುವ ಇಮೇಲ್‌ಗಳನ್ನು ಮಾತ್ರ ನಾವು ಹುಡುಕಿ ನಿಮ್ಮ ಫೋನ್‌ನಲ್ಲಿ ಸ್ಥಳೀಯವಾಗಿ ಹೊರತೆಗೆಯುತ್ತೇವೆ. ಯಾವುದೇ ಇಮೇಲ್ ವಿಷಯವನ್ನು ನಮ್ಮ ಸರ್ವರ್‌ಗಳಿಗೆ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ. ನೀವು ಇದಕ್ಕೆ ಒಪ್ಪುತ್ತೀರಾ?",
