        "If a name was mis-read on a scan and one person shows up twice, merge the wrong name into the correct one. Moves all their reports, trends, reminders and history together." to "ಸ್ಕ್ಯಾನ್‌ನಲ್ಲಿ ಹೆಸರನ್ನು ತಪ್ಪಾಗಿ ಓದಿದ್ದರೆ ಮತ್ತು ಒಬ್ಬ ವ್ಯಕ್ತಿ ಎರಡು ಬಾರಿ ಕಾಣಿಸಿಕೊಂಡರೆ, ತಪ್ಪು ಹೆಸರನ್ನು ಸರಿಯಾದ ಹೆಸರಿಗೆ ವಿಲೀನಗೊಳಿಸಿ. ಇದು ಅವರ ಎಲ್ಲಾ ವರದಿಗಳು, ಪ್ರವೃತ್ತಿಗಳು, ರಿಮೈಂಡರ್‌ಗಳು ಮತ್ತು ಇತಿಹಾಸವನ್ನು ಒಟ್ಟಿಗೆ ಸ್ಥಳಾಂತರಿಸುತ್ತದೆ.",
