        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್‌ಗಳನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿದ ನಂತರ, ನಿಮ್ಮ ದೈನಂದಿನ ಔಷಧಿಗಳು ರಿಮೈಂಡರ್‌ಗಳೊಂದಿಗೆ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ.\n\nಪ್ರತಿ ಔಷಧಿಗೆ ರಿಮೈಂಡರ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲು ಕೆಳಗಿನ ಟಾಗಲ್ ಟ್ಯಾಪ್ ಮಾಡಿ.",
