        "Scan Mode: Regional / Indic Script (Sarvam AI)" to "ಸ್ಕ್ಯಾನ್ ಮೋಡ್: ಪ್ರಾದೇಶಿಕ / ಭಾರತೀಯ ಲಿಪಿ (Sarvam AI)",
