        "Scan failed. Check your email settings and try again." to "ಸ್ಕ್ಯಾನ್ ವಿಫಲವಾಗಿದೆ. ನಿಮ್ಮ ಇಮೇಲ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
        "Scan from Email" to "ಇಮೇಲ್‌ನಿಂದ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ",
        "Scan lab reports (blood test, thyroid, etc.) and their trends will appear here." to "ಲ್ಯಾಬ್ ವರದಿಗಳನ್ನು (ರಕ್ತ ಪರೀಕ್ಷೆ, ಥೈರಾಯ್ಡ್, ಇತ್ಯಾದಿ) ಸ್ಕ್ಯಾನ್ ಮಾಡಿ ಮತ್ತು ಅವುಗಳ ಪ್ರವೃತ್ತಿಗಳು ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ.",
        "Scan started — watch the progress above." to "ಸ್ಕ್ಯಾನ್ ಪ್ರಾರಂಭವಾಗಿದೆ — ಮೇಲಿನ ಪ್ರಗತಿಯನ್ನು ನೋಡಿ.",
        "Scan time" to "ಸ್ಕ್ಯಾನ್ ಸಮಯ",
