        "Scheduled Slot:" to "ನಿಗದಿತ ಸ್ಲಾಟ್:",
        "Search doctor or specialty..." to "ವೈದ್ಯರು ಅಥವಾ ವಿಶೇಷತೆಯನ್ನು ಹುಡುಕಿ...",
