        "Searching Unified Health Interface (UHI) registry for real-time open network listings." to "ನೈಜ-ಸಮಯದ ಓಪನ್ ನೆಟ್‌ವರ್ಕ್ ಪಟ್ಟಿಗಳಿಗಾಗಿ ಯುನಿಫೈಡ್ ಹೆಲ್ತ್ ಇಂಟರ್‌ಫೇಸ್ (UHI) ರಿಜಿಸ್ಟ್ರಿಯನ್ನು ಹುಡುಕಲಾಗುತ್ತಿದೆ.",
        "Searching nearby centers..." to "ಹತ್ತಿರದ ಕೇಂದ್ರಗಳನ್ನು ಹುಡುಕಲಾಗುತ್ತಿದೆ...",
        "Secondary: Custom Key" to "ದ್ವಿತೀಯ: ಕಸ್ಟಮ್ ಕೀ",
        "Secure App Password" to "ಸುರಕ್ಷಿತ ಆ್ಯಪ್ ಪಾಸ್‌ವರ್ಡ್",
        "Secure Medical Report Analyzer" to "ಸುರಕ್ಷಿತ ವೈದ್ಯಕೀಯ ವರದಿ ವಿಶ್ಲೇಷಕ",
        "See it in action" to "ಇದನ್ನು ಕ್ರಿಯೆಯಲ್ಲಿ ನೋಡಿ",
        "Select a Slot first" to "ಮೊದಲು ಸ್ಲಾಟ್ ಆಯ್ಕೆಮಾಡಿ",
        "Select reminder slots" to "ರಿಮೈಂಡರ್ ಸ್ಲಾಟ್‌ಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ",
        "Select which days the patient should take this medicine:" to "ರೋಗಿ ಈ ಔಷಧಿಯನ್ನು ಯಾವ ದಿನಗಳಂದು ತೆಗೆದುಕೊಳ್ಳಬೇಕು ಎಂಬುದನ್ನು ಆಯ್ಕೆಮಾಡಿ:",
        "Sends just what changed since last time" to "ಕೊನೆಯ ಬಾರಿಯಿಂದ ಬದಲಾಗಿರುವುದನ್ನು ಮಾತ್ರ ಕಳುಹಿಸುತ್ತದೆ",
        "Server Settings" to "ಸರ್ವರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
        "Server address, language, voice, backups" to "ಸರ್ವರ್ ವಿಳಾಸ, ಭಾಷೆ, ಧ್ವನಿ, ಬ್ಯಾಕಪ್‌ಗಳು",
        "Set" to "ಹೊಂದಿಸಿ",
        "Settings" to "ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
        "Sex" to "ಲಿಂಗ",
        "Share" to "ಹಂಚಿಕೊಳ್ಳಿ",
        "Share brief" to "ಸಾರಾಂಶವನ್ನು ಹಂಚಿಕೊಳ್ಳಿ",
        "Share on WhatsApp" to "WhatsApp ನಲ್ಲಿ ಹಂಚಿಕೊಳ್ಳಿ",
        "Share with Doctor" to "ವೈದ್ಯರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಿ",
        "Side Effects" to "ಅಡ್ಡಪರಿಣಾಮಗಳು",
        "Sign In" to "ಸೈನ್ ಇನ್ ಮಾಡಿ",
        "Sign In with Google" to "Google ಮೂಲಕ ಸೈನ್ ಇನ್ ಮಾಡಿ",
        "Sign in quickly using fingerprint" to "ಬೆರಳಚ್ಚು ಬಳಸಿ ವೇಗವಾಗಿ ಸೈನ್ ಇನ್ ಮಾಡಿ",
        "Signing in gives you your own free daily AI usage allowance, separate from other users of this app." to "ಸೈನ್ ಇನ್ ಮಾಡುವುದರಿಂದ ಈ ಆ್ಯಪ್‌ನ ಇತರ ಬಳಕೆದಾರರಿಂದ ಪ್ರತ್ಯೇಕವಾಗಿ ನಿಮ್ಮ ಸ್ವಂತ ಉಚಿತ ದೈನಂದಿನ AI ಬಳಕೆಯ ಮಿತಿ ಸಿಗುತ್ತದೆ.",
        "Skip & Mark Read" to "ಬಿಟ್ಟುಬಿಡಿ ಮತ್ತು ಓದಿದೆ ಎಂದು ಗುರುತಿಸಿ",
        "Smart Health Lens" to "ಸ್ಮಾರ್ಟ್ ಹೆಲ್ತ್ ಲೆನ್ಸ್",
        "Something went wrong. Check your connection and try again." to "ಏನೋ ತಪ್ಪಾಗಿದೆ. ನಿಮ್ಮ ಸಂಪರ್ಕವನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
        "Speak" to "ಮಾತನಾಡಿ",
        "Special Patient Notes" to "ವಿಶೇಷ ರೋಗಿ ಟಿಪ್ಪಣಿಗಳು",
        "Start Date (YYYY-MM-DD)" to "ಪ್ರಾರಂಭ ದಿನಾಂಕ (YYYY-MM-DD)",
        "Stores the file without using AI — no API calls. You can analyze it anytime from its details." to "AI ಬಳಸದೆ ಫೈಲ್ ಅನ್ನು ಸಂಗ್ರಹಿಸುತ್ತದೆ — API ಕರೆಗಳಿಲ್ಲ. ಅದರ ವಿವರಗಳಿಂದ ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ ವಿಶ್ಲೇಷಿಸಬಹುದು.",
        "Successfully initiated booking request for:" to "ಇದಕ್ಕಾಗಿ ಬುಕಿಂಗ್ ವಿನಂತಿ ಯಶಸ್ವಿಯಾಗಿ ಪ್ರಾರಂಭಿಸಲಾಗಿದೆ:",
        "Switch Profile" to "ಪ್ರೊಫೈಲ್ ಬದಲಿಸಿ",
        "Sync Now" to "ಈಗ ಸಿಂಕ್ ಮಾಡಿ",
        "System" to "ಸಿಸ್ಟಮ್",
        "T" to "T",
        "Tap Settings → allow exact alarms so reminders arrive at the precise time." to "ರಿಮೈಂಡರ್‌ಗಳು ನಿಖರ ಸಮಯಕ್ಕೆ ಬರಲು ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ನಿಖರ ಅಲಾರಂಗಳನ್ನು ಅನುಮತಿಸಿ ಟ್ಯಾಪ್ ಮಾಡಿ.",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ವೈದ್ಯರ ಭೇಟಿ ಅಥವಾ ತಪಾಸಣೆಯನ್ನು ನಿಗದಿಪಡಿಸಲು ಮೇಲಿನ \"ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಸೇರಿಸಿ\" ಟ್ಯಾಪ್ ಮಾಡಿ. ಅದು ಬಾಕಿ ಆಗುವ ಮೊದಲು ನಿಮಗೆ ನೆನಪಿಸಲಾಗುತ್ತದೆ.",
        "Tap a medicine to expand" to "ವಿಸ್ತರಿಸಲು ಔಷಧಿಯನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ",
        "Tap any point to open that report" to "ಆ ವರದಿಯನ್ನು ತೆರೆಯಲು ಯಾವುದೇ ಬಿಂದುವನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ",
        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "ನಿಮ್ಮ ಸಾಧನದಿಂದ ಚಿತ್ರ, PDF ಅಥವಾ ಡಾಕ್ ಆಯ್ಕೆಮಾಡಲು ಇಲ್ಲಿ ಟ್ಯಾಪ್ ಮಾಡಿ, ಅಥವಾ ಫೋಟೋ ತೆಗೆಯಲು ಕೆಳಗಿನ ಕ್ಯಾಮೆರಾ ಬಳಸಿ.",
        "Tap play to hear this summary" to "ಈ ಸಾರಾಂಶವನ್ನು ಕೇಳಲು ಪ್ಲೇ ಟ್ಯಾಪ್ ಮಾಡಿ",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "ನಿಮ್ಮ ಫೋನ್ ಮತ್ತು ಜೋಡಿಸಿದ ವಾಚ್‌ನಲ್ಲಿ ಔಷಧಿ ರಿಮೈಂಡರ್‌ಗಳು ಕಾಣಿಸಲು ಅನುಮತಿಸಲು ಟ್ಯಾಪ್ ಮಾಡಿ.",
        "Tap to pick\nImage or PDF" to "ಆಯ್ಕೆ ಮಾಡಲು ಟ್ಯಾಪ್ ಮಾಡಿ\nಚಿತ್ರ ಅಥವಾ PDF",
        "Tap to select" to "ಆಯ್ಕೆ ಮಾಡಲು ಟ್ಯಾಪ್ ಮಾಡಿ",
        "Tap to view" to "ನೋಡಲು ಟ್ಯಾಪ್ ಮಾಡಿ",
        "Test Parameter Changes" to "ಪರೀಕ್ಷಾ ನಿಯತಾಂಕ ಬದಲಾವಣೆಗಳು",
        "Test group" to "ಪರೀಕ್ಷಾ ಗುಂಪು",
        "Tested Parameters" to "ಪರೀಕ್ಷಿಸಿದ ನಿಯತಾಂಕಗಳು",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್‌ಗಳಲ್ಲಿ ಶಿಫಾರಸು ಮಾಡಿದ ಪರೀಕ್ಷೆಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಟ್ರ್ಯಾಕ್ ಮಾಡಲಾಗುತ್ತದೆ. ನೀವು ಅವುಗಳನ್ನು ಹಸ್ತಚಾಲಿತವಾಗಿಯೂ ಸೇರಿಸಬಹುದು.",
        "That QR code doesn't contain a report link." to "ಆ QR ಕೋಡ್‌ನಲ್ಲಿ ವರದಿ ಲಿಂಕ್ ಇಲ್ಲ.",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "ಸೌಲಭ್ಯವು 10 ನಿಮಿಷಗಳಲ್ಲಿ SMS/WhatsApp ಮೂಲಕ ನಿಮ್ಮ ಸ್ಲಾಟ್ ಅನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ.",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "ಆಯ್ಕೆಮಾಡಿದ ಫೈಲ್‌ಗಳು ತುಂಬಾ ದೊಡ್ಡದಾಗಿವೆ (%.2f MB). ಈ ಫೈಲ್‌ಗಳನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು ಹೆಚ್ಚು ಸಮಯ ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ ಮತ್ತು ಮೆಮೊರಿ ಸಮಸ್ಯೆಗಳು ಉಂಟಾಗಬಹುದು. ಫೈಲ್‌ಗಳನ್ನು 10 MB ಗಿಂತ ಕಡಿಮೆ ಇಡಲು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ. ನೀವು ಇನ್ನೂ ಮುಂದುವರಿಯಲು ಬಯಸುವಿರಾ?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "ಇದು ನಿಜವಲ್ಲ. ಇದನ್ನು ತೆಗೆದುಹಾಕಿ, ಅಥವಾ ನಿಮ್ಮ ಸ್ವಂತ ದಾಖಲೆಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಲು ಪ್ರಾರಂಭಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ.",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "ಇದು ಎಲ್ಲಾ ವರದಿಗಳು, ಔಷಧಿಗಳು, ಬಾಕಿ ಪರೀಕ್ಷೆಗಳು ಮತ್ತು ಚಿತ್ರಗಳನ್ನು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸುತ್ತದೆ. ಇದನ್ನು ರದ್ದುಗೊಳಿಸಲಾಗುವುದಿಲ್ಲ.",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "ಇದು ಮೂಲತಃ ಸ್ಕ್ಯಾನ್ ಮಾಡಿದ ಚಿತ್ರದ ಮೇಲೆ AI ವಿಶ್ಲೇಷಣೆಯನ್ನು ಮತ್ತೆ ಚಲಾಯಿಸಿ ಕೆಳಗಿನ ಹೊರತೆಗೆದ ಪರೀಕ್ಷಾ ಮೌಲ್ಯಗಳು, ಔಷಧಿಗಳು ಮತ್ತು ಒಳನೋಟಗಳನ್ನು ರಿಫ್ರೆಶ್ ಮಾಡುತ್ತದೆ. ಹಿಂದಿನ ಸ್ಕ್ಯಾನ್ ಅಪೂರ್ಣವಾಗಿ ಬಂದಿದ್ದರೆ (ಉದಾ. API ಸ್ವಲ್ಪ ಸಮಯ ಲಭ್ಯವಿರಲಿಲ್ಲ) ಇದು ಉಪಯುಕ್ತವಾಗಿದೆ. ಇದು ನಿಮ್ಮ ಕೆಲವು API ಕೋಟಾವನ್ನು ಬಳಸಬಹುದು.",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "ಈ ವರದಿಯ ಫೈಲ್ ಉಳಿಸಲಾಗಿದೆ ಆದರೆ AI ಮೂಲಕ ವಿಶ್ಲೇಷಿಸಲಾಗಿಲ್ಲ, ಆದ್ದರಿಂದ ಇದಕ್ಕೆ ಇನ್ನೂ ಪರೀಕ್ಷಾ ಮೌಲ್ಯಗಳು, ಪ್ರವೃತ್ತಿಗಳು ಅಥವಾ ಒಳನೋಟಗಳಿಲ್ಲ. ನೀವು ಸಿದ್ಧರಾದಾಗ ಇದನ್ನು ವಿಶ್ಲೇಷಿಸಿ (ಕೆಲವು API ಕೋಟಾವನ್ನು ಬಳಸುತ್ತದೆ).",
        "Time (HH:MM)" to "ಸಮಯ (HH:MM)",
        "Tip: 1-0-1 = morning & night, 1-1-1 = three times a day." to "ಸಲಹೆ: 1-0-1 = ಬೆಳಿಗ್ಗೆ ಮತ್ತು ರಾತ್ರಿ, 1-1-1 = ದಿನಕ್ಕೆ ಮೂರು ಬಾರಿ.",
