        "Which voice reads answers aloud. Sarvam & Gemini speak Indian languages well; Phone uses your device's built-in voices (may not have Marathi)." to "ಯಾವ ಧ್ವನಿ ಉತ್ತರಗಳನ್ನು ಜೋರಾಗಿ ಓದುತ್ತದೆ. Sarvam ಮತ್ತು Gemini ಭಾರತೀಯ ಭಾಷೆಗಳನ್ನು ಚೆನ್ನಾಗಿ ಮಾತನಾಡುತ್ತವೆ; ಫೋನ್ ನಿಮ್ಮ ಸಾಧನದ ಅಂತರ್ನಿರ್ಮಿತ ಧ್ವನಿಗಳನ್ನು ಬಳಸುತ್ತದೆ (ಮರಾಠಿ ಇಲ್ಲದಿರಬಹುದು).",
