        "You haven't linked an email account yet. Please go to Settings (Account tab) to link your Gmail account or IMAP details first." to "ನೀವು ಇನ್ನೂ ಇಮೇಲ್ ಖಾತೆಯನ್ನು ಲಿಂಕ್ ಮಾಡಿಲ್ಲ. ನಿಮ್ಮ Gmail ಖಾತೆ ಅಥವಾ IMAP ವಿವರಗಳನ್ನು ಮೊದಲು ಲಿಂಕ್ ಮಾಡಲು ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ (ಖಾತೆ ಟ್ಯಾಬ್) ಹೋಗಿ.",
