        "Medication Reminders" to "ಔಷಧಿ ರಿಮೈಂಡರ್‌ಗಳು",
        "Find Doctors" to "ವೈದ್ಯರನ್ನು ಹುಡುಕಿ",
        "Find Hospitals" to "ಆಸ್ಪತ್ರೆಗಳನ್ನು ಹುಡುಕಿ",
        "Doctor Brief" to "ವೈದ್ಯರ ಸಾರಾಂಶ",
        "Scan any medical report" to "ಯಾವುದೇ ವೈದ್ಯಕೀಯ ವರದಿಯನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿ",
        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "ಕಾಗದದ ಲ್ಯಾಬ್ ವರದಿಗಳು, ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್‌ಗಳು ಮತ್ತು ಡಿಸ್ಚಾರ್ಜ್ ಸಾರಾಂಶಗಳನ್ನು ಸಂಘಟಿತ, ಹುಡುಕಬಹುದಾದ ಡಿಜಿಟಲ್ ದಾಖಲೆಗಳಾಗಿ ಪರಿವರ್ತಿಸಿ — ನೇರವಾಗಿ ನಿಮ್ಮ ಫೋನ್ ಕ್ಯಾಮೆರಾದಿಂದ.",
        "Understand it instantly" to "ಇದನ್ನು ತಕ್ಷಣ ಅರ್ಥಮಾಡಿಕೊಳ್ಳಿ",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI ಪುಟದಲ್ಲಿನ ಪ್ರತಿ ಪರೀಕ್ಷಾ ಮೌಲ್ಯ, ಔಷಧಿ ಮತ್ತು ದಿನಾಂಕವನ್ನು ಓದುತ್ತದೆ, ಇದರಿಂದ ವೈದ್ಯಕೀಯ ಪರಿಭಾಷೆಯಲ್ಲಿ ಸಿಲುಕದೆ ವರದಿಯ ನಿಜವಾದ ಅರ್ಥವನ್ನು ನೀವು ನೋಡಬಹುದು.",
        "Never miss a dose or a follow-up" to "ಎಂದಿಗೂ ಡೋಸ್ ಅಥವಾ ಫಾಲೋ-ಅಪ್ ತಪ್ಪಿಸಬೇಡಿ",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "ಔಷಧಿ ರಿಮೈಂಡರ್‌ಗಳು ಪ್ರತಿದಿನ ಸರಿಯಾದ ಸಮಯಕ್ಕೆ ಮೊಳಗುತ್ತವೆ — ವಾರಕ್ಕೆ ಎರಡು ಬಾರಿ ತೆಗೆದುಕೊಳ್ಳುವ ಔಷಧಿಗೂ ಸಹ — ಮತ್ತು ವೈದ್ಯರ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್‌ಗಳಿಗೂ ಅವುಗಳದ್ದೇ ರಿಮೈಂಡರ್ ಇರುತ್ತದೆ.",
        "What do my latest test results mean?" to "ನನ್ನ ಇತ್ತೀಚಿನ ಪರೀಕ್ಷಾ ಫಲಿತಾಂಶಗಳ ಅರ್ಥವೇನು?",
        "Explain my current medicines in simple words" to "ನನ್ನ ಪ್ರಸ್ತುತ ಔಷಧಿಗಳನ್ನು ಸರಳ ಪದಗಳಲ್ಲಿ ವಿವರಿಸಿ",
        "Are any of my values abnormal?" to "ನನ್ನ ಯಾವುದೇ ಮೌಲ್ಯಗಳು ಅಸಹಜವಾಗಿವೆಯೇ?",
        "What should I ask my doctor next?" to "ನಾನು ಮುಂದೆ ನನ್ನ ವೈದ್ಯರನ್ನು ಏನು ಕೇಳಬೇಕು?",
        "Rx" to "Rx",
        "Hospitals" to "ಆಸ್ಪತ್ರೆಗಳು",
        "Lab Tests" to "ಲ್ಯಾಬ್ ಪರೀಕ್ಷೆಗಳು",
        "Doctors" to "ವೈದ್ಯರು",
        "Broadcasting search to UHI gateway..." to "UHI ಗೇಟ್‌ವೇಗೆ ಹುಡುಕಾಟ ಪ್ರಸಾರ ಮಾಡಲಾಗುತ್ತಿದೆ...",
        "Gateway ACK received. Listening for provider webhook responses..." to "ಗೇಟ್‌ವೇ ACK ಸ್ವೀಕರಿಸಲಾಗಿದೆ. ಪೂರೈಕೆದಾರ ವೆಬ್‌ಹುಕ್ ಪ್ರತಿಕ್ರಿಯೆಗಳಿಗಾಗಿ ಆಲಿಸಲಾಗುತ್ತಿದೆ...",
        "Listening for provider webhooks... (Incoming responses)" to "ಪೂರೈಕೆದಾರ ವೆಬ್‌ಹುಕ್‌ಗಳಿಗಾಗಿ ಆಲಿಸಲಾಗುತ್ತಿದೆ... (ಬರುತ್ತಿರುವ ಪ್ರತಿಕ್ರಿಯೆಗಳು)",
        "3M" to "3 ತಿಂಗಳು",
        "6M" to "6 ತಿಂಗಳು",
        "1Y" to "1 ವರ್ಷ",
        "2Y" to "2 ವರ್ಷಗಳು",
        "10 km" to "10 ಕಿಮೀ",
        "20 km" to "20 ಕಿಮೀ",
        "50 km" to "50 ಕಿಮೀ",
        "Any" to "ಯಾವುದಾದರೂ",
        "Couldn't load your account. Check your connection and try again." to "ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ. ನಿಮ್ಮ ಸಂಪರ್ಕವನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
        "Please enter a valid API key or tap 'Revert to Shared Pool'." to "ದಯವಿಟ್ಟು ಮಾನ್ಯ API ಕೀ ನಮೂದಿಸಿ ಅಥವಾ 'ಹಂಚಿಕೆಯ ಪೂಲ್‌ಗೆ ಹಿಂತಿರುಗಿ' ಟ್ಯಾಪ್ ಮಾಡಿ.",
        "Personal API Key saved! Switched to Individual Key mode." to "ವೈಯಕ್ತಿಕ API ಕೀ ಉಳಿಸಲಾಗಿದೆ! ವೈಯಕ್ತಿಕ ಕೀ ಮೋಡ್‌ಗೆ ಬದಲಾಯಿಸಲಾಗಿದೆ.",
        "Reverted to Primary Shared Key Pool." to "ಪ್ರಾಥಮಿಕ ಹಂಚಿಕೆಯ ಕೀ ಪೂಲ್‌ಗೆ ಹಿಂತಿರುಗಿಸಲಾಗಿದೆ.",
        "All fields are required." to "ಎಲ್ಲಾ ಕ್ಷೇತ್ರಗಳು ಅಗತ್ಯವಿದೆ.",
        "New password must be at least 6 characters." to "ಹೊಸ ಪಾಸ್‌ವರ್ಡ್ ಕನಿಷ್ಠ 6 ಅಕ್ಷರಗಳಿರಬೇಕು.",
        "Password updated successfully." to "ಪಾಸ್‌ವರ್ಡ್ ಯಶಸ್ವಿಯಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ.",
        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "ಸಹಾಯಕವನ್ನು ತಲುಪಲಾಗಲಿಲ್ಲ. ಸರ್ವರ್ ಚಾಲನೆಯಲ್ಲಿದೆ ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಕಾನ್ಫಿಗರ್ ಆಗಿದೆ ಎಂದು ಪರಿಶೀಲಿಸಿ.",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "ಈ ಸಾಧನದಲ್ಲಿ ಧ್ವನಿ ಇನ್‌ಪುಟ್ ಲಭ್ಯವಿಲ್ಲ. ದಯವಿಟ್ಟು Google ಧ್ವನಿ ಟೈಪಿಂಗ್ ಇನ್‌ಸ್ಟಾಲ್/ಸಕ್ರಿಯಗೊಳಿಸಿ.",
        "Couldn't generate the detailed analysis. Please try again." to "ವಿವರವಾದ ವಿಶ್ಲೇಷಣೆ ರಚಿಸಲಾಗಲಿಲ್ಲ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
        "Search failed. Make sure the backend server is running and database is migrated." to "ಹುಡುಕಾಟ ವಿಫಲವಾಗಿದೆ. ಬ್ಯಾಕೆಂಡ್ ಸರ್ವರ್ ಚಾಲನೆಯಲ್ಲಿದೆ ಮತ್ತು ಡೇಟಾಬೇಸ್ ವಲಸೆಯಾಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "ಔಷಧಿಗಳನ್ನು ಪಡೆಯಲು ವಿಫಲವಾಗಿದೆ. ನಿಮ್ಮ ಸ್ಥಳೀಯ ಸರ್ವರ್ ಚಾಲನೆಯಲ್ಲಿದೆ ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಸರಿಯಾಗಿ ಕಾನ್ಫಿಗರ್ ಆಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
        "Failed to delete the selected medicines." to "ಆಯ್ಕೆಮಾಡಿದ ಔಷಧಿಗಳನ್ನು ಅಳಿಸಲು ವಿಫಲವಾಗಿದೆ.",
        "Failed to update the selected medicines." to "ಆಯ್ಕೆಮಾಡಿದ ಔಷಧಿಗಳನ್ನು ನವೀಕರಿಸಲು ವಿಫಲವಾಗಿದೆ.",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "ಬಾಕಿ ಪರೀಕ್ಷೆಗಳನ್ನು ಪಡೆಯಲು ವಿಫಲವಾಗಿದೆ. ನಿಮ್ಮ ಸ್ಥಳೀಯ ಸರ್ವರ್ ಚಾಲನೆಯಲ್ಲಿದೆ ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಸರಿಯಾಗಿ ಕಾನ್ಫಿಗರ್ ಆಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
        "Failed to delete test reminder." to "ಪರೀಕ್ಷಾ ರಿಮೈಂಡರ್ ಅಳಿಸಲು ವಿಫಲವಾಗಿದೆ.",
        "Patient and Test names are required." to "ರೋಗಿ ಮತ್ತು ಪರೀಕ್ಷೆಯ ಹೆಸರುಗಳು ಅಗತ್ಯವಿದೆ.",
        "Failed to save test reminder." to "ಪರೀಕ್ಷಾ ರಿಮೈಂಡರ್ ಉಳಿಸಲು ವಿಫಲವಾಗಿದೆ.",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "ದಾಖಲೆಗಳನ್ನು ಪಡೆಯಲು ವಿಫಲವಾಗಿದೆ. ನಿಮ್ಮ ಸ್ಥಳೀಯ ಸರ್ವರ್ ಚಾಲನೆಯಲ್ಲಿದೆ ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಸರಿಯಾಗಿ ಕಾನ್ಫಿಗರ್ ಆಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "ರಿಮೈಂಡರ್‌ಗಳನ್ನು ಪಡೆಯಲು ವಿಫಲವಾಗಿದೆ. ನಿಮ್ಮ ಸ್ಥಳೀಯ ಸರ್ವರ್ ಚಾಲನೆಯಲ್ಲಿದೆ ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಸರಿಯಾಗಿ ಕಾನ್ಫಿಗರ್ ಆಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
        "Couldn't save the file." to "ಫೈಲ್ ಉಳಿಸಲಾಗಲಿಲ್ಲ.",
        "No app available to open this file type." to "ಈ ಫೈಲ್ ಪ್ರಕಾರವನ್ನು ತೆರೆಯಲು ಯಾವುದೇ ಆ್ಯಪ್ ಲಭ್ಯವಿಲ್ಲ.",
        "Couldn't share this file." to "ಈ ಫೈಲ್ ಹಂಚಿಕೊಳ್ಳಲಾಗಲಿಲ್ಲ.",
        "Report not found." to "ವರದಿ ಕಂಡುಬಂದಿಲ್ಲ.",
        "Failed to load report details." to "ವರದಿ ವಿವರಗಳನ್ನು ಲೋಡ್ ಮಾಡಲು ವಿಫಲವಾಗಿದೆ.",
        "Failed to save edits. Check network settings." to "ಸಂಪಾದನೆಗಳನ್ನು ಉಳಿಸಲು ವಿಫಲವಾಗಿದೆ. ನೆಟ್‌ವರ್ಕ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.",
        "Failed to delete report." to "ವರದಿ ಅಳಿಸಲು ವಿಫಲವಾಗಿದೆ.",
        "Couldn't reprocess: report or its scanned image is missing." to "ಮರುಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲಾಗಲಿಲ್ಲ: ವರದಿ ಅಥವಾ ಅದರ ಸ್ಕ್ಯಾನ್ ಮಾಡಿದ ಚಿತ್ರ ಕಾಣೆಯಾಗಿದೆ.",
        "Failed to reprocess this report." to "ಈ ವರದಿಯನ್ನು ಮರುಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು ವಿಫಲವಾಗಿದೆ.",
        "Medicine name is required." to "ಔಷಧಿಯ ಹೆಸರು ಅಗತ್ಯವಿದೆ.",
        "Select at least one reminder slot." to "ಕನಿಷ್ಠ ಒಂದು ರಿಮೈಂಡರ್ ಸ್ಲಾಟ್ ಆಯ್ಕೆಮಾಡಿ.",
        "Doctor name is required." to "ವೈದ್ಯರ ಹೆಸರು ಅಗತ್ಯವಿದೆ.",
        "Place is required." to "ಸ್ಥಳ ಅಗತ್ಯವಿದೆ.",
        "Date is required." to "ದಿನಾಂಕ ಅಗತ್ಯವಿದೆ.",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "ಈ ಸಾಧನದ ಸುರಕ್ಷಿತ ಹಾರ್ಡ್‌ವೇರ್ ಸಂಗ್ರಹಣೆ ಲಭ್ಯವಿಲ್ಲ, ಆದ್ದರಿಂದ ನಿಮ್ಮ ಸ್ಥಳೀಯ ದಾಖಲೆಗಳ ಕೀ ಮತ್ತು ಲಿಂಕ್ ಮಾಡಿದ-ಇಮೇಲ್ ರುಜುವಾತುಗಳನ್ನು ಹಾರ್ಡ್‌ವೇರ್-ಬೆಂಬಲಿತ ಎನ್‌ಕ್ರಿಪ್ಶನ್ ಇಲ್ಲದೆ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಡೇಟಾ ಇನ್ನೂ ಅಸುರಕ್ಷಿತವಾಗಿ ಎಲ್ಲಿಯೂ ಕಳುಹಿಸಲ್ಪಡುವುದಿಲ್ಲ, ಆದರೆ ಈ ಸಾಧನವು ಸಾಮಾನ್ಯಕ್ಕಿಂತ ದುರ್ಬಲ ರಕ್ಷಣೆ ನೀಡುತ್ತದೆ.",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "ಸ್ಕ್ಯಾನಿಂಗ್, ರಿಮೈಂಡರ್‌ಗಳು ಮತ್ತು ಉಳಿದೆಲ್ಲವೂ ಈ ಸಾಧನದಲ್ಲಿ ಸೈನ್ ಇನ್ ಮಾಡದೆ ಸಂಪೂರ್ಣವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತವೆ. ಸೈನ್ ಇನ್ ಐಚ್ಛಿಕವಾಗಿದೆ (ಇದು SMS ಕೋಡ್ ಕಳುಹಿಸುತ್ತದೆ, ಆದ್ದರಿಂದ ಇದು ಸ್ವಯಂಚಾಲಿತವಲ್ಲ) — ಸಾಧನಗಳಾದ್ಯಂತ ನಿಮ್ಮೊಂದಿಗೆ ಇರುವ ಪ್ರೊಫೈಲ್ ಅಥವಾ ವೈಯಕ್ತಿಕ API ಕೀ ಬೇಕಿದ್ದರೆ ಇದನ್ನು ಬಳಸಿ.",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "ಪ್ರತಿ ಪ್ರವೃತ್ತಿ ಚಾರ್ಟ್ ವಾಚನಗಳನ್ನು ಪ್ರಮಾಣೀಕರಿಸುವ ಘಟಕ. ಬೇರೆ ಘಟಕದ ವರದಿಗಳು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪರಿವರ್ತಿಸಲ್ಪಡುತ್ತವೆ; ಪ್ರತಿ ವರದಿ ಇನ್ನೂ ಅದರ ಮೂಲ ಮೌಲ್ಯವನ್ನು ತೋರಿಸುತ್ತದೆ.",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "ಏಕೆ: Health Decoder ವೆಚ್ಚಗಳನ್ನು ಕಡಿಮೆ ಇಟ್ಟುಕೊಂಡು ಉಚಿತವಾಗಿ ಉಳಿಯುತ್ತದೆ, ನಿಮ್ಮ ದಾಖಲೆಗಳನ್ನು ಮಾರಾಟ ಮಾಡುವ ಮೂಲಕ ಅಲ್ಲ. ನೀವು ಇಲ್ಲಿ ಸೇರಿದರೆ, ನಿಮ್ಮ ವಯಸ್ಸು ಮತ್ತು ಲಿಂಗ ಮಾತ್ರ — ನಿಮ್ಮ ಹೆಸರು, ವರದಿಗಳು ಅಥವಾ ನಿಖರವಾದ ಸ್ಥಳ ಎಂದಿಗೂ ಅಲ್ಲ — ವೈದ್ಯಕೀಯ ಸಂಶೋಧನಾ ಸಂಸ್ಥೆಗಳೊಂದಿಗೆ ಒಟ್ಟಾರೆಯಾಗಿ ಹಂಚಿಕೊಳ್ಳಲಾಗುತ್ತದೆ, ಜಾಹೀರಾತುಗಳನ್ನು ಚಲಾಯಿಸುವ ಅಥವಾ ಚಂದಾದಾರಿಕೆ ವಿಧಿಸುವ ಬದಲು ಪ್ರತಿ ಕುಟುಂಬಕ್ಕೆ ಆ್ಯಪ್ ಅನ್ನು ಉಚಿತವಾಗಿ ಇಡಲು ಸಹಾಯ ಮಾಡಲು.",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "ಈ ಪ್ರೋಗ್ರಾಂ ಇನ್ನೂ ಪ್ರಾರಂಭವಾಗಿಲ್ಲ — ಇಂದು ಇದನ್ನು ಆನ್ ಮಾಡುವುದು ನಿಮ್ಮ ಆದ್ಯತೆಯನ್ನು ಮಾತ್ರ ಉಳಿಸುತ್ತದೆ. ನಿಜವಾದ ಡೇಟಾ-ಹಂಚಿಕೆ ಪೈಪ್‌ಲೈನ್ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವವರೆಗೆ ಏನೂ ಎಲ್ಲಿಯೂ ಕಳುಹಿಸಲ್ಪಡುವುದಿಲ್ಲ, ಮತ್ತು ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ ಇಲ್ಲಿ ನಿಮ್ಮ ಉತ್ತರವನ್ನು ಬದಲಾಯಿಸಬಹುದು.",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "ಇದು ನಿಮ್ಮ Health Decoder ಖಾತೆ ಮತ್ತು ಈ ಸಾಧನದಲ್ಲಿ ಸಂಗ್ರಹಿಸಿದ ಎಲ್ಲಾ ವೈದ್ಯಕೀಯ ದಾಖಲೆಗಳನ್ನು — ವರದಿಗಳು, ರಿಮೈಂಡರ್‌ಗಳು, ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್‌ಗಳು ಮತ್ತು ಕುಟುಂಬ ಪ್ರೊಫೈಲ್‌ಗಳು — ಶಾಶ್ವತವಾಗಿ ಅಳಿಸುತ್ತದೆ. ಇದನ್ನು ರದ್ದುಗೊಳಿಸಲಾಗುವುದಿಲ್ಲ.",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "ಸೂಚಿಸಲಾಗುತ್ತದೆ, ಜೊತೆಗೆ ಪ್ರಮುಖ ಸಲಹೆಗಳು. ಮೊದಲ ಹುಡುಕಾಟ ಇಂಟರ್ನೆಟ್ ಬಳಸುತ್ತದೆ, ನಂತರ ಅದನ್ನು ಉಳಿಸಲಾಗುತ್ತದೆ ಇದರಿಂದ ಮುಂದಿನ ಬಾರಿ ತಕ್ಷಣ ತೆರೆಯುತ್ತದೆ.",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "ಉದಾಹರಣೆ ವರದಿಗಳು, ರಿಮೈಂಡರ್‌ಗಳು ಮತ್ತು ಈಗಾಗಲೇ ಭರ್ತಿ ಮಾಡಿದ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್‌ನೊಂದಿಗೆ, ಇದರಿಂದ ನೀವು ನಿಜವಾದುದನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡುವ ಮೊದಲು ಪ್ರತಿ ಪರದೆಯನ್ನು ಅನ್ವೇಷಿಸಬಹುದು. ಖಾತೆಯಿಂದ ಇದನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ತೆಗೆದುಹಾಕಿ.",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ಆ QR ಒಂದು ವೆಬ್ ಪುಟವನ್ನು ತೆರೆಯಿತು, ನೇರ ಫೈಲ್ ಅಲ್ಲ. ಇದನ್ನು ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ತೆರೆಯಲಾಗುತ್ತಿದೆ — ಅಲ್ಲಿ ವರದಿಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ನಂತರ ಅದನ್ನು ಆಮದು ಮಾಡಲು \"ಸಾಧನದಿಂದ\" ಬಳಸಿ.",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "ದೊಡ್ಡ ದಾಖಲೆಗಳನ್ನು ವಿಶ್ಲೇಷಣೆಗಾಗಿ ವಿಭಜಿಸುವ ವಿಧಾನದಲ್ಲಿ ಸರಿಪಡಿಸುವ ಮೊದಲು %1\$d ಬಹು-ಪುಟ ಸ್ಕ್ಯಾನ್‌ಗಳು ಪ್ರಕ್ರಿಯೆಗೊಂಡಿದ್ದವು — ಅದೇ ದಾಖಲೆಯ ಒಂದು ಪ್ಯಾನೆಲ್ (ಉದಾ. ಎಲೆಕ್ಟ್ರೋಲೈಟ್ಸ್ ಅಥವಾ PT/INR ಪುಟ) ಕಾಣೆಯಾಗಿರಬಹುದು. ಇದು ಈಗಾಗಲೇ ಉಳಿಸಿದ ಪುಟಗಳನ್ನು ಬಳಸಿ ಮತ್ತೆ ಪರಿಶೀಲಿಸಿ, ಬಿಟ್ಟುಹೋದದ್ದನ್ನು ಸೇರಿಸುತ್ತದೆ; ಈಗಾಗಲೇ ಉಳಿಸಿದ್ದು ಹಾಗೆಯೇ ಉಳಿಯುತ್ತದೆ.",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "AI ವಿಶ್ಲೇಷಣಾ ಸರ್ವರ್ ಲಭ್ಯವಿಲ್ಲದ ಸಮಯದಲ್ಲಿ %1\$d ವರದಿ(ಗಳು) ಉಳಿಸಲ್ಪಟ್ಟಿವೆ (ಉದಾ. ದೈನಂದಿನ ಕೋಟಾ ಮುಗಿದಿದೆ), ಆದ್ದರಿಂದ ಅವುಗಳ ದಿನಾಂಕ ಮತ್ತು ವರ್ಗ ದಾಖಲೆಯಿಂದ ಓದಿದ್ದಲ್ಲ, ಊಹೆಗಳು. ಮರು-ವಿಶ್ಲೇಷಣೆ ಈಗಾಗಲೇ ಸಂಗ್ರಹಿಸಿದ ಚಿತ್ರಗಳನ್ನು ಬಳಸುತ್ತದೆ — ನೀವು ಅವನ್ನು ಮತ್ತೆ ಸ್ಕ್ಯಾನ್ ಮಾಡಬೇಕಿಲ್ಲ.",
        "Add, edit, or remove people this device tracks — including yourself" to "ಈ ಸಾಧನ ಟ್ರ್ಯಾಕ್ ಮಾಡುವ ವ್ಯಕ್ತಿಗಳನ್ನು ಸೇರಿಸಿ, ಸಂಪಾದಿಸಿ ಅಥವಾ ತೆಗೆದುಹಾಕಿ — ನಿಮ್ಮನ್ನೂ ಸೇರಿಸಿ",
        "Also protect automatic backups with a password" to "ಸ್ವಯಂಚಾಲಿತ ಬ್ಯಾಕಪ್‌ಗಳನ್ನೂ ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ರಕ್ಷಿಸಿ",
        "Auto-backup password" to "ಸ್ವಯಂ-ಬ್ಯಾಕಪ್ ಪಾಸ್‌ವರ್ಡ್",
        "Backup password" to "ಬ್ಯಾಕಪ್ ಪಾಸ್‌ವರ್ಡ್",
        "Based on your %1\$s result (%2\$s) from your report dated %3\$s." to "%3\$s ದಿನಾಂಕದ ನಿಮ್ಮ ವರದಿಯ %1\$s ಫಲಿತಾಂಶದ (%2\$s) ಆಧಾರದ ಮೇಲೆ.",
        "Blood" to "ರಕ್ತ",
        "Brief" to "ಸಾರಾಂಶ",
        "Chat" to "ಚಾಟ್",
        "Check Now (%1\$d)" to "ಈಗ ಪರಿಶೀಲಿಸಿ (%1\$d)",
        "Check for Missing Report Data" to "ಕಾಣೆಯಾದ ವರದಿ ಡೇಟಾವನ್ನು ಪರಿಶೀಲಿಸಿ",
        "Checking %1\$d of %2\$d…" to "%2\$d ರಲ್ಲಿ %1\$d ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
        "Compare" to "ಹೋಲಿಕೆ",
        "Confirm password" to "ಪಾಸ್‌ವರ್ಡ್ ದೃಢೀಕರಿಸಿ",
        "Data Management" to "ಡೇಟಾ ನಿರ್ವಹಣೆ",
        "Date of Birth (YYYY-MM-DD)" to "ಜನ್ಮ ದಿನಾಂಕ (YYYY-MM-DD)",
        "Discharge Summary" to "ಡಿಸ್ಚಾರ್ಜ್ ಸಾರಾಂಶ",
        "Discharge Summary + Prescription" to "ಡಿಸ್ಚಾರ್ಜ್ ಸಾರಾಂಶ + ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್",
        "Echo" to "ಎಕೋ",
        "Edit Profile" to "ಪ್ರೊಫೈಲ್ ಸಂಪಾದಿಸಿ",
        "Edit profile" to "ಪ್ರೊಫೈಲ್ ಸಂಪಾದಿಸಿ",
        "Ends" to "ಅಂತ್ಯ",
        "Enter Backup Password" to "ಬ್ಯಾಕಪ್ ಪಾಸ್‌ವರ್ಡ್ ನಮೂದಿಸಿ",
        "Every" to "ಪ್ರತಿ",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restoring REPLACES everything currently on this device." to "ನಿಮ್ಮ ಎಲ್ಲ ದಾಖಲೆಗಳನ್ನು (ವರದಿಗಳು + ಚಿತ್ರಗಳು) ಒಂದೇ ಬ್ಯಾಕಪ್ ಫೈಲ್‌ ಆಗಿ ರಫ್ತು ಮಾಡಿ. ಕ್ಲೌಡ್ ಪ್ರತಿ ಇಟ್ಟುಕೊಳ್ಳಲು ಪಿಕರ್‌ನಲ್ಲಿ ನಿಮ್ಮ Google Drive ಅಥವಾ OneDrive ಫೋಲ್ಡರ್ ಆರಿಸಿ. ಮರುಸ್ಥಾಪಿಸಿದರೆ ಈ ಸಾಧನದಲ್ಲಿರುವ ಎಲ್ಲವೂ ಬದಲಾಗುತ್ತದೆ.",
        "Family Members" to "ಕುಟುಂಬ ಸದಸ್ಯರು",
        "First Name" to "ಮೊದಲ ಹೆಸರು",
        "Free Gemini API Key (Optional)" to "ಉಚಿತ Gemini API ಕೀ (ಐಚ್ಛಿಕ)",
        "Full Backup & Restore" to "ಪೂರ್ಣ ಬ್ಯಾಕಪ್ ಮತ್ತು ಮರುಸ್ಥಾಪನೆ",
        "General lifestyle suggestion, not medical advice — talk to your doctor before making changes based on a lab result." to "ಸಾಮಾನ್ಯ ಜೀವನಶೈಲಿ ಸಲಹೆ, ವೈದ್ಯಕೀಯ ಸಲಹೆ ಅಲ್ಲ — ಲ್ಯಾಬ್ ಫಲಿತಾಂಶದ ಆಧಾರದ ಮೇಲೆ ಬದಲಾವಣೆ ಮಾಡುವ ಮೊದಲು ನಿಮ್ಮ ವೈದ್ಯರೊಂದಿಗೆ ಮಾತನಾಡಿ.",
        "Get Free API Key" to "ಉಚಿತ API ಕೀ ಪಡೆಯಿರಿ",
        "Got it" to "ಅರ್ಥವಾಯಿತು",
        "HEALTH TIP" to "ಆರೋಗ್ಯ ಸಲಹೆ",
        "Health Decoder" to "ಹೆಲ್ತ್ ಡಿಕೋಡರ್",
        "Hello," to "ನಮಸ್ಕಾರ,",
        "High" to "ಹೆಚ್ಚು",
        "Home" to "ಮುಖಪುಟ",
        "Last Name" to "ಕೊನೆಯ ಹೆಸರು",
        "Learn More" to "ಇನ್ನಷ್ಟು ತಿಳಿಯಿರಿ",
        "Leave blank to keep the current one" to "ಈಗಿನದನ್ನೇ ಉಳಿಸಿಕೊಳ್ಳಲು ಖಾಲಿ ಬಿಡಿ",
        "Live camera scan — point and get instant answers" to "ಲೈವ್ ಕ್ಯಾಮೆರಾ ಸ್ಕ್ಯಾನ್ — ಕ್ಯಾಮೆರಾ ತೋರಿಸಿ ತಕ್ಷಣ ಉತ್ತರ ಪಡೆಯಿರಿ",
        "Low" to "ಕಡಿಮೆ",
        "Medical Report" to "ವೈದ್ಯಕೀಯ ವರದಿ",
        "Not set" to "ಸೆಟ್ ಆಗಿಲ್ಲ",
        "Not signed in" to "ಸೈನ್ ಇನ್ ಆಗಿಲ್ಲ",
        "Off by default — these sync to your cloud folder above without a password unless you set one here" to "ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಆಫ್ — ನೀವು ಇಲ್ಲಿ ಒಂದನ್ನು ಹೊಂದಿಸುವವರೆಗೆ ಇವು ಮೇಲಿನ ನಿಮ್ಮ ಕ್ಲೌಡ್ ಫೋಲ್ಡರ್‌ಗೆ ಪಾಸ್‌ವರ್ಡ್ ಇಲ್ಲದೆ ಸಿಂಕ್ ಆಗುತ್ತವೆ",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್‌ಗಳು ಸ್ಕ್ಯಾನ್ ಆದ ನಂತರ, ನಿಮ್ಮ ದೈನಂದಿನ ಔಷಧಿಗಳು ಜ್ಞಾಪನೆಗಳೊಂದಿಗೆ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ.\n\nಪ್ರತಿ ಔಷಧಿಗೆ ಜ್ಞಾಪನೆ ಸಕ್ರಿಯಗೊಳಿಸಲು ಕೆಳಗಿನ ಟಾಗಲ್ ಒತ್ತಿ.",
        "Optional — keeps your data available across devices" to "ಐಚ್ಛಿಕ — ನಿಮ್ಮ ಡೇಟಾವನ್ನು ಎಲ್ಲ ಸಾಧನಗಳಲ್ಲಿ ಲಭ್ಯವಿರಿಸುತ್ತದೆ",
        "Optional — leave blank to use the shared pool" to "ಐಚ್ಛಿಕ — ಹಂಚಿದ ಪೂಲ್ ಬಳಸಲು ಖಾಲಿ ಬಿಡಿ",
        "PERSONALIZED FOR YOU" to "ನಿಮಗಾಗಿ ವಿಶೇಷ",
        "Passwords don't match" to "ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ",
        "Profile" to "ಪ್ರೊಫೈಲ್",
        "Protect this backup with a password" to "ಈ ಬ್ಯಾಕಪ್ ಅನ್ನು ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ರಕ್ಷಿಸಿ",
        "Re-analyze All (%1\$d)" to "ಎಲ್ಲವನ್ನೂ ಮರು-ವಿಶ್ಲೇಷಿಸಿ (%1\$d)",
        "Re-analyzing %1\$d of %2\$d…" to "%2\$d ರಲ್ಲಿ %1\$d ಮರು-ವಿಶ್ಲೇಷಣೆಯಾಗುತ್ತಿದೆ…",
        "Reports Needing Re-check" to "ಮರು-ಪರಿಶೀಲನೆ ಬೇಕಾದ ವರದಿಗಳು",
        "Restoring…" to "ಮರುಸ್ಥಾಪಿಸಲಾಗುತ್ತಿದೆ…",
        "Select gender" to "ಲಿಂಗ ಆಯ್ಕೆಮಾಡಿ",
        "Share / Merge Records" to "ದಾಖಲೆಗಳನ್ನು ಹಂಚಿ / ವಿಲೀನಗೊಳಿಸಿ",
        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "ಹಂಚಿಕೆ / ವಿಲೀನ ಆಯ್ಕೆ ಮಾಡಿದ್ದನ್ನು ಇನ್ನೊಂದು ಫೋನ್‌ಗೆ ಅಥವಾ ವೈದ್ಯರಿಗೆ ಕಳುಹಿಸಿ ಅಲ್ಲಿ ಇರುವುದಕ್ಕೆ ಸೇರಿಸುತ್ತದೆ. ಬ್ಯಾಕಪ್ ಮತ್ತು ಮರುಸ್ಥಾಪನೆ ಈ ಸಾಧನದ ಸಂಪೂರ್ಣ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ — ಮರುಸ್ಥಾಪಿಸಿದಾಗ ಎಲ್ಲವನ್ನೂ ಬದಲಾಯಿಸುತ್ತದೆ, ಆದ್ದರಿಂದ ಅದನ್ನು ಹಂಚಿಕೆಗಲ್ಲ, ವಿಪತ್ತು ಚೇತರಿಕೆಗೆ ಬಳಸಿ.",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "ನಿಮ್ಮ ಹೆಸರು ಮತ್ತು ವಿವರಗಳನ್ನು ಸಂಪಾದಿಸಲು, ವೈಯಕ್ತಿಕ API ಕೀ ಬಳಸಲು ಮತ್ತು ಬೆರಳಚ್ಚು ಲಾಗಿನ್ ಸಕ್ರಿಯಗೊಳಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ. ಅದಿಲ್ಲದೆಯೂ ಆ್ಯಪ್ ಸಂಪೂರ್ಣವಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ — ನಿಮ್ಮ ಕುಟುಂಬ ಸದಸ್ಯರು ಮತ್ತು ದಾಖಲೆಗಳು ಈಗಾಗಲೇ ಈ ಸಾಧನದಲ್ಲೇ ಇವೆ.",
        "Sign in to sync your records" to "ನಿಮ್ಮ ದಾಖಲೆಗಳನ್ನು ಸಿಂಕ್ ಮಾಡಲು ಸೈನ್ ಇನ್ ಮಾಡಿ",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "ಇದನ್ನು ಬಿಟ್ಟರೆ ಆ್ಯಪ್ ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಹಂಚಿದ ಉಚಿತ ಪೂಲ್ ಬಳಸುತ್ತದೆ. ನಿಮ್ಮದೇ ಕೀಯನ್ನು ಮೊದಲೇ ಸೇರಿಸಿದರೆ ಆ ಪೂಲ್‌ನ ದೈನಂದಿನ ಮಿತಿ ನಿಮ್ಮನ್ನು ಎಂದಿಗೂ ತಡೆಯುವುದಿಲ್ಲ.",
        "Sono" to "ಸೋನೋ",
        "Starts" to "ಆರಂಭ",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ವೈದ್ಯರ ಭೇಟಿ ಅಥವಾ ತಪಾಸಣೆ ನಿಗದಿಪಡಿಸಲು ಮೇಲಿನ \"ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಸೇರಿಸಿ\" ಒತ್ತಿ. ಸಮಯಕ್ಕೂ ಮೊದಲೇ ನಿಮಗೆ ನೆನಪಿಸಲಾಗುತ್ತದೆ.",
        "Tap to pick\nImage or PDF" to "ಆಯ್ಕೆಮಾಡಲು ಒತ್ತಿ\nಚಿತ್ರ ಅಥವಾ PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ಆ QR ಒಂದು ವೆಬ್ ಪುಟವನ್ನು ತೆರೆಯಿತು, ನೇರ ಫೈಲ್ ಅಲ್ಲ. ಅದನ್ನು ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ತೆರೆಯಲಾಗುತ್ತಿದೆ — ಅಲ್ಲಿ ವರದಿಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ನಂತರ ಅದನ್ನು ಆಮದು ಮಾಡಲು \"ಸಾಧನದಿಂದ\" ಬಳಸಿ.",
        "There's no way to reset this if you forget it — write it down somewhere safe." to "ಮರೆತರೆ ಇದನ್ನು ಮರುಹೊಂದಿಸಲು ಯಾವ ಮಾರ್ಗವೂ ಇಲ್ಲ — ಇದನ್ನು ಎಲ್ಲಾದರೂ ಸುರಕ್ಷಿತವಾಗಿ ಬರೆದಿಟ್ಟುಕೊಳ್ಳಿ.",
        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "ಮರೆತರೆ ಇದನ್ನು ಮರುಹೊಂದಿಸಲು ಯಾವ ಮಾರ್ಗವೂ ಇಲ್ಲ — ಇದನ್ನು ಎಲ್ಲಾದರೂ ಸುರಕ್ಷಿತವಾಗಿ ಬರೆದಿಟ್ಟುಕೊಳ್ಳಿ. ಬ್ಯಾಕಪ್ ಪಾಸ್‌ವರ್ಡ್ ಕಳೆದುಕೊಂಡರೆ ಆ ಬ್ಯಾಕಪ್ ಅನ್ನು ಎಂದಿಗೂ ಮರುಸ್ಥಾಪಿಸಲಾಗದು.",
        "This backup is password-protected. Enter the password it was created with." to "ಈ ಬ್ಯಾಕಪ್ ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ರಕ್ಷಿತವಾಗಿದೆ. ಅದನ್ನು ರಚಿಸಿದ ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನೇ ನಮೂದಿಸಿ.",
        "Try Smart Health Lens" to "ಸ್ಮಾರ್ಟ್ ಹೆಲ್ತ್ ಲೆನ್ಸ್ ಪ್ರಯತ್ನಿಸಿ",
        "Welcome" to "ಸ್ವಾಗತ",
        "Without one, anyone who gets the backup file can open it" to "ಅದಿಲ್ಲದಿದ್ದರೆ, ಬ್ಯಾಕಪ್ ಫೈಲ್ ಸಿಕ್ಕ ಯಾರಾದರೂ ಅದನ್ನು ತೆರೆಯಬಹುದು",
        "Your Profile" to "ನಿಮ್ಮ ಪ್ರೊಫೈಲ್",
        "➕ Add family member" to "➕ ಕುಟುಂಬ ಸದಸ್ಯರನ್ನು ಸೇರಿಸಿ"
    )

