        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "আপনার ডিভাইস থেকে ছবি, PDF বা ডক নির্বাচন করতে এখানে ট্যাপ করুন, অথবা ছবি তুলতে নিচের ক্যামেরা ব্যবহার করুন।",
        "Tap play to hear this summary" to "এই সংক্ষিপ্তসার শুনতে প্লে ট্যাপ করুন",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "ওষুধ রিমাইন্ডার আপনার ফোন ও যুক্ত ওয়াচে দেখাতে অনুমতি দিতে ট্যাপ করুন।",
        "Tap to pick\nImage or PDF" to "নির্বাচন করতে ট্যাপ করুন\nছবি বা PDF",
        "Tap to select" to "নির্বাচন করতে ট্যাপ করুন",
        "Tap to view" to "দেখতে ট্যাপ করুন",
        "Test Parameter Changes" to "পরীক্ষার প্যারামিটার পরিবর্তন",
        "Test group" to "পরীক্ষার গ্রুপ",
        "Tested Parameters" to "পরীক্ষিত প্যারামিটার",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "প্রেসক্রিপশনে প্রস্তাবিত পরীক্ষা স্বয়ংক্রিয়ভাবে ট্র্যাক করা হয়। আপনি সেগুলো ম্যানুয়ালিও যোগ করতে পারেন।",
        "That QR code doesn't contain a report link." to "সেই QR কোডে কোনো রিপোর্ট লিঙ্ক নেই।",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "সুবিধাটি ১০ মিনিটের মধ্যে SMS/WhatsApp-এর মাধ্যমে আপনার স্লট নিশ্চিত করবে।",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "নির্বাচিত ফাইলগুলি খুব বড় (%.2f MB)। এই ফাইলগুলি প্রক্রিয়া করতে বেশি সময় লাগবে এবং মেমোরি সমস্যা হতে পারে। আমরা ফাইলগুলি ১০ MB এর নিচে রাখার পরামর্শ দিই। আপনি কি তবুও এগিয়ে যেতে চান?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "এটি বাস্তব নয়। এটি সরান, অথবা নিজের রেকর্ড ট্র্যাক করা শুরু করতে সাইন ইন করুন।",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "এটি সমস্ত রিপোর্ট, ওষুধ, মুলতুবি পরীক্ষা ও ছবি স্থায়ীভাবে মুছে দেয়। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "এটি মূল স্ক্যান করা ছবিতে AI বিশ্লেষণ আবার চালায় এবং নিচের নিষ্কাশিত পরীক্ষার মান, ওষুধ ও অন্তর্দৃষ্টি রিফ্রেশ করে। আগের স্ক্যান অসম্পূর্ণ এসে থাকলে (যেমন API সংক্ষিপ্তভাবে অনুপলব্ধ ছিল) এটি কার্যকর। এটি আপনার কিছু API কোটা ব্যবহার করতে পারে।",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "এই রিপোর্টের ফাইল সংরক্ষিত কিন্তু AI দ্বারা বিশ্লেষণ করা হয়নি, তাই এতে এখনো কোনো পরীক্ষার মান, প্রবণতা বা অন্তর্দৃষ্টি নেই। আপনি প্রস্তুত হলে এটি বিশ্লেষণ করুন (কিছু API কোটা ব্যবহার করে)।",
        "Time (HH:MM)" to "সময় (HH:MM)",
