        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "কাগজের ল্যাব রিপোর্ট, প্রেসক্রিপশন ও ডিসচার্জ সারাংশকে সুসংগঠিত, অনুসন্ধানযোগ্য ডিজিটাল রেকর্ডে পরিণত করুন — সরাসরি আপনার ফোনের ক্যামেরা থেকে।",
        "Understand it instantly" to "এটি তাৎক্ষণিকভাবে বুঝুন",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI পাতার প্রতিটি পরীক্ষার মান, ওষুধ ও তারিখ পড়ে, যাতে আপনি চিকিৎসা পরিভাষায় না আটকে রিপোর্টের প্রকৃত অর্থ দেখতে পারেন।",
        "Never miss a dose or a follow-up" to "কখনো ডোজ বা ফলো-আপ মিস করবেন না",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "ওষুধ রিমাইন্ডার প্রতিদিন সঠিক সময়ে বাজে — সপ্তাহে দুইবারের ওষুধের জন্যও — এবং ডাক্তার অ্যাপয়েন্টমেন্টেরও নিজস্ব রিমাইন্ডার থাকে।",
        "What do my latest test results mean?" to "আমার সর্বশেষ পরীক্ষার ফলাফলের অর্থ কী?",
        "Explain my current medicines in simple words" to "আমার বর্তমান ওষুধগুলো সহজ ভাষায় ব্যাখ্যা করুন",
        "Are any of my values abnormal?" to "আমার কোনো মান কি অস্বাভাবিক?",
        "What should I ask my doctor next?" to "আমার ডাক্তারকে পরবর্তীতে কী জিজ্ঞাসা করা উচিত?",
        "Rx" to "Rx",
        "Hospitals" to "হাসপাতাল",
        "Lab Tests" to "ল্যাব পরীক্ষা",
        "Doctors" to "ডাক্তারগণ",
        "Broadcasting search to UHI gateway..." to "UHI গেটওয়েতে অনুসন্ধান সম্প্রচার করা হচ্ছে...",
        "Gateway ACK received. Listening for provider webhook responses..." to "গেটওয়ে ACK পাওয়া গেছে। প্রদানকারী ওয়েবহুক প্রতিক্রিয়ার জন্য শোনা হচ্ছে...",
        "Listening for provider webhooks... (Incoming responses)" to "প্রদানকারী ওয়েবহুকের জন্য শোনা হচ্ছে... (আগত প্রতিক্রিয়া)",
        "3M" to "৩ মাস",
        "6M" to "৬ মাস",
        "1Y" to "১ বছর",
        "2Y" to "২ বছর",
        "10 km" to "১০ কিমি",
        "20 km" to "২০ কিমি",
        "50 km" to "৫০ কিমি",
        "Any" to "যেকোনো",
        "Couldn't load your account. Check your connection and try again." to "আপনার অ্যাকাউন্ট লোড করা যায়নি। আপনার সংযোগ পরীক্ষা করে আবার চেষ্টা করুন।",
        "Please enter a valid API key or tap 'Revert to Shared Pool'." to "অনুগ্রহ করে একটি বৈধ API কী লিখুন অথবা 'শেয়ার্ড পুলে ফিরুন'-এ ট্যাপ করুন।",
        "Personal API Key saved! Switched to Individual Key mode." to "ব্যক্তিগত API কী সংরক্ষিত হয়েছে! ব্যক্তিগত কী মোডে পরিবর্তিত হয়েছে।",
        "Reverted to Primary Shared Key Pool." to "প্রাইমারি শেয়ার্ড কী পুলে ফিরে যাওয়া হয়েছে।",
        "All fields are required." to "সমস্ত ক্ষেত্র প্রয়োজনীয়।",
        "New password must be at least 6 characters." to "নতুন পাসওয়ার্ড অবশ্যই কমপক্ষে ৬ অক্ষরের হতে হবে।",
        "Password updated successfully." to "পাসওয়ার্ড সফলভাবে আপডেট হয়েছে।",
        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "সহায়কের কাছে পৌঁছানো যায়নি। সার্ভার চলছে এবং সেটিংসে কনফিগার করা আছে তা পরীক্ষা করুন।",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "এই ডিভাইসে ভয়েস ইনপুট উপলব্ধ নেই। অনুগ্রহ করে Google ভয়েস টাইপিং ইনস্টল/সক্ষম করুন।",
        "Couldn't generate the detailed analysis. Please try again." to "বিস্তারিত বিশ্লেষণ তৈরি করা যায়নি। অনুগ্রহ করে আবার চেষ্টা করুন।",
        "Search failed. Make sure the backend server is running and database is migrated." to "অনুসন্ধান ব্যর্থ হয়েছে। ব্যাকএন্ড সার্ভার চলছে এবং ডেটাবেস মাইগ্রেট করা হয়েছে তা নিশ্চিত করুন।",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "ওষুধ আনতে ব্যর্থ। আপনার লোকাল সার্ভার চলছে এবং সেটিংসে সঠিকভাবে কনফিগার করা আছে তা নিশ্চিত করুন।",
        "Failed to delete the selected medicines." to "নির্বাচিত ওষুধ মুছতে ব্যর্থ।",
        "Failed to update the selected medicines." to "নির্বাচিত ওষুধ আপডেট করতে ব্যর্থ।",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "মুলতুবি পরীক্ষা আনতে ব্যর্থ। আপনার লোকাল সার্ভার চলছে এবং সেটিংসে সঠিকভাবে কনফিগার করা আছে তা নিশ্চিত করুন।",
        "Failed to delete test reminder." to "পরীক্ষার রিমাইন্ডার মুছতে ব্যর্থ।",
        "Patient and Test names are required." to "রোগী ও পরীক্ষার নাম প্রয়োজন।",
        "Failed to save test reminder." to "পরীক্ষার রিমাইন্ডার সংরক্ষণ করতে ব্যর্থ।",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "রেকর্ড আনতে ব্যর্থ। আপনার লোকাল সার্ভার চলছে এবং সেটিংসে সঠিকভাবে কনফিগার করা আছে তা নিশ্চিত করুন।",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "রিমাইন্ডার আনতে ব্যর্থ। আপনার লোকাল সার্ভার চলছে এবং সেটিংসে সঠিকভাবে কনফিগার করা আছে তা নিশ্চিত করুন।",
        "Couldn't save the file." to "ফাইল সংরক্ষণ করা যায়নি।",
        "No app available to open this file type." to "এই ফাইলের ধরন খুলতে কোনো অ্যাপ উপলব্ধ নেই।",
        "Couldn't share this file." to "এই ফাইল শেয়ার করা যায়নি।",
        "Report not found." to "রিপোর্ট পাওয়া যায়নি।",
        "Failed to load report details." to "রিপোর্টের বিবরণ লোড করতে ব্যর্থ।",
        "Failed to save edits. Check network settings." to "সম্পাদনা সংরক্ষণ করতে ব্যর্থ। নেটওয়ার্ক সেটিংস পরীক্ষা করুন।",
        "Failed to delete report." to "রিপোর্ট মুছতে ব্যর্থ।",
        "Couldn't reprocess: report or its scanned image is missing." to "পুনরায় প্রক্রিয়া করা যায়নি: রিপোর্ট বা এর স্ক্যান করা ছবি অনুপস্থিত।",
        "Failed to reprocess this report." to "এই রিপোর্ট পুনরায় প্রক্রিয়া করতে ব্যর্থ।",
        "Medicine name is required." to "ওষুধের নাম প্রয়োজন।",
        "Select at least one reminder slot." to "কমপক্ষে একটি রিমাইন্ডার স্লট নির্বাচন করুন।",
        "Doctor name is required." to "ডাক্তারের নাম প্রয়োজন।",
        "Place is required." to "স্থান প্রয়োজন।",
        "Date is required." to "তারিখ প্রয়োজন।",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "এই ডিভাইসের নিরাপদ হার্ডওয়্যার স্টোরেজ উপলব্ধ নেই, তাই আপনার লোকাল রেকর্ডস কী ও লিঙ্কড-ইমেইল ক্রেডেনশিয়াল হার্ডওয়্যার-ব্যাকড এনক্রিপশন ছাড়া সংরক্ষিত। আপনার ডেটা তবুও অনিরাপদভাবে কোথাও পাঠানো হয় না, তবে এই ডিভাইস স্বাভাবিকের চেয়ে দুর্বল সুরক্ষা দেয়।",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "স্ক্যানিং, রিমাইন্ডার এবং বাকি সবকিছু এই ডিভাইসে সাইন ইন ছাড়াই সম্পূর্ণভাবে কাজ করে। সাইন ইন ঐচ্ছিক (এটি SMS কোড পাঠায়, তাই এটি স্বয়ংক্রিয় নয়) — ডিভাইস জুড়ে আপনার সাথে থাকা প্রোফাইল বা ব্যক্তিগত API কী চাইলে এটি ব্যবহার করুন।",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "প্রতিটি প্রবণতা চার্ট যে ইউনিটে রিডিং মানসম্মত করে। ভিন্ন ইউনিটের রিপোর্ট স্বয়ংক্রিয়ভাবে রূপান্তরিত হয়; প্রতিটি রিপোর্ট এখনও তার মূল মান দেখায়।",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "কেন: Health Decoder খরচ কম রেখে বিনামূল্যে থাকে, আপনার রেকর্ড বিক্রি করে নয়। আপনি এখানে অংশগ্রহণ করলে, শুধুমাত্র আপনার বয়স ও লিঙ্গ — কখনো আপনার নাম, রিপোর্ট বা সঠিক অবস্থান নয় — চিকিৎসা গবেষণা প্রতিষ্ঠানগুলির সাথে সামষ্টিকভাবে শেয়ার করা হবে, যাতে বিজ্ঞাপন চালানো বা সাবস্ক্রিপশন নেওয়ার পরিবর্তে অ্যাপটি প্রতিটি পরিবারের জন্য বিনামূল্যে রাখতে সহায়তা হয়।",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "এই প্রোগ্রাম এখনো চালু হয়নি — আজ এটি চালু করলে শুধু আপনার পছন্দ সংরক্ষিত হয়। প্রকৃত ডেটা-শেয়ারিং পাইপলাইন তৈরি না হওয়া পর্যন্ত কিছুই কোথাও পাঠানো হয় না, এবং আপনি যেকোনো সময় এখানে আপনার উত্তর পরিবর্তন করতে পারেন।",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "এটি আপনার Health Decoder অ্যাকাউন্ট এবং এই ডিভাইসে সংরক্ষিত সমস্ত মেডিকেল রেকর্ড — রিপোর্ট, রিমাইন্ডার, অ্যাপয়েন্টমেন্ট ও পরিবারের প্রোফাইল — স্থায়ীভাবে মুছে দেয়। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "নির্ধারিত হয়, পাশাপাশি মূল টিপস। প্রথম অনুসন্ধান ইন্টারনেট ব্যবহার করে, তারপর এটি সংরক্ষিত হয় যাতে পরের বার তাৎক্ষণিকভাবে খোলে।",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "উদাহরণ রিপোর্ট, রিমাইন্ডার ও আগে থেকে পূরণ করা অ্যাপয়েন্টমেন্ট সহ, যাতে আপনি প্রকৃত কিছু স্ক্যান করার আগে প্রতিটি স্ক্রিন অন্বেষণ করতে পারেন। অ্যাকাউন্ট থেকে যেকোনো সময় এটি সরান।",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "সেই QR একটি ওয়েব পেজ খুলেছে, সরাসরি ফাইল নয়। এটি আপনার ব্রাউজারে খোলা হচ্ছে — সেখানে রিপোর্ট ডাউনলোড করুন, তারপর এটি ইমপোর্ট করতে \"ডিভাইস থেকে\" ব্যবহার করুন।",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "বড় নথিগুলিকে বিশ্লেষণের জন্য ভাগ করার পদ্ধতিতে সংশোধনের আগে %1\$d টি বহু-পৃষ্ঠার স্ক্যান প্রক্রিয়া করা হয়েছিল — একই নথির কোনও প্যানেল (যেমন ইলেক্ট্রোলাইট বা PT/INR পৃষ্ঠা) বাদ পড়তে পারে। এটি ইতিমধ্যে সংরক্ষিত পৃষ্ঠাগুলি ব্যবহার করে সেগুলি আবার যাচাই করে এবং যা বাদ পড়েছিল তা যোগ করে; আগে থেকে সংরক্ষিত কিছুই বদলায় না।",
