        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "ਚੁਣੀਆਂ ਫਾਈਲਾਂ ਬਹੁਤ ਵੱਡੀਆਂ ਹਨ (%.2f MB)। ਇਹਨਾਂ ਫਾਈਲਾਂ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਨ ਵਿੱਚ ਵੱਧ ਸਮਾਂ ਲੱਗੇਗਾ ਅਤੇ ਮੈਮੋਰੀ ਸਮੱਸਿਆਵਾਂ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਅਸੀਂ ਫਾਈਲਾਂ ਨੂੰ 10 MB ਤੋਂ ਘੱਟ ਰੱਖਣ ਦੀ ਸਿਫਾਰਸ਼ ਕਰਦੇ ਹਾਂ। ਕੀ ਤੁਸੀਂ ਫਿਰ ਵੀ ਅੱਗੇ ਵਧਣਾ ਚਾਹੁੰਦੇ ਹੋ?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "ਇਹ ਅਸਲੀ ਨਹੀਂ ਹੈ। ਇਸਨੂੰ ਹਟਾਓ, ਜਾਂ ਆਪਣੇ ਖੁਦ ਦੇ ਰਿਕਾਰਡ ਟਰੈਕ ਕਰਨਾ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਸਾਈਨ ਇਨ ਕਰੋ।",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "ਇਹ ਸਾਰੀਆਂ ਰਿਪੋਰਟਾਂ, ਦਵਾਈਆਂ, ਬਕਾਇਆ ਟੈਸਟ ਅਤੇ ਚਿੱਤਰ ਸਥਾਈ ਤੌਰ 'ਤੇ ਮਿਟਾਉਂਦਾ ਹੈ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਲਿਆ ਜਾ ਸਕਦਾ।",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "ਇਹ ਮੂਲ ਰੂਪ ਵਿੱਚ ਸਕੈਨ ਕੀਤੀ ਤਸਵੀਰ 'ਤੇ AI ਵਿਸ਼ਲੇਸ਼ਣ ਦੁਬਾਰਾ ਚਲਾਉਂਦਾ ਹੈ ਅਤੇ ਹੇਠਾਂ ਕੱਢੇ ਗਏ ਟੈਸਟ ਮੁੱਲਾਂ, ਦਵਾਈਆਂ ਅਤੇ ਸੂਝਾਂ ਨੂੰ ਤਾਜ਼ਾ ਕਰਦਾ ਹੈ। ਜੇ ਪਹਿਲਾਂ ਦਾ ਸਕੈਨ ਅਧੂਰਾ ਆਇਆ ਸੀ (ਜਿਵੇਂ API ਥੋੜ੍ਹੀ ਦੇਰ ਲਈ ਅਣਉਪਲਬਧ ਸੀ) ਤਾਂ ਇਹ ਲਾਭਦਾਇਕ ਹੈ। ਇਹ ਤੁਹਾਡੇ ਕੁਝ API ਕੋਟੇ ਦੀ ਵਰਤੋਂ ਕਰ ਸਕਦਾ ਹੈ।",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "ਇਸ ਰਿਪੋਰਟ ਦੀ ਫਾਈਲ ਸੇਵ ਹੈ ਪਰ AI ਦੁਆਰਾ ਵਿਸ਼ਲੇਸ਼ਣ ਨਹੀਂ ਕੀਤਾ ਗਿਆ, ਇਸ ਲਈ ਇਸ ਵਿੱਚ ਅਜੇ ਤੱਕ ਕੋਈ ਟੈਸਟ ਮੁੱਲ, ਰੁਝਾਨ ਜਾਂ ਸੂਝ ਨਹੀਂ ਹੈ। ਜਦੋਂ ਵੀ ਤੁਸੀਂ ਤਿਆਰ ਹੋਵੋ ਇਸਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ (ਕੁਝ API ਕੋਟਾ ਵਰਤਦਾ ਹੈ)।",
