        "Scan any medical report" to "ਕੋਈ ਵੀ ਮੈਡੀਕਲ ਰਿਪੋਰਟ ਸਕੈਨ ਕਰੋ",
        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "ਕਾਗਜ਼ੀ ਲੈਬ ਰਿਪੋਰਟਾਂ, ਨੁਸਖਿਆਂ ਅਤੇ ਡਿਸਚਾਰਜ ਸੰਖੇਪਾਂ ਨੂੰ ਸੰਗਠਿਤ, ਖੋਜਣਯੋਗ ਡਿਜੀਟਲ ਰਿਕਾਰਡਾਂ ਵਿੱਚ ਬਦਲੋ — ਸਿੱਧਾ ਤੁਹਾਡੇ ਫੋਨ ਦੇ ਕੈਮਰੇ ਤੋਂ।",
        "Understand it instantly" to "ਇਸਨੂੰ ਤੁਰੰਤ ਸਮਝੋ",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI ਪੰਨੇ 'ਤੇ ਹਰ ਟੈਸਟ ਮੁੱਲ, ਦਵਾਈ ਅਤੇ ਮਿਤੀ ਪੜ੍ਹਦਾ ਹੈ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਡਾਕਟਰੀ ਸ਼ਬਦਜਾਲ ਵਿੱਚ ਫਸੇ ਬਿਨਾਂ ਰਿਪੋਰਟ ਦਾ ਅਸਲ ਮਤਲਬ ਦੇਖ ਸਕੋ।",
        "Never miss a dose or a follow-up" to "ਕਦੇ ਵੀ ਖੁਰਾਕ ਜਾਂ ਫਾਲੋ-ਅੱਪ ਨਾ ਖੁੰਝਾਓ",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "ਦਵਾਈ ਰਿਮਾਈਂਡਰ ਹਰ ਰੋਜ਼ ਸਹੀ ਸਮੇਂ 'ਤੇ ਵੱਜਦੇ ਹਨ — ਹਫ਼ਤੇ ਵਿੱਚ ਦੋ ਵਾਰ ਵਾਲੀ ਦਵਾਈ ਲਈ ਵੀ — ਅਤੇ ਡਾਕਟਰ ਮੁਲਾਕਾਤਾਂ ਨੂੰ ਵੀ ਆਪਣਾ ਰਿਮਾਈਂਡਰ ਮਿਲਦਾ ਹੈ।",
        "What do my latest test results mean?" to "ਮੇਰੇ ਨਵੀਨਤਮ ਟੈਸਟ ਨਤੀਜਿਆਂ ਦਾ ਕੀ ਮਤਲਬ ਹੈ?",
        "Explain my current medicines in simple words" to "ਮੇਰੀਆਂ ਮੌਜੂਦਾ ਦਵਾਈਆਂ ਨੂੰ ਸਧਾਰਨ ਸ਼ਬਦਾਂ ਵਿੱਚ ਸਮਝਾਓ",
        "Are any of my values abnormal?" to "ਕੀ ਮੇਰੇ ਕੋਈ ਮੁੱਲ ਅਸਾਧਾਰਨ ਹਨ?",
        "What should I ask my doctor next?" to "ਮੈਨੂੰ ਆਪਣੇ ਡਾਕਟਰ ਤੋਂ ਅੱਗੇ ਕੀ ਪੁੱਛਣਾ ਚਾਹੀਦਾ ਹੈ?",
        "Rx" to "Rx",
        "Hospitals" to "ਹਸਪਤਾਲ",
        "Lab Tests" to "ਲੈਬ ਟੈਸਟ",
        "Doctors" to "ਡਾਕਟਰ",
        "Broadcasting search to UHI gateway..." to "UHI ਗੇਟਵੇ ਨੂੰ ਖੋਜ ਪ੍ਰਸਾਰਿਤ ਕੀਤੀ ਜਾ ਰਹੀ ਹੈ...",
        "Gateway ACK received. Listening for provider webhook responses..." to "ਗੇਟਵੇ ACK ਪ੍ਰਾਪਤ ਹੋਇਆ। ਪ੍ਰਦਾਤਾ ਵੈੱਬਹੁੱਕ ਜਵਾਬਾਂ ਲਈ ਸੁਣਿਆ ਜਾ ਰਿਹਾ ਹੈ...",
        "Listening for provider webhooks... (Incoming responses)" to "ਪ੍ਰਦਾਤਾ ਵੈੱਬਹੁੱਕਾਂ ਲਈ ਸੁਣਿਆ ਜਾ ਰਿਹਾ ਹੈ... (ਆ ਰਹੇ ਜਵਾਬ)",
        "3M" to "3 ਮਹੀਨੇ",
        "6M" to "6 ਮਹੀਨੇ",
        "1Y" to "1 ਸਾਲ",
        "2Y" to "2 ਸਾਲ",
        "10 km" to "10 ਕਿਮੀ",
        "20 km" to "20 ਕਿਮੀ",
        "50 km" to "50 ਕਿਮੀ",
        "Any" to "ਕੋਈ ਵੀ",
        "Couldn't load your account. Check your connection and try again." to "ਤੁਹਾਡਾ ਖਾਤਾ ਲੋਡ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਆਪਣਾ ਕਨੈਕਸ਼ਨ ਜਾਂਚੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
        "Please enter a valid API key or tap 'Revert to Shared Pool'." to "ਕਿਰਪਾ ਕਰਕੇ ਇੱਕ ਵੈਧ API ਕੁੰਜੀ ਦਰਜ ਕਰੋ ਜਾਂ 'ਸਾਂਝੇ ਪੂਲ 'ਤੇ ਵਾਪਸ ਜਾਓ' 'ਤੇ ਟੈਪ ਕਰੋ।",
        "Personal API Key saved! Switched to Individual Key mode." to "ਨਿੱਜੀ API ਕੁੰਜੀ ਸੇਵ ਹੋਈ! ਵਿਅਕਤੀਗਤ ਕੁੰਜੀ ਮੋਡ ਵਿੱਚ ਬਦਲਿਆ।",
        "Reverted to Primary Shared Key Pool." to "ਪ੍ਰਾਇਮਰੀ ਸਾਂਝੇ ਕੀਤੇ ਕੀ ਪੂਲ 'ਤੇ ਵਾਪਸ ਗਏ।",
        "All fields are required." to "ਸਾਰੇ ਖੇਤਰ ਲੋੜੀਂਦੇ ਹਨ।",
        "New password must be at least 6 characters." to "ਨਵਾਂ ਪਾਸਵਰਡ ਘੱਟੋ-ਘੱਟ 6 ਅੱਖਰਾਂ ਦਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
        "Password updated successfully." to "ਪਾਸਵਰਡ ਸਫਲਤਾਪੂਰਵਕ ਅੱਪਡੇਟ ਹੋਇਆ।",
        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "ਸਹਾਇਕ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚ ਸਕਿਆ। ਜਾਂਚੋ ਕਿ ਸਰਵਰ ਚੱਲ ਰਿਹਾ ਹੈ ਅਤੇ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸੰਰਚਿਤ ਹੈ।",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਵੌਇਸ ਇਨਪੁੱਟ ਉਪਲਬਧ ਨਹੀਂ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ Google ਵੌਇਸ ਟਾਈਪਿੰਗ ਇੰਸਟਾਲ/ਸਮਰੱਥ ਕਰੋ।",
        "Couldn't generate the detailed analysis. Please try again." to "ਵਿਸਤ੍ਰਿਤ ਵਿਸ਼ਲੇਸ਼ਣ ਤਿਆਰ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
        "Search failed. Make sure the backend server is running and database is migrated." to "ਖੋਜ ਅਸਫਲ ਰਹੀ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਬੈਕਐਂਡ ਸਰਵਰ ਚੱਲ ਰਿਹਾ ਹੈ ਅਤੇ ਡੇਟਾਬੇਸ ਮਾਈਗ੍ਰੇਟ ਹੈ।",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "ਦਵਾਈਆਂ ਪ੍ਰਾਪਤ ਕਰਨ ਵਿੱਚ ਅਸਫਲ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਹਾਡਾ ਸਥਾਨਕ ਸਰਵਰ ਚੱਲ ਰਿਹਾ ਹੈ ਅਤੇ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਹੀ ਢੰਗ ਨਾਲ ਸੰਰਚਿਤ ਹੈ।",
        "Failed to delete the selected medicines." to "ਚੁਣੀਆਂ ਦਵਾਈਆਂ ਮਿਟਾਉਣ ਵਿੱਚ ਅਸਫਲ।",
        "Failed to update the selected medicines." to "ਚੁਣੀਆਂ ਦਵਾਈਆਂ ਅੱਪਡੇਟ ਕਰਨ ਵਿੱਚ ਅਸਫਲ।",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "ਬਕਾਇਆ ਟੈਸਟ ਪ੍ਰਾਪਤ ਕਰਨ ਵਿੱਚ ਅਸਫਲ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਹਾਡਾ ਸਥਾਨਕ ਸਰਵਰ ਚੱਲ ਰਿਹਾ ਹੈ ਅਤੇ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਹੀ ਢੰਗ ਨਾਲ ਸੰਰਚਿਤ ਹੈ।",
        "Failed to delete test reminder." to "ਟੈਸਟ ਰਿਮਾਈਂਡਰ ਮਿਟਾਉਣ ਵਿੱਚ ਅਸਫਲ।",
        "Patient and Test names are required." to "ਮਰੀਜ਼ ਅਤੇ ਟੈਸਟ ਦੇ ਨਾਮ ਲੋੜੀਂਦੇ ਹਨ।",
        "Failed to save test reminder." to "ਟੈਸਟ ਰਿਮਾਈਂਡਰ ਸੇਵ ਕਰਨ ਵਿੱਚ ਅਸਫਲ।",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "ਰਿਕਾਰਡ ਪ੍ਰਾਪਤ ਕਰਨ ਵਿੱਚ ਅਸਫਲ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਹਾਡਾ ਸਥਾਨਕ ਸਰਵਰ ਚੱਲ ਰਿਹਾ ਹੈ ਅਤੇ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਹੀ ਢੰਗ ਨਾਲ ਸੰਰਚਿਤ ਹੈ।",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "ਰਿਮਾਈਂਡਰ ਪ੍ਰਾਪਤ ਕਰਨ ਵਿੱਚ ਅਸਫਲ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਹਾਡਾ ਸਥਾਨਕ ਸਰਵਰ ਚੱਲ ਰਿਹਾ ਹੈ ਅਤੇ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਹੀ ਢੰਗ ਨਾਲ ਸੰਰਚਿਤ ਹੈ।",
        "Couldn't save the file." to "ਫਾਈਲ ਸੇਵ ਨਹੀਂ ਹੋ ਸਕੀ।",
        "No app available to open this file type." to "ਇਸ ਫਾਈਲ ਕਿਸਮ ਨੂੰ ਖੋਲ੍ਹਣ ਲਈ ਕੋਈ ਐਪ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।",
        "Couldn't share this file." to "ਇਹ ਫਾਈਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕੀ।",
        "Report not found." to "ਰਿਪੋਰਟ ਨਹੀਂ ਮਿਲੀ।",
        "Failed to load report details." to "ਰਿਪੋਰਟ ਵੇਰਵੇ ਲੋਡ ਕਰਨ ਵਿੱਚ ਅਸਫਲ।",
        "Failed to save edits. Check network settings." to "ਸੰਪਾਦਨ ਸੇਵ ਕਰਨ ਵਿੱਚ ਅਸਫਲ। ਨੈੱਟਵਰਕ ਸੈਟਿੰਗਾਂ ਦੀ ਜਾਂਚ ਕਰੋ।",
        "Failed to delete report." to "ਰਿਪੋਰਟ ਮਿਟਾਉਣ ਵਿੱਚ ਅਸਫਲ।",
        "Couldn't reprocess: report or its scanned image is missing." to "ਮੁੜ-ਪ੍ਰੋਸੈਸ ਨਹੀਂ ਹੋ ਸਕਿਆ: ਰਿਪੋਰਟ ਜਾਂ ਇਸਦੀ ਸਕੈਨ ਕੀਤੀ ਤਸਵੀਰ ਗੁੰਮ ਹੈ।",
        "Failed to reprocess this report." to "ਇਸ ਰਿਪੋਰਟ ਨੂੰ ਮੁੜ-ਪ੍ਰੋਸੈਸ ਕਰਨ ਵਿੱਚ ਅਸਫਲ।",
        "Medicine name is required." to "ਦਵਾਈ ਦਾ ਨਾਮ ਲੋੜੀਂਦਾ ਹੈ।",
        "Select at least one reminder slot." to "ਘੱਟੋ-ਘੱਟ ਇੱਕ ਰਿਮਾਈਂਡਰ ਸਲਾਟ ਚੁਣੋ।",
        "Doctor name is required." to "ਡਾਕਟਰ ਦਾ ਨਾਮ ਲੋੜੀਂਦਾ ਹੈ।",
        "Place is required." to "ਥਾਂ ਲੋੜੀਂਦੀ ਹੈ।",
        "Date is required." to "ਮਿਤੀ ਲੋੜੀਂਦੀ ਹੈ।",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "ਇਸ ਡਿਵਾਈਸ ਦਾ ਸੁਰੱਖਿਅਤ ਹਾਰਡਵੇਅਰ ਸਟੋਰੇਜ ਉਪਲਬਧ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਤੁਹਾਡੀ ਸਥਾਨਕ ਰਿਕਾਰਡ ਕੁੰਜੀ ਅਤੇ ਲਿੰਕਡ-ਈਮੇਲ ਪ੍ਰਮਾਣ ਪੱਤਰ ਹਾਰਡਵੇਅਰ-ਬੈਕਡ ਇਨਕ੍ਰਿਪਸ਼ਨ ਤੋਂ ਬਿਨਾਂ ਸਟੋਰ ਕੀਤੇ ਗਏ ਹਨ। ਤੁਹਾਡਾ ਡੇਟਾ ਫਿਰ ਵੀ ਅਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਕਿਤੇ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ, ਪਰ ਇਹ ਡਿਵਾਈਸ ਆਮ ਨਾਲੋਂ ਕਮਜ਼ੋਰ ਸੁਰੱਖਿਆ ਦਿੰਦੀ ਹੈ।",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "ਸਕੈਨਿੰਗ, ਰਿਮਾਈਂਡਰ, ਅਤੇ ਬਾਕੀ ਸਭ ਕੁਝ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਸਾਈਨ ਇਨ ਕੀਤੇ ਬਿਨਾਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਕੰਮ ਕਰਦਾ ਹੈ। ਸਾਈਨ ਇਨ ਵਿਕਲਪਿਕ ਹੈ (ਇਹ SMS ਕੋਡ ਭੇਜਦਾ ਹੈ, ਇਸ ਲਈ ਇਹ ਆਟੋਮੈਟਿਕ ਨਹੀਂ ਹੈ) — ਇਸਦੀ ਵਰਤੋਂ ਕਰੋ ਜੇ ਤੁਹਾਨੂੰ ਇੱਕ ਪ੍ਰੋਫਾਈਲ ਜਾਂ ਨਿੱਜੀ API ਕੁੰਜੀ ਚਾਹੀਦੀ ਹੈ ਜੋ ਡਿਵਾਈਸਾਂ ਵਿੱਚ ਤੁਹਾਡੇ ਨਾਲ ਰਹੇ।",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "ਹਰ ਰੁਝਾਨ ਚਾਰਟ ਜਿਸ ਯੂਨਿਟ ਵਿੱਚ ਰੀਡਿੰਗਾਂ ਨੂੰ ਮਿਆਰੀ ਬਣਾਉਂਦਾ ਹੈ। ਵੱਖਰੇ ਯੂਨਿਟ ਵਾਲੀਆਂ ਰਿਪੋਰਟਾਂ ਆਪਣੇ ਆਪ ਬਦਲੀਆਂ ਜਾਂਦੀਆਂ ਹਨ; ਹਰ ਰਿਪੋਰਟ ਅਜੇ ਵੀ ਆਪਣਾ ਅਸਲ ਮੁੱਲ ਦਿਖਾਉਂਦੀ ਹੈ।",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "ਕਿਉਂ: Health Decoder ਲਾਗਤ ਘੱਟ ਰੱਖ ਕੇ ਮੁਫ਼ਤ ਰਹਿੰਦੀ ਹੈ, ਤੁਹਾਡੇ ਰਿਕਾਰਡ ਵੇਚ ਕੇ ਨਹੀਂ। ਜੇ ਤੁਸੀਂ ਇੱਥੇ ਸ਼ਾਮਲ ਹੁੰਦੇ ਹੋ, ਤਾਂ ਸਿਰਫ਼ ਤੁਹਾਡੀ ਉਮਰ ਅਤੇ ਲਿੰਗ — ਕਦੇ ਵੀ ਤੁਹਾਡਾ ਨਾਮ, ਰਿਪੋਰਟਾਂ, ਜਾਂ ਸਹੀ ਟਿਕਾਣਾ ਨਹੀਂ — ਡਾਕਟਰੀ ਖੋਜ ਸੰਸਥਾਵਾਂ ਨਾਲ ਸਮੂਹਿਕ ਤੌਰ 'ਤੇ ਸਾਂਝਾ ਕੀਤਾ ਜਾਵੇਗਾ, ਤਾਂ ਜੋ ਇਸ਼ਤਿਹਾਰ ਚਲਾਉਣ ਜਾਂ ਗਾਹਕੀ ਲੈਣ ਦੀ ਬਜਾਏ ਐਪ ਨੂੰ ਹਰ ਪਰਿਵਾਰ ਲਈ ਮੁਫ਼ਤ ਰੱਖਣ ਵਿੱਚ ਮਦਦ ਮਿਲੇ।",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "ਇਹ ਪ੍ਰੋਗਰਾਮ ਅਜੇ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋਇਆ — ਅੱਜ ਇਸਨੂੰ ਚਾਲੂ ਕਰਨ ਨਾਲ ਸਿਰਫ਼ ਤੁਹਾਡੀ ਪਸੰਦ ਸੇਵ ਹੁੰਦੀ ਹੈ। ਅਸਲ ਡੇਟਾ-ਸ਼ੇਅਰਿੰਗ ਪਾਈਪਲਾਈਨ ਮੌਜੂਦ ਹੋਣ ਤੱਕ ਕੁਝ ਵੀ ਕਿਤੇ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ, ਅਤੇ ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਇੱਥੇ ਆਪਣਾ ਜਵਾਬ ਬਦਲ ਸਕਦੇ ਹੋ।",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "ਇਹ ਤੁਹਾਡਾ Health Decoder ਖਾਤਾ ਅਤੇ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਸਟੋਰ ਕੀਤੇ ਸਾਰੇ ਮੈਡੀਕਲ ਰਿਕਾਰਡ — ਰਿਪੋਰਟਾਂ, ਰਿਮਾਈਂਡਰ, ਮੁਲਾਕਾਤਾਂ, ਅਤੇ ਪਰਿਵਾਰਕ ਪ੍ਰੋਫਾਈਲਾਂ — ਸਥਾਈ ਤੌਰ 'ਤੇ ਮਿਟਾਉਂਦਾ ਹੈ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਲਿਆ ਜਾ ਸਕਦਾ।",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "ਨਿਰਧਾਰਤ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਨਾਲ ਹੀ ਮੁੱਖ ਸੁਝਾਅ ਵੀ। ਪਹਿਲੀ ਖੋਜ ਇੰਟਰਨੈੱਟ ਵਰਤਦੀ ਹੈ, ਫਿਰ ਇਹ ਸੇਵ ਹੋ ਜਾਂਦੀ ਹੈ ਤਾਂ ਜੋ ਅਗਲੀ ਵਾਰ ਤੁਰੰਤ ਖੁੱਲ੍ਹੇ।",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "ਉਦਾਹਰਨ ਰਿਪੋਰਟਾਂ, ਰਿਮਾਈਂਡਰ ਅਤੇ ਪਹਿਲਾਂ ਤੋਂ ਭਰੀ ਮੁਲਾਕਾਤ ਨਾਲ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਕੁਝ ਵੀ ਅਸਲੀ ਸਕੈਨ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਹਰ ਸਕ੍ਰੀਨ ਦੀ ਪੜਚੋਲ ਕਰ ਸਕੋ। ਇਸਨੂੰ ਖਾਤੇ ਤੋਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਹਟਾਓ।",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ਉਸ QR ਨੇ ਇੱਕ ਵੈੱਬ ਪੇਜ ਖੋਲ੍ਹਿਆ, ਸਿੱਧੀ ਫਾਈਲ ਨਹੀਂ। ਇਸਨੂੰ ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਖੋਲ੍ਹਿਆ ਜਾ ਰਿਹਾ ਹੈ — ਉੱਥੇ ਰਿਪੋਰਟ ਡਾਊਨਲੋਡ ਕਰੋ, ਫਿਰ ਇਸਨੂੰ ਇੰਪੋਰਟ ਕਰਨ ਲਈ \"ਡਿਵਾਈਸ ਤੋਂ\" ਵਰਤੋ।",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "ਵੱਡੇ ਦਸਤਾਵੇਜ਼ਾਂ ਨੂੰ ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਵੰਡਣ ਦੇ ਤਰੀਕੇ ਵਿੱਚ ਸੁਧਾਰ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ %1\$d ਬਹੁ-ਪੰਨਾ ਸਕੈਨ ਪ੍ਰੋਸੈੱਸ ਹੋਏ ਸਨ — ਉਸੇ ਦਸਤਾਵੇਜ਼ ਦਾ ਕੋਈ ਪੈਨਲ (ਜਿਵੇਂ ਇਲੈਕਟ੍ਰੋਲਾਈਟਸ ਜਾਂ PT/INR ਪੰਨਾ) ਛੁੱਟ ਸਕਦਾ ਹੈ। ਇਹ ਪਹਿਲਾਂ ਹੀ ਸੰਭਾਲੇ ਪੰਨਿਆਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਉਹਨਾਂ ਦੀ ਮੁੜ ਜਾਂਚ ਕਰਦਾ ਹੈ ਅਤੇ ਜੋ ਛੁੱਟ ਗਿਆ ਸੀ ਉਹ ਜੋੜਦਾ ਹੈ; ਪਹਿਲਾਂ ਸੰਭਾਲਿਆ ਹੋਇਆ ਉਵੇਂ ਹੀ ਰਹਿੰਦਾ ਹੈ।",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "%1\$d ਰਿਪੋਰਟਾਂ ਉਸ ਵੇਲੇ ਸੰਭਾਲੀਆਂ ਗਈਆਂ ਸਨ ਜਦੋਂ AI ਵਿਸ਼ਲੇਸ਼ਣ ਸਰਵਰ ਉਪਲਬਧ ਨਹੀਂ ਸੀ (ਜਿਵੇਂ ਰੋਜ਼ਾਨਾ ਕੋਟਾ ਪੂਰਾ ਹੋ ਗਿਆ), ਇਸ ਲਈ ਉਹਨਾਂ ਦੀ ਤਾਰੀਖ ਅਤੇ ਸ਼੍ਰੇਣੀ ਦਸਤਾਵੇਜ਼ ਤੋਂ ਪੜ੍ਹੀ ਨਹੀਂ ਗਈ, ਸਗੋਂ ਅੰਦਾਜ਼ਾ ਹੈ। ਮੁੜ-ਵਿਸ਼ਲੇਸ਼ਣ ਪਹਿਲਾਂ ਸੰਭਾਲੀਆਂ ਤਸਵੀਰਾਂ ਵਰਤਦਾ ਹੈ — ਤੁਹਾਨੂੰ ਦੁਬਾਰਾ ਸਕੈਨ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ।",
        "Add, edit, or remove people this device tracks — including yourself" to "ਇਸ ਡਿਵਾਈਸ ਵੱਲੋਂ ਟ੍ਰੈਕ ਕੀਤੇ ਜਾਂਦੇ ਲੋਕਾਂ ਨੂੰ ਜੋੜੋ, ਸੋਧੋ ਜਾਂ ਹਟਾਓ — ਆਪਣੇ ਸਮੇਤ",
        "Also protect automatic backups with a password" to "ਆਟੋਮੈਟਿਕ ਬੈਕਅੱਪ ਨੂੰ ਵੀ ਪਾਸਵਰਡ ਨਾਲ ਸੁਰੱਖਿਅਤ ਕਰੋ",
        "Auto-backup password" to "ਸਵੈ-ਬੈਕਅੱਪ ਪਾਸਵਰਡ",
        "Backup password" to "ਬੈਕਅੱਪ ਪਾਸਵਰਡ",
        "Based on your %1\$s result (%2\$s) from your report dated %3\$s." to "%3\$s ਦੀ ਤੁਹਾਡੀ ਰਿਪੋਰਟ ਵਿੱਚ %1\$s ਦੇ ਨਤੀਜੇ (%2\$s) ਦੇ ਆਧਾਰ 'ਤੇ।",
        "Blood" to "ਖੂਨ",
