        "Checking %1\$d of %2\$d…" to "%2\$d ਵਿੱਚੋਂ %1\$d ਦੀ ਜਾਂਚ ਹੋ ਰਹੀ ਹੈ…",
        "Compare" to "ਤੁਲਨਾ",
        "Confirm password" to "ਪਾਸਵਰਡ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
