        "Date of Birth (YYYY-MM-DD)" to "ਜਨਮ ਤਾਰੀਖ (YYYY-MM-DD)",
        "Discharge Summary" to "ਡਿਸਚਾਰਜ ਸੰਖੇਪ",
        "Discharge Summary + Prescription" to "ਡਿਸਚਾਰਜ ਸੰਖੇਪ + ਪ੍ਰਿਸਕ੍ਰਿਪਸ਼ਨ",
        "Echo" to "ਈਕੋ",
        "Edit Profile" to "ਪ੍ਰੋਫਾਈਲ ਸੋਧੋ",
        "Edit profile" to "ਪ੍ਰੋਫਾਈਲ ਸੋਧੋ",
        "Ends" to "ਸਮਾਪਤ",
        "Enter Backup Password" to "ਬੈਕਅੱਪ ਪਾਸਵਰਡ ਦਰਜ ਕਰੋ",
        "Every" to "ਹਰ",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restoring REPLACES everything currently on this device." to "ਆਪਣੇ ਸਾਰੇ ਰਿਕਾਰਡ (ਰਿਪੋਰਟਾਂ + ਤਸਵੀਰਾਂ) ਇੱਕੋ ਬੈਕਅੱਪ ਫਾਈਲ ਵਜੋਂ ਐਕਸਪੋਰਟ ਕਰੋ। ਕਲਾਊਡ ਕਾਪੀ ਰੱਖਣ ਲਈ ਪਿਕਰ ਵਿੱਚ ਆਪਣਾ Google Drive ਜਾਂ OneDrive ਫੋਲਡਰ ਚੁਣੋ। ਰੀਸਟੋਰ ਕਰਨ ਨਾਲ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਮੌਜੂਦ ਸਭ ਕੁਝ ਬਦਲ ਜਾਂਦਾ ਹੈ।",
        "Family Members" to "ਪਰਿਵਾਰਕ ਮੈਂਬਰ",
        "First Name" to "ਪਹਿਲਾ ਨਾਮ",
        "Free Gemini API Key (Optional)" to "ਮੁਫ਼ਤ Gemini API ਕੁੰਜੀ (ਵਿਕਲਪਿਕ)",
        "Full Backup & Restore" to "ਪੂਰਾ ਬੈਕਅੱਪ ਅਤੇ ਰੀਸਟੋਰ",
        "General lifestyle suggestion, not medical advice — talk to your doctor before making changes based on a lab result." to "ਆਮ ਜੀਵਨਸ਼ੈਲੀ ਸੁਝਾਅ, ਡਾਕਟਰੀ ਸਲਾਹ ਨਹੀਂ — ਲੈਬ ਨਤੀਜੇ ਦੇ ਆਧਾਰ 'ਤੇ ਬਦਲਾਅ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੇ ਡਾਕਟਰ ਨਾਲ ਗੱਲ ਕਰੋ।",
        "Get Free API Key" to "ਮੁਫ਼ਤ API ਕੁੰਜੀ ਲਵੋ",
        "Got it" to "ਸਮਝ ਗਏ",
        "HEALTH TIP" to "ਸਿਹਤ ਸੁਝਾਅ",
        "Health Decoder" to "ਹੈਲਥ ਡੀਕੋਡਰ",
        "Hello," to "ਸਤ ਸ੍ਰੀ ਅਕਾਲ,",
        "High" to "ਵੱਧ",
        "Home" to "ਹੋਮ",
        "Last Name" to "ਆਖਰੀ ਨਾਮ",
        "Learn More" to "ਹੋਰ ਜਾਣੋ",
        "Leave blank to keep the current one" to "ਮੌਜੂਦਾ ਹੀ ਰੱਖਣ ਲਈ ਖਾਲੀ ਛੱਡੋ",
        "Live camera scan — point and get instant answers" to "ਲਾਈਵ ਕੈਮਰਾ ਸਕੈਨ — ਕੈਮਰਾ ਸੇਧੋ ਅਤੇ ਤੁਰੰਤ ਜਵਾਬ ਪਾਓ",
        "Low" to "ਘੱਟ",
        "Medical Report" to "ਮੈਡੀਕਲ ਰਿਪੋਰਟ",
        "Not set" to "ਸੈੱਟ ਨਹੀਂ",
        "Not signed in" to "ਸਾਈਨ ਇਨ ਨਹੀਂ ਕੀਤਾ",
        "Off by default — these sync to your cloud folder above without a password unless you set one here" to "ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ — ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇੱਥੇ ਇੱਕ ਸੈੱਟ ਨਹੀਂ ਕਰਦੇ, ਇਹ ਉੱਪਰਲੇ ਤੁਹਾਡੇ ਕਲਾਊਡ ਫੋਲਡਰ ਵਿੱਚ ਪਾਸਵਰਡ ਤੋਂ ਬਿਨਾਂ ਸਿੰਕ ਹੁੰਦੇ ਹਨ",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "ਪ੍ਰਿਸਕ੍ਰਿਪਸ਼ਨ ਸਕੈਨ ਹੋਣ ਤੋਂ ਬਾਅਦ, ਤੁਹਾਡੀਆਂ ਰੋਜ਼ਾਨਾ ਦਵਾਈਆਂ ਰਿਮਾਈਂਡਰਾਂ ਨਾਲ ਇੱਥੇ ਦਿਖਣਗੀਆਂ।\n\nਹਰ ਦਵਾਈ ਲਈ ਰਿਮਾਈਂਡਰ ਚਾਲੂ ਕਰਨ ਵਾਸਤੇ ਹੇਠਾਂ ਟੌਗਲ ਦਬਾਓ।",
        "Optional — keeps your data available across devices" to "ਵਿਕਲਪਿਕ — ਤੁਹਾਡਾ ਡਾਟਾ ਸਾਰੇ ਡਿਵਾਈਸਾਂ 'ਤੇ ਉਪਲਬਧ ਰੱਖਦਾ ਹੈ",
        "Optional — leave blank to use the shared pool" to "ਵਿਕਲਪਿਕ — ਸਾਂਝੇ ਪੂਲ ਦੀ ਵਰਤੋਂ ਲਈ ਖਾਲੀ ਛੱਡੋ",
        "PERSONALIZED FOR YOU" to "ਤੁਹਾਡੇ ਲਈ ਖਾਸ",
        "Passwords don't match" to "ਪਾਸਵਰਡ ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ",
        "Profile" to "ਪ੍ਰੋਫਾਈਲ",
        "Protect this backup with a password" to "ਇਸ ਬੈਕਅੱਪ ਨੂੰ ਪਾਸਵਰਡ ਨਾਲ ਸੁਰੱਖਿਅਤ ਕਰੋ",
        "Re-analyze All (%1\$d)" to "ਸਾਰਿਆਂ ਦਾ ਮੁੜ-ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ (%1\$d)",
        "Re-analyzing %1\$d of %2\$d…" to "%2\$d ਵਿੱਚੋਂ %1\$d ਦਾ ਮੁੜ-ਵਿਸ਼ਲੇਸ਼ਣ ਹੋ ਰਿਹਾ ਹੈ…",
        "Reports Needing Re-check" to "ਮੁੜ-ਜਾਂਚ ਵਾਲੀਆਂ ਰਿਪੋਰਟਾਂ",
        "Restoring…" to "ਰੀਸਟੋਰ ਹੋ ਰਿਹਾ ਹੈ…",
        "Select gender" to "ਲਿੰਗ ਚੁਣੋ",
        "Share / Merge Records" to "ਰਿਕਾਰਡ ਸਾਂਝੇ ਕਰੋ / ਮਿਲਾਓ",
        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "ਸਾਂਝਾ ਕਰੋ / ਮਿਲਾਓ ਚੁਣੀ ਹੋਈ ਜਾਣਕਾਰੀ ਕਿਸੇ ਹੋਰ ਫੋਨ ਜਾਂ ਡਾਕਟਰ ਨੂੰ ਭੇਜਦਾ ਹੈ ਅਤੇ ਉੱਥੇ ਮੌਜੂਦ ਵਿੱਚ ਜੋੜ ਦਿੰਦਾ ਹੈ। ਬੈਕਅੱਪ ਅਤੇ ਰੀਸਟੋਰ ਇਸ ਡਿਵਾਈਸ ਦਾ ਪੂਰਾ ਸਨੈਪਸ਼ਾਟ ਹੈ ਜੋ ਰੀਸਟੋਰ ਕਰਨ 'ਤੇ ਸਭ ਕੁਝ ਬਦਲ ਦਿੰਦਾ ਹੈ — ਇਸਨੂੰ ਸਾਂਝਾ ਕਰਨ ਲਈ ਨਹੀਂ, ਆਫ਼ਤ ਰਿਕਵਰੀ ਲਈ ਵਰਤੋ।",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "ਆਪਣਾ ਨਾਮ ਅਤੇ ਵੇਰਵੇ ਸੋਧਣ, ਨਿੱਜੀ API ਕੁੰਜੀ ਵਰਤਣ ਅਤੇ ਫਿੰਗਰਪ੍ਰਿੰਟ ਲੌਗਇਨ ਚਾਲੂ ਕਰਨ ਲਈ ਸਾਈਨ ਇਨ ਕਰੋ। ਇਸ ਤੋਂ ਬਿਨਾਂ ਵੀ ਐਪ ਪੂਰੀ ਤਰ੍ਹਾਂ ਕੰਮ ਕਰਦੀ ਹੈ — ਤੁਹਾਡੇ ਪਰਿਵਾਰਕ ਮੈਂਬਰ ਅਤੇ ਰਿਕਾਰਡ ਪਹਿਲਾਂ ਹੀ ਇਸੇ ਡਿਵਾਈਸ 'ਤੇ ਹਨ।",
        "Sign in to sync your records" to "ਆਪਣੇ ਰਿਕਾਰਡ ਸਿੰਕ ਕਰਨ ਲਈ ਸਾਈਨ ਇਨ ਕਰੋ",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "ਇਸਨੂੰ ਛੱਡ ਦਿਓ ਤਾਂ ਐਪ ਮੂਲ ਰੂਪ ਵਿੱਚ ਸਾਂਝੇ ਮੁਫ਼ਤ ਪੂਲ ਦੀ ਵਰਤੋਂ ਕਰਦੀ ਹੈ। ਆਪਣੀ ਕੁੰਜੀ ਪਹਿਲਾਂ ਹੀ ਜੋੜਨ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਉਸ ਪੂਲ ਦੀ ਰੋਜ਼ਾਨਾ ਹੱਦ ਤੁਹਾਨੂੰ ਕਦੇ ਨਹੀਂ ਰੋਕੇਗੀ।",
        "Sono" to "ਸੋਨੋ",
        "Starts" to "ਸ਼ੁਰੂ",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ਡਾਕਟਰ ਦੀ ਮੁਲਾਕਾਤ ਜਾਂ ਜਾਂਚ ਤੈਅ ਕਰਨ ਲਈ ਉੱਪਰ \"ਅਪਾਇੰਟਮੈਂਟ ਜੋੜੋ\" ਦਬਾਓ। ਸਮੇਂ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਨੂੰ ਯਾਦ ਕਰਵਾਇਆ ਜਾਵੇਗਾ।",
        "Tap to pick\nImage or PDF" to "ਚੁਣਨ ਲਈ ਦਬਾਓ\nਤਸਵੀਰ ਜਾਂ PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ਉਸ QR ਨੇ ਇੱਕ ਵੈੱਬ ਪੰਨਾ ਖੋਲ੍ਹਿਆ, ਸਿੱਧੀ ਫਾਈਲ ਨਹੀਂ। ਇਸਨੂੰ ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਖੋਲ੍ਹਿਆ ਜਾ ਰਿਹਾ ਹੈ — ਉੱਥੇ ਰਿਪੋਰਟ ਡਾਊਨਲੋਡ ਕਰੋ, ਫਿਰ ਇਸਨੂੰ ਇੰਪੋਰਟ ਕਰਨ ਲਈ \"ਡਿਵਾਈਸ ਤੋਂ\" ਵਰਤੋ।",
        "There's no way to reset this if you forget it — write it down somewhere safe." to "ਜੇ ਤੁਸੀਂ ਭੁੱਲ ਗਏ ਤਾਂ ਇਸਨੂੰ ਰੀਸੈੱਟ ਕਰਨ ਦਾ ਕੋਈ ਤਰੀਕਾ ਨਹੀਂ — ਇਸਨੂੰ ਕਿਤੇ ਸੁਰੱਖਿਅਤ ਲਿਖ ਲਵੋ।",
        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "ਜੇ ਤੁਸੀਂ ਭੁੱਲ ਗਏ ਤਾਂ ਇਸਨੂੰ ਰੀਸੈੱਟ ਕਰਨ ਦਾ ਕੋਈ ਤਰੀਕਾ ਨਹੀਂ — ਇਸਨੂੰ ਕਿਤੇ ਸੁਰੱਖਿਅਤ ਲਿਖ ਲਵੋ। ਬੈਕਅੱਪ ਪਾਸਵਰਡ ਗੁਆਚਣ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਉਹ ਬੈਕਅੱਪ ਕਦੇ ਰੀਸਟੋਰ ਨਹੀਂ ਹੋ ਸਕੇਗਾ।",
        "This backup is password-protected. Enter the password it was created with." to "ਇਹ ਬੈਕਅੱਪ ਪਾਸਵਰਡ ਨਾਲ ਸੁਰੱਖਿਅਤ ਹੈ। ਉਹੀ ਪਾਸਵਰਡ ਦਰਜ ਕਰੋ ਜਿਸ ਨਾਲ ਇਹ ਬਣਾਇਆ ਗਿਆ ਸੀ।",
        "Try Smart Health Lens" to "ਸਮਾਰਟ ਹੈਲਥ ਲੈਂਸ ਅਜ਼ਮਾਓ",
        "Welcome" to "ਜੀ ਆਇਆਂ ਨੂੰ",
        "Without one, anyone who gets the backup file can open it" to "ਇਸ ਤੋਂ ਬਿਨਾਂ, ਜਿਸਨੂੰ ਵੀ ਬੈਕਅੱਪ ਫਾਈਲ ਮਿਲੇਗੀ ਉਹ ਇਸਨੂੰ ਖੋਲ੍ਹ ਸਕਦਾ ਹੈ",
        "Your Profile" to "ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ",
