        "All patients" to "എല്ലാ രോഗികളും",
        "All search results, doctor availability, and diagnostic slots are purely informational. Sourced from the public UHI network, they are not clinical recommendations or confirmed appointments. Do not rely solely on this information. Always consult a qualified medical professional for health concerns." to "എല്ലാ തിരയൽ ഫലങ്ങളും, ഡോക്ടറുടെ ലഭ്യതയും, ഡയഗ്നോസ്റ്റിക് സ്ലോട്ടുകളും കേവലം വിവരങ്ങൾക്ക് മാത്രമാണ്. പൊതു UHI നെറ്റ്‌വർക്കിൽ നിന്ന് ലഭിച്ചത്, ഇവ ക്ലിനിക്കൽ ശുപാർശകളോ സ്ഥിരീകരിച്ച അപ്പോയിന്റ്മെന്റുകളോ അല്ല. ഈ വിവരത്തെ മാത്രം ആശ്രയിക്കരുത്. ആരോഗ്യ പ്രശ്നങ്ങൾക്ക് എപ്പോഴും യോഗ്യതയുള്ള ഒരു മെഡിക്കൽ പ്രൊഫഷണലിനെ സമീപിക്കുക.",
        "Analysing your report…" to "നിങ്ങളുടെ റിപ്പോർട്ട് വിശകലനം ചെയ്യുന്നു…",
