        "Enable Exact Alarms" to "കൃത്യമായ അലാറങ്ങൾ പ്രവർത്തനക്ഷമമാക്കുക",
        "Enable Fingerprint Login" to "വിരലടയാള ലോഗിൻ പ്രവർത്തനക്ഷമമാക്കുക",
        "Enable Fingerprint Login?" to "വിരലടയാള ലോഗിൻ പ്രവർത്തനക്ഷമമാക്കണോ?",
        "Enable or disable reminders per slot, tap the time to change it." to "ഓരോ സ്ലോട്ടിനും റിമൈൻഡറുകൾ പ്രവർത്തനക്ഷമമാക്കുക അല്ലെങ്കിൽ പ്രവർത്തനരഹിതമാക്കുക, മാറ്റാൻ സമയത്ത് ടാപ്പ് ചെയ്യുക.",
        "Enter a valid 10-digit mobile number." to "സാധുവായ 10-അക്ക മൊബൈൽ നമ്പർ നൽകുക.",
        "Enter an email and password." to "ഒരു ഇമെയിലും പാസ്‌വേഡും നൽകുക.",
