        "Enter the 10-digit mobile number linked to your account to verify your identity via OTP." to "OTP വഴി നിങ്ങളുടെ ഐഡന്റിറ്റി പരിശോധിക്കാൻ നിങ്ങളുടെ അക്കൗണ്ടുമായി ബന്ധിപ്പിച്ച 10-അക്ക മൊബൈൽ നമ്പർ നൽകുക.",
        "Enter the 6-digit OTP code sent to" to "ഇതിലേക്ക് അയച്ച 6-അക്ക OTP കോഡ് നൽകുക",
        "Enter the 6-digit OTP code." to "6-അക്ക OTP കോഡ് നൽകുക.",
        "Enter the 6-digit code sent to your phone." to "നിങ്ങളുടെ ഫോണിലേക്ക് അയച്ച 6-അക്ക കോഡ് നൽകുക.",
        "Error: Please log in again to configure fingerprint." to "പിശക്: വിരലടയാളം ക്രമീകരിക്കാൻ ദയവായി വീണ്ടും ലോഗിൻ ചെയ്യുക.",
        "Estimated Due Date (YYYY-MM-DD)" to "കണക്കാക്കിയ അവസാന തീയതി (YYYY-MM-DD)",
        "Every day" to "എല്ലാ ദിവസവും",
        "Expand" to "വികസിപ്പിക്കുക",
        "Explains your records in simple terms. Not a doctor — always confirm with your physician." to "നിങ്ങളുടെ റെക്കോർഡുകൾ ലളിതമായ ഭാഷയിൽ വിശദീകരിക്കുന്നു. ഡോക്ടർ അല്ല — എപ്പോഴും നിങ്ങളുടെ ഡോക്ടറുമായി സ്ഥിരീകരിക്കുക.",
        "Export" to "എക്സ്പോർട്ട് ചെയ്യുക",
        "Export Backup" to "ബാക്കപ്പ് എക്സ്പോർട്ട് ചെയ്യുക",
        "Export a shareable file of your records (with analysis included) to send to another phone or a doctor. Importing merges it into this phone and never re-runs the AI, so it's free." to "മറ്റൊരു ഫോണിലേക്കോ ഡോക്ടർക്കോ അയക്കാൻ നിങ്ങളുടെ റെക്കോർഡുകളുടെ പങ്കിടാവുന്ന ഫയൽ (വിശകലനം ഉൾപ്പെടെ) എക്സ്പോർട്ട് ചെയ്യുക. ഇംപോർട്ട് ചെയ്യുന്നത് ഇത് ഈ ഫോണിലേക്ക് ലയിപ്പിക്കുന്നു, AI വീണ്ടും പ്രവർത്തിപ്പിക്കില്ല, അതിനാൽ ഇത് സൗജന്യമാണ്.",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restore re-imports a backup file." to "നിങ്ങളുടെ എല്ലാ റെക്കോർഡുകളും (റിപ്പോർട്ടുകൾ + ചിത്രങ്ങൾ) ഒരൊറ്റ ബാക്കപ്പ് ഫയലായി എക്സ്പോർട്ട് ചെയ്യുക. ക്ലൗഡ് പകർപ്പ് സൂക്ഷിക്കാൻ പിക്കറിൽ നിങ്ങളുടെ Google Drive അല്ലെങ്കിൽ OneDrive ഫോൾഡർ തിരഞ്ഞെടുക്കുക. പുനഃസ്ഥാപനം ബാക്കപ്പ് ഫയൽ വീണ്ടും ഇംപോർട്ട് ചെയ്യുന്നു.",
        "F" to "F",
        "Facility:" to "സൗകര്യം:",
        "Failed to connect and read email inbox. Please verify settings." to "ഇമെയിൽ ഇൻബോക്സ് കണക്റ്റ് ചെയ്ത് വായിക്കുന്നതിൽ പരാജയപ്പെട്ടു. ദയവായി ക്രമീകരണങ്ങൾ പരിശോധിക്കുക.",
        "Failed to import selected files." to "തിരഞ്ഞെടുത്ത ഫയലുകൾ ഇംപോർട്ട് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Failed to reset password." to "പാസ്‌വേഡ് പുനഃക്രമീകരിക്കുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Failed to run local OCR." to "പ്രാദേശിക OCR പ്രവർത്തിപ്പിക്കുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Family / Patients" to "കുടുംബം / രോഗികൾ",
