        "Find Care" to "കെയർ കണ്ടെത്തുക",
        "Find Lab Centers" to "ലാബ് സെന്ററുകൾ കണ്ടെത്തുക",
        "Find Labs" to "ലാബുകൾ കണ്ടെത്തുക",
        "Find Nearby" to "സമീപം കണ്ടെത്തുക",
        "Finds reports that were saved more than once (same patient, date, and content) and removes the extra copies. The original of each report is always kept. New scans are checked automatically; this cleans up older duplicates." to "ഒന്നിലധികം തവണ സേവ് ചെയ്ത റിപ്പോർട്ടുകൾ (അതേ രോഗി, തീയതി, ഉള്ളടക്കം) കണ്ടെത്തി അധിക പകർപ്പുകൾ നീക്കം ചെയ്യുന്നു. ഓരോ റിപ്പോർട്ടിന്റെയും യഥാർത്ഥ പകർപ്പ് എപ്പോഴും സൂക്ഷിക്കുന്നു. പുതിയ സ്കാനുകൾ സ്വയമേവ പരിശോധിക്കുന്നു; ഇത് പഴയ ഡ്യൂപ്ലിക്കേറ്റുകൾ വൃത്തിയാക്കുന്നു.",
        "Fingerprint Login" to "വിരലടയാള ലോഗിൻ",
        "Fix / Merge Patient" to "രോഗിയെ ശരിയാക്കുക / ലയിപ്പിക്കുക",
        "Fixing a mis-scanned name updates it in every report, reminder and log for this patient." to "തെറ്റായി സ്കാൻ ചെയ്ത പേര് ശരിയാക്കുന്നത് ഈ രോഗിയുടെ എല്ലാ റിപ്പോർട്ട്, റിമൈൻഡർ, ലോഗിലും അപ്ഡേറ്റ് ചെയ്യും.",
        "Food instruction" to "ഭക്ഷണ നിർദ്ദേശം",
