        "Forgot Password?" to "പാസ്‌വേഡ് മറന്നോ?",
        "Found" to "കണ്ടെത്തി",
        "Frequency String" to "ഫ്രീക്വൻസി സ്ട്രിംഗ്",
        "Frequency/details updated" to "ഫ്രീക്വൻസി/വിശദാംശങ്ങൾ അപ്ഡേറ്റ് ചെയ്തു",
        "From" to "മുതൽ",
        "From device" to "ഉപകരണത്തിൽ നിന്ന്",
        "Full Screen Preview" to "ഫുൾ സ്ക്രീൻ പ്രിവ്യൂ",
        "Full Screen shows a large-text alarm page (even on the lock screen) so medicine names are easy to read. Medicines due at the same time always appear together in one reminder." to "മരുന്നിന്റെ പേരുകൾ എളുപ്പത്തിൽ വായിക്കാൻ ഫുൾ സ്ക്രീൻ ഒരു വലിയ-ടെക്സ്റ്റ് അലാറം പേജ് കാണിക്കുന്നു (ലോക്ക് സ്ക്രീനിലും). ഒരേ സമയത്ത് കഴിക്കേണ്ട മരുന്നുകൾ എപ്പോഴും ഒരു റിമൈൻഡറിൽ ഒരുമിച്ച് കാണിക്കും.",
        "Gemini API Key (AIzaSy...)" to "Gemini API കീ (AIzaSy...)",
        "Generated by AI" to "AI സൃഷ്ടിച്ചത്",
        "Get a short, easy explanation of why" to "എന്തുകൊണ്ടെന്നതിന്റെ ഒരു ചെറിയ, ലളിതമായ വിശദീകരണം നേടുക",
        "Gmail (OAuth)" to "Gmail (OAuth)",
        "Go to Dashboard" to "ഡാഷ്‌ബോർഡിലേക്ക് പോകുക",
        "Google ML Kit Scan Results" to "Google ML Kit സ്കാൻ ഫലങ്ങൾ",
        "Google sign-in failed. Please try again." to "Google സൈൻ-ഇൻ പരാജയപ്പെട്ടു. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
        "Grant permission" to "അനുമതി നൽകുക",
        "Health Decoder Logo" to "ഹെൽത്ത് ഡീകോഡർ ലോഗോ",
        "Health Decoder requires your permission to connect to your email inbox. We will only search for emails from the last 2 days containing potential medical report attachments (PDFs) and extract them locally on your phone. No email contents are sent to our servers. Do you consent to this?" to "നിങ്ങളുടെ ഇമെയിൽ ഇൻബോക്സിലേക്ക് കണക്റ്റ് ചെയ്യാൻ Health Decoder-ന് നിങ്ങളുടെ അനുമതി ആവശ്യമാണ്. കഴിഞ്ഞ 2 ദിവസത്തെ സാധ്യതയുള്ള മെഡിക്കൽ റിപ്പോർട്ട് അറ്റാച്ച്‌മെന്റുകൾ (PDF) ഉള്ള ഇമെയിലുകൾ മാത്രം ഞങ്ങൾ തിരയുകയും അവ നിങ്ങളുടെ ഫോണിൽ പ്രാദേശികമായി വേർതിരിച്ചെടുക്കുകയും ചെയ്യും. ഒരു ഇമെയിൽ ഉള്ളടക്കവും ഞങ്ങളുടെ സെർവറുകളിലേക്ക് അയക്കില്ല. നിങ്ങൾ ഇതിന് സമ്മതിക്കുന്നുണ്ടോ?",
        "Help Fund This App" to "ഈ ആപ്പിന് ധനസഹായം നൽകുക",
        "Home Sample Collection" to "വീട്ടിൽ സാമ്പിൾ ശേഖരണം",
        "Hospital Search Prompt (Optional)" to "ഹോസ്പിറ്റൽ സെർച്ച് പ്രോംപ്റ്റ് (ഓപ്ഷണൽ)",
        "I Consent" to "ഞാൻ സമ്മതിക്കുന്നു",
        "I agree that this app is not a medical device and does not provide clinical advice." to "ഈ ആപ്പ് ഒരു മെഡിക്കൽ ഉപകരണമല്ലെന്നും ക്ലിനിക്കൽ ഉപദേശം നൽകുന്നില്ലെന്നും ഞാൻ സമ്മതിക്കുന്നു.",
        "I explain test results, medicines, and doctor's notes in plain language." to "ടെസ്റ്റ് ഫലങ്ങൾ, മരുന്നുകൾ, ഡോക്ടറുടെ കുറിപ്പുകൾ എന്നിവ ലളിതമായ ഭാഷയിൽ ഞാൻ വിശദീകരിക്കുന്നു.",
        "IMAP Host" to "IMAP ഹോസ്റ്റ്",
        "IMAP Port" to "IMAP പോർട്ട്",
        "IMPORTANT DISCLAIMER" to "പ്രധാന നിരാകരണം",
        "If a name was mis-read on a scan and one person shows up twice, merge the wrong name into the correct one. Moves all their reports, trends, reminders and history together." to "സ്കാനിൽ ഒരു പേര് തെറ്റായി വായിക്കപ്പെട്ട് ഒരു വ്യക്തി രണ്ടുതവണ കാണിക്കുകയാണെങ്കിൽ, തെറ്റായ പേര് ശരിയായ പേരിലേക്ക് ലയിപ്പിക്കുക. ഇത് അവരുടെ എല്ലാ റിപ്പോർട്ടുകൾ, ട്രെൻഡുകൾ, റിമൈൻഡറുകൾ, ചരിത്രം എന്നിവ ഒരുമിച്ച് നീക്കുന്നു.",
        "Import" to "ഇംപോർട്ട് ചെയ്യുക",
        "Importing files..." to "ഫയലുകൾ ഇംപോർട്ട് ചെയ്യുന്നു...",
        "In-depth, plain-language breakdown of this report" to "ഈ റിപ്പോർട്ടിന്റെ ആഴത്തിലുള്ള, ലളിതമായ ഭാഷാ വിശദീകരണം",
        "Incorrect or expired OTP code." to "തെറ്റായതോ കാലഹരണപ്പെട്ടതോ ആയ OTP കോഡ്.",
        "Incorrect or expired code. Please try again." to "തെറ്റായതോ കാലഹരണപ്പെട്ടതോ ആയ കോഡ്. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
        "Indian (mg/dL)" to "ഇന്ത്യൻ (mg/dL)",
        "Insights" to "ഇൻസൈറ്റുകൾ",
        "Instruction" to "നിർദ്ദേശം",
        "International (SI)" to "അന്താരാഷ്ട്ര (SI)",
        "Its alarms will be cancelled. This won't affect the scanned report." to "ഇതിന്റെ അലാറങ്ങൾ റദ്ദാക്കും. ഇത് സ്കാൻ ചെയ്ത റിപ്പോർട്ടിനെ ബാധിക്കില്ല.",
        "Key Notes" to "പ്രധാന കുറിപ്പുകൾ",
        "Key Results" to "പ്രധാന ഫലങ്ങൾ",
        "Lab Units" to "ലാബ് യൂണിറ്റുകൾ",
        "Large Files Selected" to "വലിയ ഫയലുകൾ തിരഞ്ഞെടുത്തു",
