        "Not Now" to "ഇപ്പോൾ വേണ്ട",
        "Not enough comparable data found between the two reports." to "രണ്ട് റിപ്പോർട്ടുകൾക്കുമിടയിൽ വേണ്ടത്ര താരതമ്യപ്പെടുത്താവുന്ന ഡാറ്റ കണ്ടെത്തിയില്ല.",
        "Not now" to "ഇപ്പോൾ വേണ്ട",
        "Not selected" to "തിരഞ്ഞെടുത്തിട്ടില്ല",
        "Note: Gmail, Yahoo, and Outlook require you to generate an 'App Password' from your account security settings to log in via IMAP." to "ശ്രദ്ധിക്കുക: Gmail, Yahoo, Outlook എന്നിവയിൽ IMAP വഴി ലോഗിൻ ചെയ്യാൻ നിങ്ങളുടെ അക്കൗണ്ട് സുരക്ഷാ ക്രമീകരണങ്ങളിൽ നിന്ന് 'ആപ്പ് പാസ്‌വേഡ്' സൃഷ്ടിക്കേണ്ടതുണ്ട്.",
        "Observations / Impressions:" to "നിരീക്ഷണങ്ങൾ / ഇംപ്രഷനുകൾ:",
        "Offline summary (set GEMINI_API_KEY for full AI analysis)" to "ഓഫ്‌ലൈൻ സംഗ്രഹം (പൂർണ്ണ AI വിശകലനത്തിന് GEMINI_API_KEY സജ്ജമാക്കുക)",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "കുറിപ്പടികൾ സ്കാൻ ചെയ്തുകഴിഞ്ഞാൽ, നിങ്ങളുടെ ദിവസേനയുള്ള മരുന്നുകൾ റിമൈൻഡറുകളോടെ ഇവിടെ കാണിക്കും.\n\nഓരോ മരുന്നിനും റിമൈൻഡറുകൾ പ്രവർത്തനക്ഷമമാക്കാൻ താഴെയുള്ള ടോഗിൾ ടാപ്പ് ചെയ്യുക.",
        "One-off" to "ഒറ്റത്തവണ",
        "Ongoing" to "നടന്നുകൊണ്ടിരിക്കുന്നു",
        "Only" to "മാത്രം",
        "Only new since last export" to "അവസാന എക്സ്പോർട്ടിന് ശേഷമുള്ളവ മാത്രം",
        "Open" to "തുറക്കുക",
        "Optional / As Needed" to "ഓപ്ഷണൽ / ആവശ്യാനുസരണം",
        "Or sign in with another method" to "അല്ലെങ്കിൽ മറ്റൊരു രീതിയിൽ സൈൻ ഇൻ ചെയ്യുക",
        "Original file(s)" to "യഥാർത്ഥ ഫയൽ(കൾ)",
        "Other (IMAP)" to "മറ്റുള്ളവ (IMAP)",
        "Overall:" to "മൊത്തത്തിൽ:",
