        "Page limit is" to "പേജ് പരിധി",
        "Parameter" to "പാരാമീറ്റർ",
        "Parameter Changes:" to "പാരാമീറ്റർ മാറ്റങ്ങൾ:",
        "Password must be at least 6 characters." to "പാസ്‌വേഡ് കുറഞ്ഞത് 6 അക്ഷരങ്ങൾ ഉണ്ടായിരിക്കണം.",
        "Password reset successfully. Log in with your new password." to "പാസ്‌വേഡ് വിജയകരമായി പുനഃക്രമീകരിച്ചു. നിങ്ങളുടെ പുതിയ പാസ്‌വേഡ് ഉപയോഗിച്ച് ലോഗിൻ ചെയ്യുക.",
        "Passwords do not match." to "പാസ്‌വേഡുകൾ പൊരുത്തപ്പെടുന്നില്ല.",
        "Permanently removes every report, medicine, pending test and image. This cannot be undone." to "ഓരോ റിപ്പോർട്ട്, മരുന്ന്, തീർച്ചയാകാത്ത ടെസ്റ്റ്, ചിത്രം എന്നിവ ശാശ്വതമായി നീക്കം ചെയ്യുന്നു. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
        "Phone OTP" to "ഫോൺ OTP",
        "Pick a folder in Google Drive, OneDrive, or Dropbox. New backups are automatically synced there by the cloud app." to "Google Drive, OneDrive, അല്ലെങ്കിൽ Dropbox-ൽ ഒരു ഫോൾഡർ തിരഞ്ഞെടുക്കുക. പുതിയ ബാക്കപ്പുകൾ അവിടെ ക്ലൗഡ് ആപ്പ് വഴി സ്വയമേവ സിങ്ക് ചെയ്യപ്പെടും.",
        "Place / Clinic Name" to "സ്ഥലം / ക്ലിനിക് പേര്",
        "Plan:" to "പ്ലാൻ:",
