        "Point camera at a medicine strip to instantly identify it, see usage instructions, and check for interactions." to "മരുന്ന് സ്ട്രിപ്പിൽ ക്യാമറ ചൂണ്ടിക്കാട്ടുക ഉടനടി തിരിച്ചറിയാനും, ഉപയോഗ നിർദ്ദേശങ്ങൾ കാണാനും, ഇടപെടലുകൾ പരിശോധിക്കാനും.",
        "Point the camera at the QR code printed on the report" to "റിപ്പോർട്ടിൽ അച്ചടിച്ച QR കോഡിലേക്ക് ക്യാമറ ചൂണ്ടുക",
