        "Prescribed Medications" to "നിർദ്ദേശിച്ച മരുന്നുകൾ",
        "Prescription" to "കുറിപ്പടി",
        "Prescription Alignment" to "കുറിപ്പടി അലൈൻമെന്റ്",
        "Press 'Scan Report' to upload your first prescription." to "നിങ്ങളുടെ ആദ്യ കുറിപ്പടി അപ്‌ലോഡ് ചെയ്യാൻ 'റിപ്പോർട്ട് സ്കാൻ ചെയ്യുക' അമർത്തുക.",
        "Previous" to "മുമ്പത്തെ",
        "Primary: Shared Key Pool" to "പ്രൈമറി: ഷെയേർഡ് കീ പൂൾ",
        "Proceed Anyway" to "എന്തായാലും തുടരുക",
        "RECENT ACTIVITY & HISTORY" to "സമീപകാല പ്രവർത്തനവും ചരിത്രവും",
        "RECORD INTAKE" to "റെക്കോർഡ് ഇൻടേക്ക്",
        "Raw Text" to "അസംസ്കൃത ടെക്സ്റ്റ്",
        "Raw Transcribed Text" to "അസംസ്കൃത ട്രാൻസ്ക്രൈബ് ചെയ്ത ടെക്സ്റ്റ്",
        "Read aloud" to "ഉച്ചത്തിൽ വായിക്കുക",
        "Read the brief aloud" to "സംഗ്രഹം ഉച്ചത്തിൽ വായിക്കുക",
        "Recommended Specialist(s):" to "ശുപാർശ ചെയ്ത സ്പെഷ്യലിസ്റ്റ്(കൾ):",
