        "Search test name, patient..." to "ടെസ്റ്റ് പേര്, രോഗി തിരയുക...",
        "Searching Unified Health Interface (UHI) registry for real-time open network listings." to "തത്സമയ ഓപ്പൺ നെറ്റ്‌വർക്ക് ലിസ്റ്റിംഗുകൾക്കായി യൂണിഫൈഡ് ഹെൽത്ത് ഇന്റർഫേസ് (UHI) രജിസ്ട്രി തിരയുന്നു.",
