        "Select a Slot first" to "ആദ്യം ഒരു സ്ലോട്ട് തിരഞ്ഞെടുക്കുക",
        "Select reminder slots" to "റിമൈൻഡർ സ്ലോട്ടുകൾ തിരഞ്ഞെടുക്കുക",
        "Select which days the patient should take this medicine:" to "ഈ മരുന്ന് രോഗി ഏത് ദിവസങ്ങളിൽ കഴിക്കണം എന്ന് തിരഞ്ഞെടുക്കുക:",
        "Sends just what changed since last time" to "അവസാന തവണ മുതൽ മാറിയത് മാത്രം അയക്കുന്നു",
        "Server Settings" to "സെർവർ ക്രമീകരണങ്ങൾ",
        "Server address, language, voice, backups" to "സെർവർ വിലാസം, ഭാഷ, ശബ്ദം, ബാക്കപ്പുകൾ",
