        "Side Effects" to "പാർശ്വഫലങ്ങൾ",
        "Sign In" to "സൈൻ ഇൻ ചെയ്യുക",
        "Sign In with Google" to "Google ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക",
        "Sign in quickly using fingerprint" to "വിരലടയാളം ഉപയോഗിച്ച് വേഗത്തിൽ സൈൻ ഇൻ ചെയ്യുക",
        "Signing in gives you your own free daily AI usage allowance, separate from other users of this app." to "സൈൻ ഇൻ ചെയ്യുന്നത് ഈ ആപ്പിലെ മറ്റ് ഉപയോക്താക്കളിൽ നിന്ന് വേറിട്ട് നിങ്ങളുടെ സ്വന്തം സൗജന്യ ദിവസേനയുള്ള AI ഉപയോഗ പരിധി നൽകുന്നു.",
        "Skip & Mark Read" to "ഒഴിവാക്കി വായിച്ചതായി അടയാളപ്പെടുത്തുക",
        "Smart Health Lens" to "സ്മാർട്ട് ഹെൽത്ത് ലെൻസ്",
        "Something went wrong. Check your connection and try again." to "എന്തോ പിഴച്ചു. നിങ്ങളുടെ കണക്ഷൻ പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.",
        "Speak" to "സംസാരിക്കുക",
        "Special Patient Notes" to "പ്രത്യേക രോഗി കുറിപ്പുകൾ",
        "Start Date (YYYY-MM-DD)" to "ആരംഭ തീയതി (YYYY-MM-DD)",
        "Stores the file without using AI — no API calls. You can analyze it anytime from its details." to "AI ഉപയോഗിക്കാതെ ഫയൽ സൂക്ഷിക്കുന്നു — API കോളുകൾ ഇല്ല. അതിന്റെ വിശദാംശങ്ങളിൽ നിന്ന് നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും വിശകലനം ചെയ്യാം.",
        "Successfully initiated booking request for:" to "ഇതിനായി ബുക്കിംഗ് അഭ്യർത്ഥന വിജയകരമായി ആരംഭിച്ചു:",
        "Switch Profile" to "പ്രൊഫൈൽ മാറ്റുക",
        "Sync Now" to "ഇപ്പോൾ സിങ്ക് ചെയ്യുക",
        "System" to "സിസ്റ്റം",
        "T" to "T",
        "Tap Settings → allow exact alarms so reminders arrive at the precise time." to "റിമൈൻഡറുകൾ കൃത്യസമയത്ത് എത്താൻ ക്രമീകരണങ്ങൾ → കൃത്യമായ അലാറങ്ങൾ അനുവദിക്കുക ടാപ്പ് ചെയ്യുക.",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ഡോക്ടർ സന്ദർശനമോ ചെക്കപ്പോ ഷെഡ്യൂൾ ചെയ്യാൻ മുകളിലെ \"അപ്പോയിന്റ്മെന്റ് ചേർക്കുക\" ടാപ്പ് ചെയ്യുക. അത് അടുക്കുന്നതിന് മുമ്പ് നിങ്ങളെ ഓർമ്മിപ്പിക്കും.",
        "Tap a medicine to expand" to "വികസിപ്പിക്കാൻ ഒരു മരുന്നിൽ ടാപ്പ് ചെയ്യുക",
        "Tap any point to open that report" to "ആ റിപ്പോർട്ട് തുറക്കാൻ ഏത് പോയിന്റിലും ടാപ്പ് ചെയ്യുക",
        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "നിങ്ങളുടെ ഉപകരണത്തിൽ നിന്ന് ചിത്രം, PDF അല്ലെങ്കിൽ ഡോക് തിരഞ്ഞെടുക്കാൻ ഇവിടെ ടാപ്പ് ചെയ്യുക, അല്ലെങ്കിൽ ഫോട്ടോ എടുക്കാൻ താഴെയുള്ള ക്യാമറ ഉപയോഗിക്കുക.",
        "Tap play to hear this summary" to "ഈ സംഗ്രഹം കേൾക്കാൻ പ്ലേ ടാപ്പ് ചെയ്യുക",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "മരുന്ന് റിമൈൻഡറുകൾ നിങ്ങളുടെ ഫോണിലും ജോടിയാക്കിയ വാച്ചിലും കാണിക്കാൻ അനുവദിക്കാൻ ടാപ്പ് ചെയ്യുക.",
        "Tap to pick\nImage or PDF" to "തിരഞ്ഞെടുക്കാൻ ടാപ്പ് ചെയ്യുക\nചിത്രം അല്ലെങ്കിൽ PDF",
        "Tap to select" to "തിരഞ്ഞെടുക്കാൻ ടാപ്പ് ചെയ്യുക",
        "Tap to view" to "കാണാൻ ടാപ്പ് ചെയ്യുക",
        "Test Parameter Changes" to "ടെസ്റ്റ് പാരാമീറ്റർ മാറ്റങ്ങൾ",
        "Test group" to "ടെസ്റ്റ് ഗ്രൂപ്പ്",
        "Tested Parameters" to "പരിശോധിച്ച പാരാമീറ്ററുകൾ",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "കുറിപ്പടികളിൽ ശുപാർശ ചെയ്ത ടെസ്റ്റുകൾ സ്വയമേവ ട്രാക്ക് ചെയ്യുന്നു. നിങ്ങൾക്ക് അവ സ്വമേധയാ ചേർക്കാനും കഴിയും.",
        "That QR code doesn't contain a report link." to "ആ QR കോഡിൽ റിപ്പോർട്ട് ലിങ്ക് ഇല്ല.",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "സൗകര്യം 10 മിനിറ്റിനുള്ളിൽ SMS/WhatsApp വഴി നിങ്ങളുടെ സ്ലോട്ട് സ്ഥിരീകരിക്കും.",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "തിരഞ്ഞെടുത്ത ഫയലുകൾ വളരെ വലുതാണ് (%.2f MB). ഈ ഫയലുകൾ പ്രോസസ്സ് ചെയ്യാൻ കൂടുതൽ സമയമെടുക്കും, മെമ്മറി പ്രശ്നങ്ങൾ ഉണ്ടാകാം. ഫയലുകൾ 10 MB-ൽ താഴെ സൂക്ഷിക്കാൻ ഞങ്ങൾ ശുപാർശ ചെയ്യുന്നു. എന്തായാലും തുടരണോ?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "ഇത് യഥാർത്ഥമല്ല. ഇത് നീക്കം ചെയ്യുക, അല്ലെങ്കിൽ നിങ്ങളുടെ സ്വന്തം റെക്കോർഡുകൾ ട്രാക്ക് ചെയ്യാൻ തുടങ്ങാൻ സൈൻ ഇൻ ചെയ്യുക.",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "ഇത് എല്ലാ റിപ്പോർട്ടുകൾ, മരുന്നുകൾ, തീർച്ചയാകാത്ത ടെസ്റ്റുകൾ, ചിത്രങ്ങൾ എന്നിവ ശാശ്വതമായി ഇല്ലാതാക്കുന്നു. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "ഇത് യഥാർത്ഥ സ്കാൻ ചെയ്ത ചിത്രത്തിൽ AI വിശകലനം വീണ്ടും പ്രവർത്തിപ്പിച്ച് താഴെയുള്ള വേർതിരിച്ചെടുത്ത ടെസ്റ്റ് മൂല്യങ്ങൾ, മരുന്നുകൾ, ഇൻസൈറ്റുകൾ എന്നിവ പുതുക്കുന്നു. മുൻ സ്കാൻ അപൂർണ്ണമായി വന്നിരുന്നെങ്കിൽ (ഉദാ. API അല്പസമയം ലഭ്യമല്ലായിരുന്നു) ഇത് ഉപകാരപ്രദമാണ്. ഇത് നിങ്ങളുടെ കുറച്ച് API ക്വോട്ട ഉപയോഗിച്ചേക്കാം.",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "ഈ റിപ്പോർട്ടിന്റെ ഫയൽ സേവ് ചെയ്തിട്ടുണ്ട് പക്ഷേ AI വഴി വിശകലനം ചെയ്തിട്ടില്ല, അതിനാൽ ഇതിന് ഇതുവരെ ടെസ്റ്റ് മൂല്യങ്ങളോ ട്രെൻഡുകളോ ഇൻസൈറ്റുകളോ ഇല്ല. നിങ്ങൾ തയ്യാറാകുമ്പോൾ ഇത് വിശകലനം ചെയ്യുക (കുറച്ച് API ക്വോട്ട ഉപയോഗിക്കുന്നു).",
        "Time (HH:MM)" to "സമയം (HH:MM)",
        "Tip: 1-0-1 = morning & night, 1-1-1 = three times a day." to "നുറുങ്ങ്: 1-0-1 = രാവിലെയും രാത്രിയും, 1-1-1 = ദിവസത്തിൽ മൂന്ന് തവണ.",
        "Tips" to "നുറുങ്ങുകൾ",
        "To" to "ലേക്ക്",
