        "You haven't linked an email account yet. Please go to Settings (Account tab) to link your Gmail account or IMAP details first." to "നിങ്ങൾ ഇതുവരെ ഇമെയിൽ അക്കൗണ്ട് ലിങ്ക് ചെയ്തിട്ടില്ല. നിങ്ങളുടെ Gmail അക്കൗണ്ട് അല്ലെങ്കിൽ IMAP വിശദാംശങ്ങൾ ആദ്യം ലിങ്ക് ചെയ്യാൻ ക്രമീകരണങ്ങളിലേക്ക് (അക്കൗണ്ട് ടാബ്) പോകുക.",
        "You're using Health Decoder without an account" to "നിങ്ങൾ അക്കൗണ്ട് ഇല്ലാതെ Health Decoder ഉപയോഗിക്കുന്നു",
