        "🎙️ Ask AI" to "🎙️ AI-യോട് ചോദിക്കുക",
        "👨‍👩‍👧 Everyone" to "👨‍👩‍👧 എല്ലാവരും",
        "📸 Identify" to "📸 തിരിച്ചറിയുക",
        "🧪 You're viewing sample demo data" to "🧪 നിങ്ങൾ സാമ്പിൾ ഡെമോ ഡാറ്റ കാണുന്നു",
        "Medication Reminders" to "മരുന്ന് റിമൈൻഡറുകൾ",
        "Find Doctors" to "ഡോക്ടർമാരെ കണ്ടെത്തുക",
        "Find Hospitals" to "ആശുപത്രികൾ കണ്ടെത്തുക",
        "Doctor Brief" to "ഡോക്ടർ സംഗ്രഹം",
        "Scan any medical report" to "ഏതെങ്കിലും മെഡിക്കൽ റിപ്പോർട്ട് സ്കാൻ ചെയ്യുക",
        "Turn paper lab reports, prescriptions and discharge summaries into organized, searchable digital records — right from your phone's camera." to "പേപ്പർ ലാബ് റിപ്പോർട്ടുകൾ, കുറിപ്പടികൾ, ഡിസ്ചാർജ് സംഗ്രഹങ്ങൾ എന്നിവ ചിട്ടയായ, തിരയാവുന്ന ഡിജിറ്റൽ റെക്കോർഡുകളാക്കി മാറ്റുക — നിങ്ങളുടെ ഫോൺ ക്യാമറയിൽ നിന്ന് നേരിട്ട്.",
        "Understand it instantly" to "ഇത് ഉടനടി മനസ്സിലാക്കുക",
        "AI reads every test value, medicine and date on the page, so you see what a report actually means without hunting through medical jargon." to "AI പേജിലെ ഓരോ ടെസ്റ്റ് മൂല്യവും, മരുന്നും, തീയതിയും വായിക്കുന്നു, അതിനാൽ മെഡിക്കൽ പദപ്രയോഗങ്ങളിൽ കുടുങ്ങാതെ റിപ്പോർട്ട് യഥാർത്ഥത്തിൽ എന്താണ് അർത്ഥമാക്കുന്നതെന്ന് നിങ്ങൾക്ക് കാണാം.",
        "Never miss a dose or a follow-up" to "ഒരു ഡോസോ ഫോളോ-അപ്പോ ഒരിക്കലും നഷ്ടപ്പെടുത്തരുത്",
        "Medicine reminders fire at the right time every day — even for a twice-a-week medicine — and doctor appointments get their own reminder too." to "മരുന്ന് റിമൈൻഡറുകൾ എല്ലാ ദിവസവും കൃത്യസമയത്ത് മുഴങ്ങുന്നു — ആഴ്ചയിൽ രണ്ടുതവണ കഴിക്കുന്ന മരുന്നിനും പോലും — ഡോക്ടർ അപ്പോയിന്റ്മെന്റുകൾക്കും അവയുടേതായ റിമൈൻഡർ ലഭിക്കും.",
        "What do my latest test results mean?" to "എന്റെ ഏറ്റവും പുതിയ ടെസ്റ്റ് ഫലങ്ങളുടെ അർത്ഥമെന്ത്?",
        "Explain my current medicines in simple words" to "എന്റെ നിലവിലെ മരുന്നുകൾ ലളിതമായ വാക്കുകളിൽ വിശദീകരിക്കുക",
        "Are any of my values abnormal?" to "എന്റെ മൂല്യങ്ങളിൽ എന്തെങ്കിലും അസാധാരണമാണോ?",
        "What should I ask my doctor next?" to "അടുത്തതായി ഞാൻ എന്റെ ഡോക്ടറോട് എന്ത് ചോദിക്കണം?",
        "Rx" to "Rx",
        "Hospitals" to "ആശുപത്രികൾ",
        "Lab Tests" to "ലാബ് ടെസ്റ്റുകൾ",
        "Doctors" to "ഡോക്ടർമാർ",
        "Broadcasting search to UHI gateway..." to "UHI ഗേറ്റ്‌വേയിലേക്ക് തിരയൽ പ്രക്ഷേപണം ചെയ്യുന്നു...",
        "Gateway ACK received. Listening for provider webhook responses..." to "ഗേറ്റ്‌വേ ACK ലഭിച്ചു. ദാതാവിന്റെ വെബ്‌ഹുക്ക് പ്രതികരണങ്ങൾക്കായി കേൾക്കുന്നു...",
        "Listening for provider webhooks... (Incoming responses)" to "ദാതാവിന്റെ വെബ്‌ഹുക്കുകൾക്കായി കേൾക്കുന്നു... (വരുന്ന പ്രതികരണങ്ങൾ)",
        "3M" to "3 മാസം",
        "6M" to "6 മാസം",
        "1Y" to "1 വർഷം",
        "2Y" to "2 വർഷം",
        "10 km" to "10 കിമീ",
        "20 km" to "20 കിമീ",
        "50 km" to "50 കിമീ",
        "Any" to "ഏതെങ്കിലും",
        "Couldn't load your account. Check your connection and try again." to "നിങ്ങളുടെ അക്കൗണ്ട് ലോഡ് ചെയ്യാനായില്ല. നിങ്ങളുടെ കണക്ഷൻ പരിശോധിച്ച് വീണ്ടും ശ്രമിക്കുക.",
        "Please enter a valid API key or tap 'Revert to Shared Pool'." to "ദയവായി സാധുവായ API കീ നൽകുക അല്ലെങ്കിൽ 'ഷെയേർഡ് പൂളിലേക്ക് മടങ്ങുക' ടാപ്പ് ചെയ്യുക.",
        "Personal API Key saved! Switched to Individual Key mode." to "വ്യക്തിഗത API കീ സേവ് ചെയ്തു! വ്യക്തിഗത കീ മോഡിലേക്ക് മാറി.",
        "Reverted to Primary Shared Key Pool." to "പ്രൈമറി ഷെയേർഡ് കീ പൂളിലേക്ക് മടങ്ങി.",
        "All fields are required." to "എല്ലാ ഫീൽഡുകളും ആവശ്യമാണ്.",
        "New password must be at least 6 characters." to "പുതിയ പാസ്‌വേഡ് കുറഞ്ഞത് 6 അക്ഷരങ്ങൾ ഉണ്ടായിരിക്കണം.",
        "Password updated successfully." to "പാസ്‌വേഡ് വിജയകരമായി അപ്ഡേറ്റ് ചെയ്തു.",
        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "അസിസ്റ്റന്റിനെ ബന്ധപ്പെടാനായില്ല. സെർവർ പ്രവർത്തിക്കുന്നുണ്ടെന്നും ക്രമീകരണങ്ങളിൽ കോൺഫിഗർ ചെയ്തിട്ടുണ്ടെന്നും പരിശോധിക്കുക.",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "ഈ ഉപകരണത്തിൽ വോയ്‌സ് ഇൻപുട്ട് ലഭ്യമല്ല. ദയവായി Google വോയ്‌സ് ടൈപ്പിംഗ് ഇൻസ്റ്റാൾ/പ്രവർത്തനക്ഷമമാക്കുക.",
        "Couldn't generate the detailed analysis. Please try again." to "വിശദമായ വിശകലനം സൃഷ്ടിക്കാനായില്ല. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
        "Search failed. Make sure the backend server is running and database is migrated." to "തിരയൽ പരാജയപ്പെട്ടു. ബാക്ക്എൻഡ് സെർവർ പ്രവർത്തിക്കുന്നുണ്ടെന്നും ഡാറ്റാബേസ് മൈഗ്രേറ്റ് ചെയ്തിട്ടുണ്ടെന്നും ഉറപ്പാക്കുക.",
        "Failed to fetch medications. Make sure your local server is running and configured correctly in settings." to "മരുന്നുകൾ ലഭ്യമാക്കുന്നതിൽ പരാജയപ്പെട്ടു. നിങ്ങളുടെ ലോക്കൽ സെർവർ പ്രവർത്തിക്കുന്നുണ്ടെന്നും ക്രമീകരണങ്ങളിൽ ശരിയായി കോൺഫിഗർ ചെയ്തിട്ടുണ്ടെന്നും ഉറപ്പാക്കുക.",
        "Failed to delete the selected medicines." to "തിരഞ്ഞെടുത്ത മരുന്നുകൾ ഇല്ലാതാക്കുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Failed to update the selected medicines." to "തിരഞ്ഞെടുത്ത മരുന്നുകൾ അപ്ഡേറ്റ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Failed to fetch pending tests. Make sure your local server is running and configured correctly in settings." to "തീർച്ചയാകാത്ത ടെസ്റ്റുകൾ ലഭ്യമാക്കുന്നതിൽ പരാജയപ്പെട്ടു. നിങ്ങളുടെ ലോക്കൽ സെർവർ പ്രവർത്തിക്കുന്നുണ്ടെന്നും ക്രമീകരണങ്ങളിൽ ശരിയായി കോൺഫിഗർ ചെയ്തിട്ടുണ്ടെന്നും ഉറപ്പാക്കുക.",
        "Failed to delete test reminder." to "ടെസ്റ്റ് റിമൈൻഡർ ഇല്ലാതാക്കുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Patient and Test names are required." to "രോഗിയുടെയും ടെസ്റ്റിന്റെയും പേരുകൾ ആവശ്യമാണ്.",
        "Failed to save test reminder." to "ടെസ്റ്റ് റിമൈൻഡർ സേവ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "റെക്കോർഡുകൾ ലഭ്യമാക്കുന്നതിൽ പരാജയപ്പെട്ടു. നിങ്ങളുടെ ലോക്കൽ സെർവർ പ്രവർത്തിക്കുന്നുണ്ടെന്നും ക്രമീകരണങ്ങളിൽ ശരിയായി കോൺഫിഗർ ചെയ്തിട്ടുണ്ടെന്നും ഉറപ്പാക്കുക.",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "റിമൈൻഡറുകൾ ലഭ്യമാക്കുന്നതിൽ പരാജയപ്പെട്ടു. നിങ്ങളുടെ ലോക്കൽ സെർവർ പ്രവർത്തിക്കുന്നുണ്ടെന്നും ക്രമീകരണങ്ങളിൽ ശരിയായി കോൺഫിഗർ ചെയ്തിട്ടുണ്ടെന്നും ഉറപ്പാക്കുക.",
        "Couldn't save the file." to "ഫയൽ സേവ് ചെയ്യാനായില്ല.",
        "No app available to open this file type." to "ഈ ഫയൽ തരം തുറക്കാൻ ആപ്പ് ലഭ്യമല്ല.",
        "Couldn't share this file." to "ഈ ഫയൽ പങ്കിടാനായില്ല.",
        "Report not found." to "റിപ്പോർട്ട് കണ്ടെത്തിയില്ല.",
        "Failed to load report details." to "റിപ്പോർട്ട് വിശദാംശങ്ങൾ ലോഡ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Failed to save edits. Check network settings." to "എഡിറ്റുകൾ സേവ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു. നെറ്റ്‌വർക്ക് ക്രമീകരണങ്ങൾ പരിശോധിക്കുക.",
        "Failed to delete report." to "റിപ്പോർട്ട് ഇല്ലാതാക്കുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Couldn't reprocess: report or its scanned image is missing." to "വീണ്ടും പ്രോസസ്സ് ചെയ്യാനായില്ല: റിപ്പോർട്ട് അല്ലെങ്കിൽ അതിന്റെ സ്കാൻ ചെയ്ത ചിത്രം കാണുന്നില്ല.",
        "Failed to reprocess this report." to "ഈ റിപ്പോർട്ട് വീണ്ടും പ്രോസസ്സ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു.",
        "Medicine name is required." to "മരുന്നിന്റെ പേര് ആവശ്യമാണ്.",
        "Select at least one reminder slot." to "കുറഞ്ഞത് ഒരു റിമൈൻഡർ സ്ലോട്ട് തിരഞ്ഞെടുക്കുക.",
        "Doctor name is required." to "ഡോക്ടറുടെ പേര് ആവശ്യമാണ്.",
        "Place is required." to "സ്ഥലം ആവശ്യമാണ്.",
        "Date is required." to "തീയതി ആവശ്യമാണ്.",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "ഈ ഉപകരണത്തിന്റെ സുരക്ഷിത ഹാർഡ്‌വെയർ സംഭരണം ലഭ്യമല്ല, അതിനാൽ നിങ്ങളുടെ ലോക്കൽ റെക്കോർഡുകൾ കീയും ലിങ്ക് ചെയ്ത-ഇമെയിൽ ക്രെഡൻഷ്യലുകളും ഹാർഡ്‌വെയർ-പിന്തുണയുള്ള എൻക്രിപ്ഷൻ ഇല്ലാതെ സൂക്ഷിക്കുന്നു. നിങ്ങളുടെ ഡാറ്റ ഇപ്പോഴും അരക്ഷിതമായി എവിടെയും അയക്കുന്നില്ല, പക്ഷേ ഈ ഉപകരണം സാധാരണയേക്കാൾ ദുർബലമായ സംരക്ഷണം നൽകുന്നു.",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "സ്കാനിംഗ്, റിമൈൻഡറുകൾ, മറ്റെല്ലാം ഈ ഉപകരണത്തിൽ സൈൻ ഇൻ ചെയ്യാതെ പൂർണ്ണമായി പ്രവർത്തിക്കുന്നു. സൈൻ ഇൻ ഓപ്ഷണലാണ് (ഇത് SMS കോഡ് അയക്കുന്നു, അതിനാൽ ഇത് സ്വയമേവ അല്ല) — ഉപകരണങ്ങളിലുടനീളം നിങ്ങളോടൊപ്പം വരുന്ന പ്രൊഫൈൽ അല്ലെങ്കിൽ വ്യക്തിഗത API കീ വേണമെങ്കിൽ ഇത് ഉപയോഗിക്കുക.",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "ഓരോ ട്രെൻഡ് ചാർട്ടും റീഡിംഗുകൾ സ്റ്റാൻഡേർഡ് ചെയ്യുന്ന യൂണിറ്റ്. വ്യത്യസ്ത യൂണിറ്റിലുള്ള റിപ്പോർട്ടുകൾ സ്വയമേവ പരിവർത്തനം ചെയ്യപ്പെടും; ഓരോ റിപ്പോർട്ടും ഇപ്പോഴും അതിന്റെ യഥാർത്ഥ മൂല്യം കാണിക്കും.",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "എന്തുകൊണ്ട്: Health Decoder ചെലവുകൾ കുറച്ചു നിർത്തി സൗജന്യമായി തുടരുന്നു, നിങ്ങളുടെ റെക്കോർഡുകൾ വിറ്റല്ല. നിങ്ങൾ ഇവിടെ ചേർന്നാൽ, നിങ്ങളുടെ പ്രായവും ലിംഗവും മാത്രം — നിങ്ങളുടെ പേരോ റിപ്പോർട്ടുകളോ കൃത്യമായ സ്ഥലമോ ഒരിക്കലുമില്ല — മെഡിക്കൽ ഗവേഷണ സ്ഥാപനങ്ങളുമായി മൊത്തത്തിൽ പങ്കിടും, പരസ്യങ്ങൾ പ്രവർത്തിപ്പിക്കുന്നതിനോ സബ്സ്ക്രിപ്ഷൻ ഈടാക്കുന്നതിനോ പകരം ആപ്പ് എല്ലാ കുടുംബത്തിനും സൗജന്യമായി നിലനിർത്താൻ സഹായിക്കാൻ.",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "ഈ പ്രോഗ്രാം ഇതുവരെ ആരംഭിച്ചിട്ടില്ല — ഇന്ന് ഇത് ഓണാക്കുന്നത് നിങ്ങളുടെ മുൻഗണന മാത്രം സേവ് ചെയ്യുന്നു. യഥാർത്ഥ ഡാറ്റ-പങ്കിടൽ പൈപ്പ്‌ലൈൻ നിലവിൽ വരുന്നതുവരെ ഒന്നും എവിടെയും അയക്കില്ല, നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും ഇവിടെ നിങ്ങളുടെ ഉത്തരം മാറ്റാം.",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "ഇത് നിങ്ങളുടെ Health Decoder അക്കൗണ്ടും ഈ ഉപകരണത്തിൽ സൂക്ഷിച്ചിരിക്കുന്ന എല്ലാ മെഡിക്കൽ റെക്കോർഡുകളും — റിപ്പോർട്ടുകൾ, റിമൈൻഡറുകൾ, അപ്പോയിന്റ്മെന്റുകൾ, കുടുംബ പ്രൊഫൈലുകൾ — ശാശ്വതമായി ഇല്ലാതാക്കുന്നു. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "നിർദ്ദേശിക്കുന്നു, കൂടെ പ്രധാന നുറുങ്ങുകളും. ആദ്യ തിരയൽ ഇന്റർനെറ്റ് ഉപയോഗിക്കുന്നു, പിന്നീട് അത് സേവ് ചെയ്യുന്നു അതിനാൽ അടുത്ത തവണ ഉടനടി തുറക്കും.",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "ഉദാഹരണ റിപ്പോർട്ടുകൾ, റിമൈൻഡറുകൾ, ഇതിനകം പൂരിപ്പിച്ച അപ്പോയിന്റ്മെന്റ് എന്നിവയോടെ, അതിനാൽ യഥാർത്ഥമായത് സ്കാൻ ചെയ്യുന്നതിന് മുമ്പ് നിങ്ങൾക്ക് എല്ലാ സ്ക്രീനും പര്യവേക്ഷണം ചെയ്യാം. അക്കൗണ്ടിൽ നിന്ന് എപ്പോൾ വേണമെങ്കിലും ഇത് നീക്കം ചെയ്യുക.",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ആ QR ഒരു വെബ് പേജ് തുറന്നു, നേരിട്ടുള്ള ഫയൽ അല്ല. ഇത് നിങ്ങളുടെ ബ്രൗസറിൽ തുറക്കുന്നു — അവിടെ റിപ്പോർട്ട് ഡൗൺലോഡ് ചെയ്യുക, പിന്നീട് അത് ഇംപോർട്ട് ചെയ്യാൻ \"ഉപകരണത്തിൽ നിന്ന്\" ഉപയോഗിക്കുക.",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "വലിയ രേഖകൾ വിശകലനത്തിനായി വിഭജിക്കുന്ന രീതി പരിഹരിക്കുന്നതിന് മുമ്പ് %1\$d മൾട്ടി-പേജ് സ്കാനുകൾ പ്രോസസ് ചെയ്യപ്പെട്ടിരുന്നു — അതേ രേഖയിലെ ഒരു പാനൽ (ഉദാ. ഇലക്ട്രോലൈറ്റുകൾ അല്ലെങ്കിൽ PT/INR പേജ്) വിട്ടുപോയിരിക്കാം. ഇത് ഇതിനകം സേവ് ചെയ്ത പേജുകൾ ഉപയോഗിച്ച് വീണ്ടും പരിശോധിച്ച് വിട്ടുപോയത് ചേർക്കുന്നു; ഇതിനകം സേവ് ചെയ്തത് അതേപടി തുടരും.",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "AI വിശകലന സെർവർ ലഭ്യമല്ലാതിരുന്ന സമയത്ത് %1\$d റിപ്പോർട്ട്(കൾ) സേവ് ചെയ്യപ്പെട്ടു (ഉദാ. ദൈനംദിന ക്വോട്ട തീർന്നു), അതിനാൽ അവയുടെ തീയതിയും വിഭാഗവും രേഖയിൽ നിന്ന് വായിച്ചതല്ല, ഊഹമാണ്. വീണ്ടും വിശകലനം ഇതിനകം സൂക്ഷിച്ച ചിത്രങ്ങൾ ഉപയോഗിക്കുന്നു — നിങ്ങൾ വീണ്ടും സ്കാൻ ചെയ്യേണ്ടതില്ല.",
        "Add, edit, or remove people this device tracks — including yourself" to "ഈ ഉപകരണം ട്രാക്ക് ചെയ്യുന്ന ആളുകളെ ചേർക്കുക, തിരുത്തുക അല്ലെങ്കിൽ നീക്കുക — നിങ്ങളെയും ഉൾപ്പെടെ",
        "Also protect automatic backups with a password" to "സ്വയമേവയുള്ള ബാക്കപ്പുകളും പാസ്‌വേഡ് ഉപയോഗിച്ച് സംരക്ഷിക്കുക",
        "Auto-backup password" to "സ്വയം-ബാക്കപ്പ് പാസ്‌വേഡ്",
        "Backup password" to "ബാക്കപ്പ് പാസ്‌വേഡ്",
        "Based on your %1\$s result (%2\$s) from your report dated %3\$s." to "%3\$s തീയതിയിലെ നിങ്ങളുടെ റിപ്പോർട്ടിലെ %1\$s ഫലത്തെ (%2\$s) അടിസ്ഥാനമാക്കി.",
        "Blood" to "രക്തം",
        "Brief" to "സംഗ്രഹം",
        "Chat" to "ചാറ്റ്",
        "Check Now (%1\$d)" to "ഇപ്പോൾ പരിശോധിക്കുക (%1\$d)",
        "Check for Missing Report Data" to "നഷ്ടപ്പെട്ട റിപ്പോർട്ട് ഡാറ്റ പരിശോധിക്കുക",
        "Checking %1\$d of %2\$d…" to "%2\$d-ൽ %1\$d പരിശോധിക്കുന്നു…",
        "Compare" to "താരതമ്യം",
        "Confirm password" to "പാസ്‌വേഡ് സ്ഥിരീകരിക്കുക",
        "Data Management" to "ഡാറ്റ മാനേജ്‌മെന്റ്",
        "Date of Birth (YYYY-MM-DD)" to "ജനന തീയതി (YYYY-MM-DD)",
        "Discharge Summary" to "ഡിസ്ചാർജ് സംഗ്രഹം",
        "Discharge Summary + Prescription" to "ഡിസ്ചാർജ് സംഗ്രഹം + കുറിപ്പടി",
        "Echo" to "എക്കോ",
        "Edit Profile" to "പ്രൊഫൈൽ തിരുത്തുക",
        "Edit profile" to "പ്രൊഫൈൽ തിരുത്തുക",
        "Ends" to "അവസാനം",
        "Enter Backup Password" to "ബാക്കപ്പ് പാസ്‌വേഡ് നൽകുക",
        "Every" to "ഓരോ",
        "Export all your records (reports + images) as a single backup file. Choose your Google Drive or OneDrive folder in the picker to keep a cloud copy. Restoring REPLACES everything currently on this device." to "നിങ്ങളുടെ എല്ലാ രേഖകളും (റിപ്പോർട്ടുകൾ + ചിത്രങ്ങൾ) ഒറ്റ ബാക്കപ്പ് ഫയലായി കയറ്റുമതി ചെയ്യുക. ക്ലൗഡ് പകർപ്പ് സൂക്ഷിക്കാൻ പിക്കറിൽ നിങ്ങളുടെ Google Drive അല്ലെങ്കിൽ OneDrive ഫോൾഡർ തിരഞ്ഞെടുക്കുക. പുനഃസ്ഥാപിച്ചാൽ ഈ ഉപകരണത്തിലുള്ളതെല്ലാം മാറ്റപ്പെടും.",
        "Family Members" to "കുടുംബാംഗങ്ങൾ",
        "First Name" to "ആദ്യ പേര്",
        "Free Gemini API Key (Optional)" to "സൗജന്യ Gemini API കീ (ഓപ്ഷണൽ)",
        "Full Backup & Restore" to "പൂർണ്ണ ബാക്കപ്പും പുനഃസ്ഥാപനവും",
        "General lifestyle suggestion, not medical advice — talk to your doctor before making changes based on a lab result." to "പൊതുവായ ജീവിതശൈലി നിർദ്ദേശം, വൈദ്യോപദേശമല്ല — ലാബ് ഫലത്തിന്റെ അടിസ്ഥാനത്തിൽ മാറ്റങ്ങൾ വരുത്തുന്നതിന് മുമ്പ് നിങ്ങളുടെ ഡോക്ടറോട് സംസാരിക്കുക.",
        "Get Free API Key" to "സൗജന്യ API കീ നേടുക",
        "Got it" to "മനസ്സിലായി",
        "HEALTH TIP" to "ആരോഗ്യ ടിപ്പ്",
        "Health Decoder" to "ഹെൽത്ത് ഡീകോഡർ",
        "Hello," to "നമസ്കാരം,",
        "High" to "ഉയർന്നത്",
        "Home" to "ഹോം",
        "Last Name" to "അവസാന പേര്",
        "Learn More" to "കൂടുതൽ അറിയുക",
        "Leave blank to keep the current one" to "നിലവിലുള്ളത് തന്നെ നിലനിർത്താൻ ശൂന്യമാക്കിയിടുക",
        "Live camera scan — point and get instant answers" to "ലൈവ് ക്യാമറ സ്കാൻ — ക്യാമറ ചൂണ്ടി ഉടൻ ഉത്തരങ്ങൾ നേടുക",
        "Low" to "കുറവ്",
        "Medical Report" to "മെഡിക്കൽ റിപ്പോർട്ട്",
        "Not set" to "സജ്ജമാക്കിയിട്ടില്ല",
        "Not signed in" to "സൈൻ ഇൻ ചെയ്തിട്ടില്ല",
        "Off by default — these sync to your cloud folder above without a password unless you set one here" to "സ്ഥിരസ്ഥിതിയായി ഓഫ് — നിങ്ങൾ ഇവിടെ ഒന്ന് സജ്ജമാക്കുന്നത് വരെ ഇവ മുകളിലെ നിങ്ങളുടെ ക്ലൗഡ് ഫോൾഡറിലേക്ക് പാസ്‌വേഡ് ഇല്ലാതെ സിങ്ക് ചെയ്യും",
        "Once prescriptions are scanned, your daily medicines will appear here with reminders.\n\nTap a toggle below to enable reminders for each medicine." to "കുറിപ്പടികൾ സ്കാൻ ചെയ്തുകഴിഞ്ഞാൽ, നിങ്ങളുടെ ദൈനംദിന മരുന്നുകൾ ഓർമ്മപ്പെടുത്തലുകളോടെ ഇവിടെ കാണാം.\n\nഓരോ മരുന്നിനും ഓർമ്മപ്പെടുത്തൽ പ്രവർത്തനക്ഷമമാക്കാൻ താഴെയുള്ള ടോഗിൾ അമർത്തുക.",
        "Optional — keeps your data available across devices" to "ഓപ്ഷണൽ — നിങ്ങളുടെ ഡാറ്റ എല്ലാ ഉപകരണങ്ങളിലും ലഭ്യമാക്കുന്നു",
        "Optional — leave blank to use the shared pool" to "ഓപ്ഷണൽ — പങ്കിട്ട പൂൾ ഉപയോഗിക്കാൻ ശൂന്യമാക്കിയിടുക",
        "PERSONALIZED FOR YOU" to "നിങ്ങൾക്കായി പ്രത്യേകം",
        "Passwords don't match" to "പാസ്‌വേഡുകൾ യോജിക്കുന്നില്ല",
        "Profile" to "പ്രൊഫൈൽ",
        "Protect this backup with a password" to "ഈ ബാക്കപ്പ് പാസ്‌വേഡ് ഉപയോഗിച്ച് സംരക്ഷിക്കുക",
        "Re-analyze All (%1\$d)" to "എല്ലാം വീണ്ടും വിശകലനം ചെയ്യുക (%1\$d)",
        "Re-analyzing %1\$d of %2\$d…" to "%2\$d-ൽ %1\$d വീണ്ടും വിശകലനം ചെയ്യുന്നു…",
        "Reports Needing Re-check" to "വീണ്ടും പരിശോധിക്കേണ്ട റിപ്പോർട്ടുകൾ",
        "Restoring…" to "പുനഃസ്ഥാപിക്കുന്നു…",
        "Select gender" to "ലിംഗം തിരഞ്ഞെടുക്കുക",
        "Share / Merge Records" to "രേഖകൾ പങ്കിടുക / ലയിപ്പിക്കുക",
        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "പങ്കിടുക / ലയിപ്പിക്കുക തിരഞ്ഞെടുത്തവ മറ്റൊരു ഫോണിലേക്കോ ഡോക്ടർക്കോ അയച്ച് അവിടെയുള്ളതിനോട് ചേർക്കുന്നു. ബാക്കപ്പും പുനഃസ്ഥാപനവും ഈ ഉപകരണത്തിന്റെ പൂർണ്ണ സ്നാപ്‌ഷോട്ടാണ് — പുനഃസ്ഥാപിക്കുമ്പോൾ എല്ലാം മാറ്റുന്നു, അതിനാൽ അത് പങ്കിടലിനല്ല, ദുരന്ത വീണ്ടെടുക്കലിനായി ഉപയോഗിക്കുക.",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "നിങ്ങളുടെ പേരും വിശദാംശങ്ങളും തിരുത്താനും, വ്യക്തിഗത API കീ ഉപയോഗിക്കാനും, വിരലടയാള ലോഗിൻ പ്രവർത്തനക്ഷമമാക്കാനും സൈൻ ഇൻ ചെയ്യുക. അതില്ലാതെയും ആപ്പ് പൂർണ്ണമായി പ്രവർത്തിക്കുന്നു — നിങ്ങളുടെ കുടുംബാംഗങ്ങളും രേഖകളും ഇതിനകം ഈ ഉപകരണത്തിൽ തന്നെയുണ്ട്.",
        "Sign in to sync your records" to "നിങ്ങളുടെ രേഖകൾ സിങ്ക് ചെയ്യാൻ സൈൻ ഇൻ ചെയ്യുക",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "ഇത് ഒഴിവാക്കിയാൽ ആപ്പ് സ്ഥിരസ്ഥിതിയായി പങ്കിട്ട സൗജന്യ പൂൾ ഉപയോഗിക്കുന്നു. സ്വന്തം കീ മുൻകൂട്ടി ചേർത്താൽ ആ പൂളിന്റെ ദൈനംദിന പരിധി നിങ്ങളെ ഒരിക്കലും തടയില്ല.",
        "Sono" to "സോണോ",
        "Starts" to "ആരംഭം",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ഡോക്ടറെ കാണാനോ പരിശോധനയ്ക്കോ സമയം നിശ്ചയിക്കാൻ മുകളിലുള്ള \"അപ്പോയിന്റ്മെന്റ് ചേർക്കുക\" അമർത്തുക. സമയത്തിന് മുമ്പ് നിങ്ങളെ ഓർമ്മിപ്പിക്കും.",
        "Tap to pick\nImage or PDF" to "തിരഞ്ഞെടുക്കാൻ അമർത്തുക\nചിത്രം അല്ലെങ്കിൽ PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ആ QR ഒരു വെബ് പേജ് തുറന്നു, നേരിട്ടുള്ള ഫയലല്ല. അത് നിങ്ങളുടെ ബ്രൗസറിൽ തുറക്കുന്നു — അവിടെ റിപ്പോർട്ട് ഡൗൺലോഡ് ചെയ്ത്, പിന്നീട് അത് ഇറക്കുമതി ചെയ്യാൻ \"ഉപകരണത്തിൽ നിന്ന്\" ഉപയോഗിക്കുക.",
        "There's no way to reset this if you forget it — write it down somewhere safe." to "മറന്നാൽ ഇത് പുനഃസജ്ജമാക്കാൻ ഒരു വഴിയുമില്ല — ഇത് എവിടെയെങ്കിലും സുരക്ഷിതമായി എഴുതിവയ്ക്കുക.",
        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "മറന്നാൽ ഇത് പുനഃസജ്ജമാക്കാൻ ഒരു വഴിയുമില്ല — ഇത് എവിടെയെങ്കിലും സുരക്ഷിതമായി എഴുതിവയ്ക്കുക. ബാക്കപ്പ് പാസ്‌വേഡ് നഷ്ടപ്പെട്ടാൽ ആ ബാക്കപ്പ് ഒരിക്കലും പുനഃസ്ഥാപിക്കാനാവില്ല.",
        "This backup is password-protected. Enter the password it was created with." to "ഈ ബാക്കപ്പ് പാസ്‌വേഡ് ഉപയോഗിച്ച് സംരക്ഷിച്ചിരിക്കുന്നു. അത് സൃഷ്ടിച്ച അതേ പാസ്‌വേഡ് നൽകുക.",
        "Try Smart Health Lens" to "സ്മാർട്ട് ഹെൽത്ത് ലെൻസ് പരീക്ഷിക്കുക",
        "Welcome" to "സ്വാഗതം",
        "Without one, anyone who gets the backup file can open it" to "അതില്ലെങ്കിൽ, ബാക്കപ്പ് ഫയൽ കിട്ടുന്ന ആർക്കും അത് തുറക്കാം",
        "Your Profile" to "നിങ്ങളുടെ പ്രൊഫൈൽ",
        "➕ Add family member" to "➕ കുടുംബാംഗത്തെ ചേർക്കുക"
    )

