        "Search test name, patient..." to "ପରୀକ୍ଷା ନାମ, ରୋଗୀ ସନ୍ଧାନ କରନ୍ତୁ...",
        "Searching Unified Health Interface (UHI) registry for real-time open network listings." to "ରିଅଲ-ଟାଇମ ଓପନ ନେଟୱାର୍କ ତାଲିକା ପାଇଁ ୟୁନିଫାଏଡ୍ ହେଲ୍ଥ ଇଣ୍ଟରଫେସ୍ (UHI) ରେଜିଷ୍ଟ୍ରି ସନ୍ଧାନ ହେଉଛି।",
        "Searching nearby centers..." to "ନିକଟସ୍ଥ କେନ୍ଦ୍ର ସନ୍ଧାନ ହେଉଛି...",
        "Secondary: Custom Key" to "ଦ୍ୱିତୀୟ: କଷ୍ଟମ କି",
        "Secure App Password" to "ସୁରକ୍ଷିତ ଆପ୍ ପାସୱାର୍ଡ",
        "Secure Medical Report Analyzer" to "ସୁରକ୍ଷିତ ମେଡିକାଲ୍ ରିପୋର୍ଟ ବିଶ୍ଳେଷକ",
        "See it in action" to "ଏହାକୁ କାର୍ଯ୍ୟରେ ଦେଖନ୍ତୁ",
