        "Sends just what changed since last time" to "ଶେଷ ଥର ପରଠାରୁ ଯାହା ପରିବର୍ତ୍ତନ ହୋଇଛି ତାହା ହିଁ ପଠାଏ",
        "Server Settings" to "ସର୍ଭର ସେଟିଂସ",
        "Server address, language, voice, backups" to "ସର୍ଭର ଠିକଣା, ଭାଷା, ସ୍ୱର, ବ୍ୟାକଅପ୍",
