        "Share" to "ସେୟାର କରନ୍ତୁ",
        "Share brief" to "ସାରାଂଶ ସେୟାର କରନ୍ତୁ",
        "Share on WhatsApp" to "WhatsApp ରେ ସେୟାର କରନ୍ତୁ",
        "Share with Doctor" to "ଡାକ୍ତରଙ୍କ ସହିତ ସେୟାର କରନ୍ତୁ",
        "Side Effects" to "ପାର୍ଶ୍ୱ ପ୍ରତିକ୍ରିୟା",
        "Sign In" to "ସାଇନ୍ ଇନ୍ କରନ୍ତୁ",
        "Sign In with Google" to "Google ସହିତ ସାଇନ୍ ଇନ୍ କରନ୍ତୁ",
        "Sign in quickly using fingerprint" to "ଆଙ୍ଗୁଠି ଚିହ୍ନ ବ୍ୟବହାର କରି ଶୀଘ୍ର ସାଇନ୍ ଇନ୍ କରନ୍ତୁ",
        "Signing in gives you your own free daily AI usage allowance, separate from other users of this app." to "ସାଇନ୍ ଇନ୍ କରିବା ଆପଣଙ୍କୁ ଏହି ଆପ୍ ର ଅନ୍ୟ ବ୍ୟବହାରକାରୀଙ୍କଠାରୁ ଅଲଗା ଆପଣଙ୍କର ନିଜସ୍ୱ ମାଗଣା ଦୈନିକ AI ବ୍ୟବହାର ଭତ୍ତା ଦିଏ।",
        "Skip & Mark Read" to "ଛାଡନ୍ତୁ ଏବଂ ପଢ଼ାଯାଇଛି ବୋଲି ଚିହ୍ନଟ କରନ୍ତୁ",
        "Smart Health Lens" to "ସ୍ମାର୍ଟ ହେଲ୍ଥ ଲେନ୍ସ",
        "Something went wrong. Check your connection and try again." to "କିଛି ଭୁଲ ହେଲା। ଆପଣଙ୍କ ସଂଯୋଗ ଯାଞ୍ଚ କରି ପୁନର୍ବାର ଚେଷ୍ଟା କରନ୍ତୁ।",
        "Speak" to "କୁହନ୍ତୁ",
        "Special Patient Notes" to "ବିଶେଷ ରୋଗୀ ଟିପ୍ପଣୀ",
        "Start Date (YYYY-MM-DD)" to "ଆରମ୍ଭ ତାରିଖ (YYYY-MM-DD)",
        "Stores the file without using AI — no API calls. You can analyze it anytime from its details." to "AI ବ୍ୟବହାର ନକରି ଫାଇଲ୍ ଷ୍ଟୋର୍ କରେ — କୌଣସି API କଲ୍ ନାହିଁ। ଆପଣ ଏହାର ବିବରଣୀରୁ ଯେକୌଣସି ସମୟରେ ବିଶ୍ଳେଷଣ କରିପାରିବେ।",
        "Successfully initiated booking request for:" to "ଏଥି ପାଇଁ ବୁକିଂ ଅନୁରୋଧ ସଫଳତାର ସହ ଆରମ୍ଭ ହେଲା:",
        "Switch Profile" to "ପ୍ରୋଫାଇଲ ବଦଳାନ୍ତୁ",
        "Sync Now" to "ବର୍ତ୍ତମାନ ସିଙ୍କ କରନ୍ତୁ",
        "System" to "ସିଷ୍ଟମ୍",
        "T" to "T",
        "Tap Settings → allow exact alarms so reminders arrive at the precise time." to "ରିମାଇଣ୍ଡର ସଠିକ୍ ସମୟରେ ଆସିବାକୁ ସେଟିଂସ → ସଠିକ୍ ଆଲାରାମକୁ ଅନୁମତି ଦିଅନ୍ତୁ ଟାପ୍ କରନ୍ତୁ।",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ଡାକ୍ତର ପରିଦର୍ଶନ କିମ୍ବା ଯାଞ୍ଚ ସୂଚୀତ କରିବାକୁ ଉପରେ \"ଆପଏଣ୍ଟମେଣ୍ଟ ଯୋଡନ୍ତୁ\" ଟାପ୍ କରନ୍ତୁ। ଏହା ଦେୟ ହେବା ପୂର୍ବରୁ ଆପଣଙ୍କୁ ମନେ ପକାଇ ଦିଆଯିବ।",
        "Tap a medicine to expand" to "ବିସ୍ତାର କରିବାକୁ ଏକ ଔଷଧରେ ଟାପ୍ କରନ୍ତୁ",
        "Tap any point to open that report" to "ସେହି ରିପୋର୍ଟ ଖୋଲିବାକୁ ଯେକୌଣସି ବିନ୍ଦୁରେ ଟାପ୍ କରନ୍ତୁ",
        "Tap here to select an image, PDF or doc from your device, or use Camera below to snap a photo." to "ଆପଣଙ୍କ ଡିଭାଇସରୁ ପ୍ରତିଛବି, PDF କିମ୍ବା ଡକ୍ ବାଛିବାକୁ ଏଠାରେ ଟାପ୍ କରନ୍ତୁ, କିମ୍ବା ଫଟୋ ନେବାକୁ ତଳେ କ୍ୟାମେରା ବ୍ୟବହାର କରନ୍ତୁ।",
        "Tap play to hear this summary" to "ଏହି ସାରାଂଶ ଶୁଣିବାକୁ ପ୍ଲେ ଟାପ୍ କରନ୍ତୁ",
        "Tap to allow so medicine reminders show on your phone and paired watch." to "ଔଷଧ ରିମାଇଣ୍ଡର ଆପଣଙ୍କ ଫୋନ୍ ଓ ଯୋଡି ହୋଇଥିବା ୱାଚ୍ ରେ ଦେଖାଇବାକୁ ଅନୁମତି ଦେବାକୁ ଟାପ୍ କରନ୍ତୁ।",
        "Tap to pick\nImage or PDF" to "ବାଛିବାକୁ ଟାପ୍ କରନ୍ତୁ\nପ୍ରତିଛବି କିମ୍ବା PDF",
        "Tap to select" to "ବାଛିବାକୁ ଟାପ୍ କରନ୍ତୁ",
        "Tap to view" to "ଦେଖିବାକୁ ଟାପ୍ କରନ୍ତୁ",
        "Test Parameter Changes" to "ପରୀକ୍ଷା ପାରାମିଟର ପରିବର୍ତ୍ତନ",
        "Test group" to "ପରୀକ୍ଷା ଗୋଷ୍ଠୀ",
        "Tested Parameters" to "ପରୀକ୍ଷିତ ପାରାମିଟର",
        "Tests recommended in prescriptions are automatically tracked. You can also add them manually." to "ପ୍ରେସକ୍ରିପସନରେ ସୁପାରିଶ କରାଯାଇଥିବା ପରୀକ୍ଷା ସ୍ୱୟଂଚାଳିତ ଭାବରେ ଟ୍ରାକ୍ ହୁଏ। ଆପଣ ସେଗୁଡ଼ିକୁ ମାନୁଆଲ୍ ଭାବରେ ମଧ୍ୟ ଯୋଡିପାରିବେ।",
        "That QR code doesn't contain a report link." to "ସେହି QR କୋଡ୍ ରେ କୌଣସି ରିପୋର୍ଟ ଲିଙ୍କ ନାହିଁ।",
        "The facility will confirm your slot via SMS/WhatsApp within 10 minutes." to "ସୁବିଧା 10 ମିନିଟ୍ ମଧ୍ୟରେ SMS/WhatsApp ମାଧ୍ୟମରେ ଆପଣଙ୍କ ସ୍ଲଟକୁ ନିଶ୍ଚିତ କରିବ।",
        "The selected files are very large (%.2f MB). Processing these files will take longer and might cause memory issues. We recommend keeping files under 10 MB. Do you want to proceed anyway?" to "ଚୟନ କରାଯାଇଥିବା ଫାଇଲଗୁଡ଼ିକ ବହୁତ ବଡ଼ (%.2f MB)। ଏହି ଫାଇଲଗୁଡ଼ିକୁ ପ୍ରକ୍ରିୟାକରଣ କରିବାରେ ଅଧିକ ସମୟ ଲାଗିବ ଏବଂ ମେମୋରୀ ସମସ୍ୟା ହୋଇପାରେ। ଆମେ ଫାଇଲଗୁଡ଼ିକୁ 10 MB ରୁ କମ୍ ରଖିବାକୁ ସୁପାରିଶ କରୁ। ଆପଣ ତଥାପି ଆଗକୁ ବଢ଼ିବାକୁ ଚାହାଁନ୍ତି କି?",
        "This isn't real. Remove it, or sign in to start tracking your own records." to "ଏହା ପ୍ରକୃତ ନୁହେଁ। ଏହାକୁ ହଟାନ୍ତୁ, କିମ୍ବା ଆପଣଙ୍କ ନିଜସ୍ୱ ରେକର୍ଡ ଟ୍ରାକ୍ କରିବା ଆରମ୍ଭ କରିବାକୁ ସାଇନ୍ ଇନ୍ କରନ୍ତୁ।",
        "This permanently deletes ALL reports, medicines, pending tests and images. This cannot be undone." to "ଏହା ସମସ୍ତ ରିପୋର୍ଟ, ଔଷଧ, ବକେୟା ପରୀକ୍ଷା ଏବଂ ପ୍ରତିଛବିକୁ ସ୍ଥାୟୀ ଭାବରେ ଡିଲିଟ୍ କରେ। ଏହା ପୂର୍ବବତ୍ କରାଯାଇପାରିବ ନାହିଁ।",
        "This re-runs AI analysis on the originally scanned image and refreshes the extracted test values, medicines and insights below. Useful if the earlier scan came back incomplete (e.g. the API was briefly unavailable). It may use some of your API quota." to "ଏହା ମୂଳ ସ୍କାନ ହୋଇଥିବା ପ୍ରତିଛବି ଉପରେ AI ବିଶ୍ଳେଷଣକୁ ପୁନର୍ବାର ଚଲାଏ ଏବଂ ତଳେ ଥିବା ବାହାର କରାଯାଇଥିବା ପରୀକ୍ଷା ମୂଲ୍ୟ, ଔଷଧ ଓ ଅନ୍ତର୍ଦୃଷ୍ଟିକୁ ରିଫ୍ରେସ କରେ। ପୂର୍ବ ସ୍କାନ ଅସମ୍ପୂର୍ଣ୍ଣ ଆସିଥିଲେ (ଯଥା API କିଛି ସମୟ ପାଇଁ ଅନୁପଲବ୍ଧ ଥିଲା) ଏହା ଉପଯୋଗୀ। ଏହା ଆପଣଙ୍କ କିଛି API କୋଟା ବ୍ୟବହାର କରିପାରେ।",
        "This report's file is saved but hasn't been analyzed by AI, so it has no test values, trends or insights yet. Analyze it whenever you're ready (uses some API quota)." to "ଏହି ରିପୋର୍ଟର ଫାଇଲ୍ ସେଭ୍ ହୋଇଛି କିନ୍ତୁ AI ଦ୍ୱାରା ବିଶ୍ଳେଷଣ ହୋଇ ନାହିଁ, ତେଣୁ ଏଥିରେ ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ପରୀକ୍ଷା ମୂଲ୍ୟ, ଟ୍ରେଣ୍ଡ କିମ୍ବା ଅନ୍ତର୍ଦୃଷ୍ଟି ନାହିଁ। ଆପଣ ପ୍ରସ୍ତୁତ ହେଲେ ଏହାକୁ ବିଶ୍ଳେଷଣ କରନ୍ତୁ (କିଛି API କୋଟା ବ୍ୟବହାର କରେ)।",
        "Time (HH:MM)" to "ସମୟ (HH:MM)",
        "Tip: 1-0-1 = morning & night, 1-1-1 = three times a day." to "ଟିପ୍ସ: 1-0-1 = ସକାଳ ଓ ରାତି, 1-1-1 = ଦିନକୁ ତିନିଥର।",
        "Tips" to "ଟିପ୍ସ",
        "To" to "କୁ",
        "Today's free pool quota is used up. Add a personal API key below for unlimited scans, or wait until tomorrow." to "ଆଜିର ମାଗଣା ପୁଲ୍ କୋଟା ସରିଗଲା। ଅସୀମିତ ସ୍କାନ ପାଇଁ ତଳେ ଏକ ବ୍ୟକ୍ତିଗତ API କି ଯୋଡନ୍ତୁ, କିମ୍ବା ଆସନ୍ତାକାଲି ପର୍ଯ୍ୟନ୍ତ ଅପେକ୍ଷା କରନ୍ତୁ।",
        "Toggle" to "ଟୋଗଲ୍ କରନ୍ତୁ",
        "Toggle text" to "ଟୋଗଲ୍ ପାଠ୍ୟ",
        "Transfer Records" to "ରେକର୍ଡ ସ୍ଥାନାନ୍ତର କରନ୍ତୁ",
        "Translates this intent using AI to target specific lab emails." to "ନିର୍ଦ୍ଦିଷ୍ଟ ଲ୍ୟାବ୍ ଇମେଲକୁ ଲକ୍ଷ୍ୟ କରିବାକୁ AI ବ୍ୟବହାର କରି ଏହି ଉଦ୍ଦେଶ୍ୟକୁ ଅନୁବାଦ କରେ।",
        "Trend" to "ଟ୍ରେଣ୍ଡ",
        "Trends Overview" to "ଟ୍ରେଣ୍ଡ ସମୀକ୍ଷା",
