        "Couldn't reach the assistant. Check that the server is running and configured in settings." to "ସହାୟକ ପାଖରେ ପହଞ୍ଚିହେଲା ନାହିଁ। ସର୍ଭର ଚାଲୁଛି ଏବଂ ସେଟିଂସରେ କନଫିଗର ହୋଇଛି ଯାଞ୍ଚ କରନ୍ତୁ।",
        "Voice input isn't available on this device. Please install/enable Google voice typing." to "ଏହି ଡିଭାଇସରେ ଭଏସ୍ ଇନପୁଟ୍ ଉପଲବ୍ଧ ନାହିଁ। ଦୟାକରି Google ଭଏସ୍ ଟାଇପିଂ ଇନଷ୍ଟଲ୍/ସକ୍ଷମ କରନ୍ତୁ।",
