        "Failed to fetch records. Make sure your local server is running and configured correctly in settings." to "ରେକର୍ଡ ପାଇବାରେ ବିଫଳ। ଆପଣଙ୍କ ସ୍ଥାନୀୟ ସର୍ଭର ଚାଲୁଛି ଏବଂ ସେଟିଂସରେ ସଠିକ୍ ଭାବରେ କନଫିଗର ହୋଇଛି ନିଶ୍ଚିତ କରନ୍ତୁ।",
        "Failed to fetch reminders. Make sure your local server is running and configured correctly in settings." to "ରିମାଇଣ୍ଡର ପାଇବାରେ ବିଫଳ। ଆପଣଙ୍କ ସ୍ଥାନୀୟ ସର୍ଭର ଚାଲୁଛି ଏବଂ ସେଟିଂସରେ ସଠିକ୍ ଭାବରେ କନଫିଗର ହୋଇଛି ନିଶ୍ଚିତ କରନ୍ତୁ।",
