        "Failed to delete report." to "ରିପୋର୍ଟ ଡିଲିଟ୍ କରିବାରେ ବିଫଳ।",
        "Couldn't reprocess: report or its scanned image is missing." to "ପୁନଃପ୍ରକ୍ରିୟା ହୋଇପାରିଲା ନାହିଁ: ରିପୋର୍ଟ କିମ୍ବା ଏହାର ସ୍କାନ ହୋଇଥିବା ପ୍ରତିଛବି ନାହିଁ।",
        "Failed to reprocess this report." to "ଏହି ରିପୋର୍ଟକୁ ପୁନଃପ୍ରକ୍ରିୟା କରିବାରେ ବିଫଳ।",
        "Medicine name is required." to "ଔଷଧ ନାମ ଆବଶ୍ୟକ।",
        "Select at least one reminder slot." to "ସର୍ବନିମ୍ନ ଏକ ରିମାଇଣ୍ଡର ସ୍ଲଟ ବାଛନ୍ତୁ।",
        "Doctor name is required." to "ଡାକ୍ତରଙ୍କ ନାମ ଆବଶ୍ୟକ।",
        "Place is required." to "ସ୍ଥାନ ଆବଶ୍ୟକ।",
        "Date is required." to "ତାରିଖ ଆବଶ୍ୟକ।",
        "This device's secure hardware storage is unavailable, so your local records key and linked-email credentials are stored without hardware-backed encryption. Your data still isn't sent anywhere insecurely, but this device offers weaker protection than usual." to "ଏହି ଡିଭାଇସର ସୁରକ୍ଷିତ ହାର୍ଡୱେର ଷ୍ଟୋରେଜ୍ ଉପଲବ୍ଧ ନାହିଁ, ତେଣୁ ଆପଣଙ୍କ ସ୍ଥାନୀୟ ରେକର୍ଡ କି ଏବଂ ଲିଙ୍କ ହୋଇଥିବା-ଇମେଲ୍ କ୍ରେଡେନସିଆଲ୍ ହାର୍ଡୱେର-ସମର୍ଥିତ ଏନକ୍ରିପସନ ବିନା ସଂରକ୍ଷିତ। ଆପଣଙ୍କ ଡାଟା ତଥାପି ଅସୁରକ୍ଷିତ ଭାବରେ କେଉଁଠିକୁ ପଠାଯାଏ ନାହିଁ, କିନ୍ତୁ ଏହି ଡିଭାଇସ୍ ସାଧାରଣ ଠାରୁ ଦୁର୍ବଳ ସୁରକ୍ଷା ଦିଏ।",
        "Scanning, reminders, and everything else work fully on this device without signing in. Sign-in is optional (it sends an SMS code, so it isn't automatic) — use it if you want a profile or a personal API key that follows you across devices." to "ସ୍କାନିଂ, ରିମାଇଣ୍ଡର ଏବଂ ବାକି ସବୁକିଛି ଏହି ଡିଭାଇସରେ ସାଇନ୍ ଇନ୍ ନକରି ସମ୍ପୂର୍ଣ୍ଣ ଭାବରେ କାର୍ଯ୍ୟ କରେ। ସାଇନ୍ ଇନ୍ ଇଚ୍ଛାଧୀନ (ଏହା SMS କୋଡ୍ ପଠାଏ, ତେଣୁ ଏହା ସ୍ୱୟଂଚାଳିତ ନୁହେଁ) — ଡିଭାଇସଗୁଡ଼ିକରେ ଆପଣଙ୍କ ସହିତ ରହୁଥିବା ପ୍ରୋଫାଇଲ୍ କିମ୍ବା ବ୍ୟକ୍ତିଗତ API କି ଚାହାଁନ୍ତି ତେବେ ଏହା ବ୍ୟବହାର କରନ୍ତୁ।",
        "The unit every trend chart standardises readings to. Reports in a different unit are converted automatically; each report still shows its original value." to "ପ୍ରତ୍ୟେକ ଟ୍ରେଣ୍ଡ ଚାର୍ଟ ଯେଉଁ ୟୁନିଟରେ ରିଡିଂକୁ ମାନକୀକରଣ କରେ। ଭିନ୍ନ ୟୁନିଟର ରିପୋର୍ଟ ସ୍ୱୟଂଚାଳିତ ଭାବରେ ପରିବର୍ତ୍ତିତ ହୁଏ; ପ୍ରତ୍ୟେକ ରିପୋର୍ଟ ତଥାପି ଏହାର ମୂଳ ମୂଲ୍ୟ ଦେଖାଏ।",
        "Why: Health Decoder stays free by keeping costs low, not by selling your records. If you opt in here, only your age and sex — never your name, reports, or exact location — would be shared in aggregate with medical research institutes, to help fund keeping the app free for every family instead of running ads or charging a subscription." to "କାହିଁକି: Health Decoder ଖର୍ଚ୍ଚ କମ୍ ରଖି ମାଗଣା ରୁହେ, ଆପଣଙ୍କ ରେକର୍ଡ ବିକ୍ରି କରି ନୁହେଁ। ଆପଣ ଏଠାରେ ଯୋଗ ଦେଲେ, କେବଳ ଆପଣଙ୍କ ବୟସ ଏବଂ ଲିଙ୍ଗ — କେବେ ବି ଆପଣଙ୍କ ନାମ, ରିପୋର୍ଟ, କିମ୍ବା ସଠିକ୍ ଅବସ୍ଥାନ ନୁହେଁ — ଚିକିତ୍ସା ଗବେଷଣା ପ୍ରତିଷ୍ଠାନ ସହିତ ସାମଗ୍ରିକ ଭାବରେ ସେୟାର କରାଯିବ, ଯାହା ଫଳରେ ବିଜ୍ଞାପନ ଚଲାଇବା କିମ୍ବା ସବସ୍କ୍ରିପସନ ନେବା ପରିବର୍ତ୍ତେ ଆପ୍ କୁ ପ୍ରତ୍ୟେକ ପରିବାର ପାଇଁ ମାଗଣା ରଖିବାରେ ସାହାଯ୍ୟ ମିଳେ।",
        "This program hasn't launched yet — turning this on today only saves your preference. Nothing is sent anywhere until a real data-sharing pipeline exists, and you can change your answer here at any time." to "ଏହି କାର୍ଯ୍ୟକ୍ରମ ଏପର୍ଯ୍ୟନ୍ତ ଆରମ୍ଭ ହୋଇ ନାହିଁ — ଆଜି ଏହାକୁ ଅନ୍ କରିବା କେବଳ ଆପଣଙ୍କ ପସନ୍ଦକୁ ସେଭ୍ କରେ। ପ୍ରକୃତ ଡାଟା-ସେୟାରିଂ ପାଇପଲାଇନ୍ ଅସ୍ତିତ୍ୱରେ ନ ଆସିବା ପର୍ଯ୍ୟନ୍ତ କିଛି ବି କେଉଁଠିକୁ ପଠାଯାଏ ନାହିଁ, ଏବଂ ଆପଣ ଯେକୌଣସି ସମୟରେ ଏଠାରେ ଆପଣଙ୍କ ଉତ୍ତର ବଦଳାଇ ପାରିବେ।",
        "This permanently deletes your Health Decoder account AND all medical records stored on this device — reports, reminders, appointments, and family profiles. This cannot be undone." to "ଏହା ଆପଣଙ୍କ Health Decoder ଖାତା ଏବଂ ଏହି ଡିଭାଇସରେ ସଂରକ୍ଷିତ ସମସ୍ତ ମେଡିକାଲ୍ ରେକର୍ଡ — ରିପୋର୍ଟ, ରିମାଇଣ୍ଡର, ଆପଏଣ୍ଟମେଣ୍ଟ, ଏବଂ ପରିବାର ପ୍ରୋଫାଇଲ — ସ୍ଥାୟୀ ଭାବରେ ଡିଲିଟ୍ କରେ। ଏହା ପୂର୍ବବତ୍ କରାଯାଇପାରିବ ନାହିଁ।",
        "is prescribed, plus key tips. The first lookup uses the internet, then it's saved so it opens instantly next time." to "ନିର୍ଦ୍ଦିଷ୍ଟ କରାଯାଏ, ସହିତ ମୁଖ୍ୟ ଟିପ୍ସ। ପ୍ରଥମ ସନ୍ଧାନ ଇଣ୍ଟରନେଟ୍ ବ୍ୟବହାର କରେ, ତାପରେ ଏହା ସେଭ୍ ହୁଏ ଯାହା ଫଳରେ ପରବର୍ତ୍ତୀ ଥର ତୁରନ୍ତ ଖୁଲିଯାଏ।",
        "with example reports, reminders and an appointment already filled in, so you can explore every screen before you scan anything real. Remove it any time from Account." to "ଉଦାହରଣ ରିପୋର୍ଟ, ରିମାଇଣ୍ଡର ଏବଂ ପୂର୍ବରୁ ପୂରଣ ହୋଇଥିବା ଆପଏଣ୍ଟମେଣ୍ଟ ସହିତ, ଯାହା ଫଳରେ ଆପଣ ପ୍ରକୃତ କିଛି ସ୍କାନ କରିବା ପୂର୍ବରୁ ପ୍ରତ୍ୟେକ ସ୍କ୍ରିନ ଅନୁସନ୍ଧାନ କରିପାରିବେ। ଖାତାରୁ ଏହାକୁ ଯେକୌଣସି ସମୟରେ ହଟାନ୍ତୁ।",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ସେହି QR ଏକ ୱେବ୍ ପୃଷ୍ଠା ଖୋଲିଲା, ସିଧାସଳଖ ଫାଇଲ୍ ନୁହେଁ। ଏହାକୁ ଆପଣଙ୍କ ବ୍ରାଉଜରରେ ଖୋଲାଯାଉଛି — ସେଠାରେ ରିପୋର୍ଟ ଡାଉନଲୋଡ୍ କରନ୍ତୁ, ତାପରେ ଏହାକୁ ଇମ୍ପୋର୍ଟ କରିବାକୁ \"ଡିଭାଇସରୁ\" ବ୍ୟବହାର କରନ୍ତୁ।",
        // --- UI chrome added by the missing-translations audit ---
        "%1\$d multi-page scan(s) were processed before a fix to how large documents are split for analysis — a panel from the same document (e.g. an electrolytes or PT/INR page) may be missing. This re-checks them using the pages already stored and adds anything that was missed; anything already saved is left alone." to "ବଡ଼ ଡକ୍ୟୁମେଣ୍ଟଗୁଡ଼ିକୁ ବିଶ୍ଳେଷଣ ପାଇଁ ବିଭାଜନ କରିବା ପଦ୍ଧତିରେ ସଂଶୋଧନ ହେବା ପୂର୍ବରୁ %1\$d ବହୁ-ପୃଷ୍ଠା ସ୍କାନ ପ୍ରକ୍ରିୟାକରଣ ହୋଇଥିଲା — ସେହି ଡକ୍ୟୁମେଣ୍ଟର କୌଣସି ପ୍ୟାନେଲ (ଯେମିତି ଇଲେକ୍ଟ୍ରୋଲାଇଟ୍ କିମ୍ବା PT/INR ପୃଷ୍ଠା) ବାଦ ପଡ଼ିଥାଇପାରେ। ଏହା ପୂର୍ବରୁ ସଞ୍ଚିତ ପୃଷ୍ଠାଗୁଡ଼ିକ ବ୍ୟବହାର କରି ପୁଣି ଯାଞ୍ଚ କରେ ଏବଂ ଯାହା ବାଦ ପଡ଼ିଥିଲା ତାହା ଯୋଡ଼େ; ପୂର୍ବରୁ ସଞ୍ଚିତ ଥିବା ଯେମିତି ଅଛି ସେମିତି ରହେ।",
        "%1\$d report(s) were saved while the AI analysis server was unavailable (e.g. daily quota reached), so their date and category are guesses instead of read from the document. Re-analyzing uses the images already stored — no need to re-scan them yourself." to "AI ବିଶ୍ଳେଷଣ ସର୍ଭର ଉପଲବ୍ଧ ନଥିବା ସମୟରେ %1\$d ରିପୋର୍ଟ ସଞ୍ଚିତ ହୋଇଥିଲା (ଯେମିତି ଦୈନିକ କୋଟା ଶେଷ), ତେଣୁ ସେଗୁଡ଼ିକର ତାରିଖ ଏବଂ ଶ୍ରେଣୀ ଡକ୍ୟୁମେଣ୍ଟରୁ ପଢ଼ାଯାଇ ନାହିଁ, ଅନୁମାନ ମାତ୍ର। ପୁନଃବିଶ୍ଳେଷଣ ପୂର୍ବରୁ ସଞ୍ଚିତ ଛବିଗୁଡ଼ିକ ବ୍ୟବହାର କରେ — ଆପଣଙ୍କୁ ପୁଣି ସ୍କାନ କରିବାକୁ ପଡ଼ିବ ନାହିଁ।",
