        "Share / Merge Records" to "ରେକର୍ଡ ସେୟାର / ମର୍ଜ କରନ୍ତୁ",
        "Share / Merge sends a selection to another phone or a doctor and adds it to what's there. Backup & Restore is a full snapshot of this device that replaces everything when restored — use it for disaster recovery, not sharing." to "ସେୟାର / ମର୍ଜ ବଛା ତଥ୍ୟକୁ ଅନ୍ୟ ଫୋନ କିମ୍ବା ଡାକ୍ତରଙ୍କ ପାଖକୁ ପଠାଏ ଏବଂ ସେଠାରେ ଥିବା ସହିତ ଯୋଡ଼ିଦିଏ। ବ୍ୟାକଅପ ଓ ପୁନଃସ୍ଥାପନ ହେଉଛି ଏହି ଡିଭାଇସର ସମ୍ପୂର୍ଣ୍ଣ ସ୍ନାପସଟ ଯାହା ପୁନଃସ୍ଥାପନ ସମୟରେ ସବୁକିଛି ବଦଳାଇଦିଏ — ତେଣୁ ଏହାକୁ ସେୟାର ପାଇଁ ନୁହେଁ, ବିପର୍ଯ୍ୟୟ ପୁନରୁଦ୍ଧାର ପାଇଁ ବ୍ୟବହାର କରନ୍ତୁ।",
        "Sign in to edit your name and details, use a personal API key, and enable fingerprint login. The app works fully without it — your family members and records already live on this device." to "ଆପଣଙ୍କ ନାମ ଏବଂ ବିବରଣୀ ସମ୍ପାଦନା କରିବାକୁ, ବ୍ୟକ୍ତିଗତ API କୀ ବ୍ୟବହାର କରିବାକୁ ଏବଂ ଆଙ୍ଗୁଠି ଛାପ ଲଗଇନ ସକ୍ରିୟ କରିବାକୁ ସାଇନ ଇନ କରନ୍ତୁ। ଏହା ବିନା ମଧ୍ୟ ଆପ ସମ୍ପୂର୍ଣ୍ଣ କାମ କରେ — ଆପଣଙ୍କ ପରିବାର ସଦସ୍ୟ ଏବଂ ରେକର୍ଡ ପୂର୍ବରୁ ଏହି ଡିଭାଇସରେ ଅଛି।",
        "Sign in to sync your records" to "ଆପଣଙ୍କ ରେକର୍ଡ ସିଙ୍କ କରିବାକୁ ସାଇନ ଇନ କରନ୍ତୁ",
        "Skip this and the app uses a shared free pool by default. Adding your own key up front means you're never limited by that pool's daily cap." to "ଏହାକୁ ଛାଡ଼ିଦେଲେ ଆପ ଡିଫଲ୍ଟ ଭାବରେ ସହଭାଗୀ ମାଗଣା ପୁଲ ବ୍ୟବହାର କରେ। ନିଜର କୀ ଆଗରୁ ଯୋଡ଼ିଲେ ସେହି ପୁଲର ଦୈନିକ ସୀମା ଆପଣଙ୍କୁ କେବେ ଅଟକାଇବ ନାହିଁ।",
        "Sono" to "ସୋନୋ",
        "Starts" to "ଆରମ୍ଭ",
        "Tap \"Add Appointment\" above to schedule a doctor visit or check-up. You'll be reminded before it's due." to "ଡାକ୍ତରଙ୍କ ସାକ୍ଷାତ କିମ୍ବା ଚେକ-ଅପ ନିର୍ଦ୍ଧାରଣ କରିବାକୁ ଉପରେ \"ଆପଏଣ୍ଟମେଣ୍ଟ ଯୋଡ଼ନ୍ତୁ\" ଦବାନ୍ତୁ। ସମୟ ପୂର୍ବରୁ ଆପଣଙ୍କୁ ମନେ ପକାଇ ଦିଆଯିବ।",
        "Tap to pick\nImage or PDF" to "ବାଛିବାକୁ ଦବାନ୍ତୁ\nଛବି କିମ୍ବା PDF",
        "That QR opened a web page, not a direct file. Opening it in your browser — download the report there, then use \"From Device\" to import it." to "ସେହି QR ଏକ ୱେବ ପୃଷ୍ଠା ଖୋଲିଲା, ସିଧାସଳଖ ଫାଇଲ ନୁହେଁ। ଏହାକୁ ଆପଣଙ୍କ ବ୍ରାଉଜରରେ ଖୋଲାଯାଉଛି — ସେଠାରେ ରିପୋର୍ଟ ଡାଉନଲୋଡ କରନ୍ତୁ, ତାପରେ ଏହାକୁ ଇମ୍ପୋର୍ଟ କରିବାକୁ \"ଡିଭାଇସରୁ\" ବ୍ୟବହାର କରନ୍ତୁ।",
        "There's no way to reset this if you forget it — write it down somewhere safe." to "ଭୁଲିଗଲେ ଏହାକୁ ରିସେଟ କରିବାର କୌଣସି ଉପାୟ ନାହିଁ — ଏହାକୁ କେଉଁଠି ସୁରକ୍ଷିତ ଲେଖି ରଖନ୍ତୁ।",
        "There's no way to reset this if you forget it — write it down somewhere safe. A lost backup password means that backup can never be restored." to "ଭୁଲିଗଲେ ଏହାକୁ ରିସେଟ କରିବାର କୌଣସି ଉପାୟ ନାହିଁ — ଏହାକୁ କେଉଁଠି ସୁରକ୍ଷିତ ଲେଖି ରଖନ୍ତୁ। ବ୍ୟାକଅପ ପାସୱାର୍ଡ ହଜିଗଲେ ସେହି ବ୍ୟାକଅପ କେବେ ପୁନଃସ୍ଥାପନ ହୋଇପାରିବ ନାହିଁ।",
        "This backup is password-protected. Enter the password it was created with." to "ଏହି ବ୍ୟାକଅପ ପାସୱାର୍ଡ ଦ୍ୱାରା ସୁରକ୍ଷିତ। ଯେଉଁ ପାସୱାର୍ଡରେ ଏହା ତିଆରି ହୋଇଥିଲା ସେହିଟି ଦିଅନ୍ତୁ।",
        "Try Smart Health Lens" to "ସ୍ମାର୍ଟ ହେଲଥ ଲେନ୍ସ ଚେଷ୍ଟା କରନ୍ତୁ",
        "Welcome" to "ସ୍ୱାଗତ",
        "Without one, anyone who gets the backup file can open it" to "ଏହା ବିନା, ବ୍ୟାକଅପ ଫାଇଲ ପାଇଥିବା ଯେକେହି ଏହାକୁ ଖୋଲିପାରିବ",
        "Your Profile" to "ଆପଣଙ୍କ ପ୍ରୋଫାଇଲ",
        "➕ Add family member" to "➕ ପରିବାର ସଦସ୍ୟ ଯୋଡ଼ନ୍ତୁ"
    )

    private val byLanguage: Map<String, Map<String, String>> = mapOf(
        "Hindi" to hindi,
        "Marathi" to marathi,
        "Gujarati" to gujarati,
        "Tamil" to tamil,
        "Telugu" to telugu,
        "Kannada" to kannada,
        "Bengali" to bengali,
        "Punjabi" to punjabi,
        "Malayalam" to malayalam,
        "Odia" to odia
    )

    /** Returns the translation if this exact string is in the language's map, else null (caller falls back to English). */
    fun lookup(language: String, text: String): String? = byLanguage[language]?.get(text)
}
